class SupabaseService {
  final SupabaseClient _client = Supabase.instance.client;
  static const String _bucketName = 'photos'; // Le nom de votre bucket
  Future<void> deleteGameFolder(String gameCode) async {
    try {
      final List<FileObject> objects = await _client.storage
          .from(_bucketName)
          .list(path: gameCode);

      if (objects.isEmpty) return;

      final List<String> pathsToDelete =
          objects.map((obj) => '$gameCode/${obj.name}').toList();

      await _client.storage.from(_bucketName).remove(pathsToDelete);

      print('Dossier de jeu $gameCode supprimÃƒÂ© avec succÃƒÂ¨s.');
    } catch (e) {
      print('Erreur lors du nettoyage Supabase : $e');
    }
  }

  Future<String?> uploadImageBytes(
    Uint8List imageBytes,
    String gameCode,
  ) async {
    int maxRetries = 3;
    for (int attempt = 1; attempt <= maxRetries; attempt++) {
      try {
        print(
          '--- [Supabase Upload] Tentative $attempt/$maxRetries pour la partie $gameCode ---',
        );
        final String fileName = '${const Uuid().v4()}.jpg';
        final String path = '$gameCode/$fileName';

        await _client.storage
            .from(_bucketName)
            .uploadBinary(
              path,
              imageBytes,
              fileOptions: const FileOptions(
                cacheControl: '3600',
                upsert: false,
              ),
            );

        final String publicUrl = _client.storage
            .from(_bucketName)
            .getPublicUrl(path);

        print(
          '--- [Supabase Upload] SuccÃ¨s (Tentative $attempt) : $publicUrl ---',
        );
        return publicUrl;
      } catch (e, stackTrace) {
        print(
          '--- [Supabase Upload] ERREUR (Tentative $attempt/$maxRetries) ---',
        );
        print('Erreur: $e');
        if (attempt == maxRetries) {
          print('--- [Supabase Upload] ECHEC DÃ‰FINITIF ---');
          return null;
        }
        // Attente avant de rÃ©essayer (permet aux sockets de se libÃ©rer)
        await Future.delayed(Duration(seconds: 2));
      }
    }
    return null;
  }

  Future<String?> uploadImage(File imageFile, String gameCode) async {
    try {
      final String fileName = '${const Uuid().v4()}.jpg';
      final String path = '$gameCode/$fileName';

      await _client.storage
          .from(_bucketName)
          .upload(
            path,
            imageFile,
            fileOptions: const FileOptions(cacheControl: '3600', upsert: false),
          );

      final String publicUrl = _client.storage
          .from(_bucketName)
          .getPublicUrl(path);

      print('Upload rÃƒÂ©ussi: $publicUrl');
      return publicUrl;
    } on StorageException catch (e) {
      print('--- ERREUR SUPABASE (StorageException) ---');
      print('Message: ${e.message}');
      print('StatusCode: ${e.statusCode}');
      print('Error: ${e.error}');
      print('-----------------------------------------');
      return null;
    } catch (e, stackTrace) {
      print('--- ERREUR INATTENDUE LORS DE L\'UPLOAD ---');
      print('Type d\'erreur: ${e.runtimeType}');
      print('Erreur: $e');
      print('StackTrace: $stackTrace');
      print('-------------------------------------------');
      return null;
    }
  }
}

