};

String _getPresidentCardRank(String card) => card.substring(0, card.length - 1);

int _getPresidentCardValue(String card, bool isRevolutionActive) {
  final rank = _getPresidentCardRank(card);
  if (isRevolutionActive) {
    return _presidentCardValuesRevolution[rank]!;
  }
  return _presidentCardValues[rank]!;
}

int _comparePresidentCards(String a, String b, bool isRevolutionActive) =>
    _getPresidentCardValue(
      a,
      isRevolutionActive,
    ).compareTo(_getPresidentCardValue(b, isRevolutionActive));

