        break;
      case 'Just One':
        await nextJustOneRound(gameCode);
        break;
      case 'Skull':
        await nextSkullRound(gameCode);
        break;
      case 'Président':
        await nextPresidentRound(gameCode);
        break;

      default:
        await nextRound(gameCode);
        break;
    }
  }

