  Future<void> _checkForWinCondition(
    DocumentReference gameRef,
    Map<String, dynamic> gameData,
  ) async {
    final playerData = Map<String, dynamic>.from(gameData['playerData']);
    List<dynamic> vivants =
        playerData.values.where((p) => p['status'] == 'vivant').toList();
    if (vivants.isEmpty) return;

    String? winner;
    String? reason;

    int loupsVivants =
        vivants
            .where(
              (p) =>
                  GameData.roleCamps[p['role']] == 'loups' ||
                  p['infectionStatus'] == 'infecte',
            )
            .length;
    int villageoisVivants =
        vivants
            .where(
              (p) =>
                  (GameData.roleCamps[p['role']] == 'villageois' ||
                      GameData.roleCamps[p['role']] == 'special') &&
                  p['infectionStatus'] != 'infecte',
            )
            .length;

    int solitairesNonLoupsVivants =
        vivants
            .where(
              (p) =>
                  GameData.roleCamps[p['role']] == 'solitaire' &&
                  p['role'] != 'Loup Blanc',
            )
            .length;
    int loupBlancVivant =
        vivants.where((p) => p['role'] == 'Loup Blanc').length;

    int ratMaladeVivant =
        vivants.where((p) => p['role'] == 'Rat Malade').length;
    int contaminesVivants = vivants.where((p) => p['poisoned'] == true).length;
    List<String> lovers = List<String>.from(gameData['lovers'] ?? []);
    bool areLoversAlive =
        lovers.length == 2 &&
        vivants.any(
          (p) =>
              playerData.entries.firstWhere((e) => e.value == p).key ==
              lovers[0],
        ) &&
        vivants.any(
          (p) =>
              playerData.entries.firstWhere((e) => e.value == p).key ==
              lovers[1],
        );

    if (areLoversAlive) {
      var lover1 = playerData[lovers[0]];
      var lover2 = playerData[lovers[1]];
      bool isLover1WolfCamp =
          GameData.roleCamps[lover1['role']] == 'loups' ||
          lover1['infectionStatus'] == 'infecte';
      bool isLover2WolfCamp =
          GameData.roleCamps[lover2['role']] == 'loups' ||
          lover2['infectionStatus'] == 'infecte';
      if (isLover1WolfCamp != isLover2WolfCamp && vivants.length == 2) {
        winner = "Les Amoureux";
        reason =
            "Seuls les deux amoureux d'un camp opposÃƒÂ© sont encore en vie. Leur amour triomphe de tout !";
      }
    }

    if (winner == null && loupBlancVivant == 1 && vivants.length == 1) {
      winner = "Loup Blanc";
      reason =
          "Le Loup Blanc est le dernier survivant ! Il a dÃƒÂ©vorÃƒÂ© tout le monde.";
    }

    // Le Rat Malade gagne quand tous les AUTRES joueurs vivants sont contaminÃƒÂ©s (ou qu'il est le seul survivant)
    if (winner == null &&
        ratMaladeVivant > 0 &&
        contaminesVivants == vivants.length - ratMaladeVivant) {
      winner = "Rat Malade";
      reason =
          vivants.length == ratMaladeVivant
              ? "Le Rat Malade est le seul survivant ! Il a empoisonnÃƒÂ© tout le monde !"
              : "Tous les autres survivants sont contaminÃƒÂ©s par le Rat Malade. Il a gagnÃƒÂ© !";
    }

    if (winner == null &&
        loupsVivants > 0 &&
        loupsVivants >= (villageoisVivants + solitairesNonLoupsVivants)) {
      winner = "Loups-Garous";
      reason =
          "Les Loups-Garous sont devenus majoritaires, ils ne peuvent plus perdre. Ils ont gagnÃƒÂ© !";
    }

    if (winner == null &&
        loupsVivants == 0 &&
        solitairesNonLoupsVivants == 0 &&
        loupBlancVivant == 0 &&
        villageoisVivants > 0) {
      winner = "Villageois";
      reason =
          "Toutes les menaces ont ÃƒÂ©tÃƒÂ© ÃƒÂ©liminÃƒÂ©es ! Le village a gagnÃƒÂ© !";
    }

    if (winner != null) {
      await gameRef.update({
        'phase': 'gameOver',
        'gameLog': FieldValue.arrayUnion([
          "La partie est terminÃƒÂ©e. Victoire des ${winner} !",
          reason,
        ]),
      });
    }
  }

  static const List<String> nightPhaseOrder = [
    'cupidon_turn',
    'heritier_turn',
    'garde_turn',
    'voyante_turn',
    'rat_malade_turn',
    'loups_turn',
    'loup_blanc_turn',
    'sorciere_turn',
    'pyromancien_turn',
  ];

  bool _isPlayerForPhaseActive(
    String phase,
    Map<String, dynamic> gameData,
    Map<String, dynamic> playerData,
  ) {
    int nightNumber = gameData['nightNumber'] ?? 0;
    final nightActions = Map<String, dynamic>.from(
      gameData['nightActions'] ?? {},
    );

    bool isRoleAlive(String role) {
      return playerData.values.any(
        (p) => p['role'] == role && p['status'] == 'vivant',
      );
    }

    switch (phase) {
      case 'cupidon_turn':
        return nightNumber == 0 &&
            isRoleAlive('Cupidon') &&
            nightActions['cupidonActed'] != true;
      case 'heritier_turn':
        var heritier = playerData.entries.firstWhere(
          (e) => e.value['role'] == 'Héritier' && e.value['status'] == 'vivant',
          orElse: () => const MapEntry('', {}),
        );
        return nightNumber == 0 &&
            heritier.key.isNotEmpty &&
            heritier.value['testateurId'] == null;
      case 'garde_turn':
        return isRoleAlive('Garde') && nightActions['gardeActed'] != true;
      case 'voyante_turn':
        return isRoleAlive('Voyante') && nightActions['voyanteActed'] != true;
      case 'rat_malade_turn':
        return isRoleAlive('Rat Malade') &&
            nightActions['ratMaladeActed'] != true;
      case 'loups_turn':
        return playerData.values.any(
              (p) =>
                  (GameData.roleCamps[p['role']] == 'loups' ||
                      p['infectionStatus'] == 'infecte') &&
                  p['status'] == 'vivant',
            ) &&
            nightActions['loupsVoted'] != true;
      case 'loup_blanc_turn':
        return nightNumber > 0 &&
            nightNumber % 2 != 0 &&
            isRoleAlive('Loup Blanc') &&
            nightActions['loupBlancActed'] != true;
      case 'sorciere_turn':
        var sorciere = playerData.entries.firstWhere(
          (e) => e.value['role'] == 'Sorcière' && e.value['status'] == 'vivant',
          orElse: () => const MapEntry('', {}),
        );
        if (sorciere.key.isEmpty) return false;
        return nightActions['sorciereActed'] != true;
      case 'pyromancien_turn':
        return isRoleAlive('Pyromancien') &&
            nightActions['pyromancienActed'] != true;
      default:
        return false;
    }
  }

  Future<void> startNextNightPhase(String gameCode) async {
    for (int attempt = 0; attempt < 5; attempt++) {
      try {
        await _db.runTransaction((transaction) async {
          final gameRef = _db.collection('games').doc(gameCode);
          DocumentSnapshot gameSnap = await transaction.get(gameRef);
          if (!gameSnap.exists) return;

          var gameData = gameSnap.data() as Map<String, dynamic>;
          var playerData = Map<String, dynamic>.from(gameData['playerData']);
          String currentSubPhase = gameData['subPhase'];

          int currentPhaseIndex = nightPhaseOrder.indexOf(currentSubPhase);
          // 'loups_voted' or 'loup_noir_action' are sentinels set during wolf phase; treat as loups_turn
          if (currentSubPhase == 'loups_voted' ||
              currentSubPhase == 'loup_noir_action') {
            currentPhaseIndex = nightPhaseOrder.indexOf('loups_turn');
          }
          if (currentPhaseIndex == -1) currentPhaseIndex = -1;

          for (int i = currentPhaseIndex + 1; i < nightPhaseOrder.length; i++) {
            String nextPhase = nightPhaseOrder[i];
            if (_isPlayerForPhaseActive(nextPhase, gameData, playerData)) {
              transaction.update(gameRef, {
                'subPhase': nextPhase,
                'turnStartTime': FieldValue.serverTimestamp(),
              });
              return;
            }
          }

          await _startDayPhase(transaction, gameRef, gameData);
        });
        break; // Succès
      } catch (e) {
        if (attempt >= 4) rethrow;
        await Future.delayed(Duration(milliseconds: 150 * (attempt + 1)));
      }
    }

    final gameRef = _db.collection('games').doc(gameCode);
    final updatedGameData =
        (await gameRef.get()).data() as Map<String, dynamic>;
    await _checkForWinCondition(gameRef, updatedGameData);
  }

  /// Voyante : Découverte du rôle
  Future<void> voyanteSee(
    String gameCode,
    String voyanteId,
