  Future<void> startPetitsChevaux(
    DocumentReference gameRef,
    Map<String, dynamic> gameData,
  ) async {
    final players = Map<String, dynamic>.from(gameData['players']);
    final playerIds = players.keys.toList()..shuffle();

    // Protection : 2v2 nÃ©cessite 4 joueurs
    bool isTeamMode = gameData['petitsChevauxTeamMode'] ?? false;
    if (playerIds.length != 4) isTeamMode = false;

    Map<String, dynamic> positions = {};
    Map<String, int> consecutiveSixes = {};
    for (String pId in playerIds) {
      positions[pId] = [-1, -1, -1, -1];
      consecutiveSixes[pId] = 0;
    }

    await gameRef.update({
      'gameState': 'playing',
      'roundState': 'rolling',
      'petitsChevauxPositions': positions,
      'petitsChevauxPlayerOrder': playerIds,
      'petitsChevauxCurrentIndex': 0,
      'petitsChevauxDice': 0,
      'petitsChevauxHasRolled': false,
      'petitsChevauxTeamMode': isTeamMode, // On s'assure de l'enregistrer ici
      'petitsChevauxConsecutiveSixes': consecutiveSixes,
      'turnStartTime': FieldValue.serverTimestamp(),
      'gameLog': [
        isTeamMode ? "La partie 2v2 commence !" : "La partie commence !",
      ],
    });
  }

