  // --- LOGIQUE ZOMBIE! ---
  void _discardPairs(List<String> hand) {
    bool pairFound = true;
    while (pairFound) {
      pairFound = false;
      Map<String, int> rankCounts = {};
      for (String c in hand) {
        if (c == 'Zombie') continue;
        String rank = c.substring(0, 1);
        rankCounts[rank] = (rankCounts[rank] ?? 0) + 1;
      }

      for (var entry in rankCounts.entries) {
        if (entry.value >= 2) {
          int removed = 0;
          hand.removeWhere((c) {
            if (removed >= 2) return false;
            if (c != 'Zombie' && c.startsWith(entry.key)) {
              removed++;
              return true;
            }
            return false;
          });
          pairFound = true;
          break;
        }
      }
    }
  }

  Future<void> _startZombieRound(
    DocumentReference gameRef,
    Map<String, dynamic> gameData,
  ) async {
    final players = Map<String, dynamic>.from(gameData['players']);
    final playerIds = players.keys.toList()..shuffle();

    // Création du deck : 16 paires (8 rangs x 4 couleurs) + 1 Zombie
    List<String> deck = [];
    List<String> ranks = ['A', '2', '3', '4', '5', '6', '7', '8'];
    List<String> suits = ['H', 'D', 'C', 'S'];
    for (String r in ranks) {
      for (String s in suits) {
        deck.add('$r$s');
      }
    }
    deck.add('Zombie');
    deck.shuffle();

    Map<String, List<String>> hands = {};
    for (String pId in playerIds) hands[pId] = [];

    int i = 0;
    while (deck.isNotEmpty) {
      String pId = playerIds[i % playerIds.length];
      hands[pId]!.add(deck.removeAt(0));
      i++;
    }

    // Retirer immédiatement les paires de chaque main
    List<String> eliminatedPlayers = [];
    for (String pId in playerIds) {
      List<String> hand = hands[pId]!;
      _discardPairs(hand);
      hand.shuffle();
      hands[pId] = hand;
      if (hand.isEmpty) {
        eliminatedPlayers.add(pId);
      }
    }

    await gameRef.update({
      'gameState': 'playing',
      'roundState': 'playing_turn',
      'zombiePlayerOrder': playerIds,
      'zombiePlayerHands': hands,
      'zombieCurrentPlayerIndex': 0,
      'zombieEliminatedPlayers': eliminatedPlayers,
      'turnStartTime': FieldValue.serverTimestamp(),
      'gameLog': [
        "La partie de Zombie! commence ! Paires initiales défaussées.",
      ],
    });
  }

  Future<void> zombieTakeCard(
    String gameCode,
    String playerId,
    int targetHandIndex,
  ) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (currentAuthUid == null) throw Exception("Non authentifié.");

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;
      if (gameData['gameState'] != 'playing') return;

      final players = Map<String, dynamic>.from(gameData['players'] ?? {});
      if (players[playerId]?['authUid'] != currentAuthUid) {
        throw Exception("Action non autorisée.");
      }

      List<String> playerOrder = List<String>.from(
        gameData['zombiePlayerOrder'],
      );
      List<String> eliminated = List<String>.from(
        gameData['zombieEliminatedPlayers'] ?? [],
      );
      int currentIndex = gameData['zombieCurrentPlayerIndex'];

      if (playerOrder[currentIndex] != playerId) {
        throw Exception("Ce n'est pas votre tour.");
      }

      // Trouver la cible suivante
      int targetIndex = currentIndex;
      do {
        targetIndex = (targetIndex + 1) % playerOrder.length;
      } while (eliminated.contains(playerOrder[targetIndex]) &&
          targetIndex != currentIndex);

      if (targetIndex == currentIndex) return;

      String targetPlayerId = playerOrder[targetIndex];

      Map<String, dynamic> hands = Map<String, dynamic>.from(
        gameData['zombiePlayerHands'],
      );
      List<String> myHand = List<String>.from(hands[playerId] ?? []);
      List<String> targetHand = List<String>.from(hands[targetPlayerId] ?? []);

      if (targetHandIndex < 0 || targetHandIndex >= targetHand.length) {
        throw Exception("Index de carte invalide.");
      }

      String drawnCard = targetHand.removeAt(targetHandIndex);
      myHand.add(drawnCard);

      _discardPairs(myHand);

      myHand.shuffle();
      targetHand.shuffle();

      hands[playerId] = myHand;
      hands[targetPlayerId] = targetHand;

      // VÉRIFICATION DES DEUX JOUEURS
      if (myHand.isEmpty && !eliminated.contains(playerId)) {
        eliminated.add(playerId);
      }
      if (targetHand.isEmpty && !eliminated.contains(targetPlayerId)) {
        eliminated.add(targetPlayerId);
      }

      int activePlayersCount = playerOrder.length - eliminated.length;

      Map<String, dynamic> updates = {
        'zombiePlayerHands': hands,
        'zombieEliminatedPlayers': eliminated,
        'turnStartTime': FieldValue.serverTimestamp(),
      };

      if (activePlayersCount <= 1) {
        String loserId = playerOrder.firstWhere(
          (p) => !eliminated.contains(p),
          orElse: () => playerId,
        );
        updates.addAll({
          'gameState': 'gameOver',
          'zombieLoserId': loserId,
          'gameEndReason':
              "${players[loserId]?['name'] ?? 'Un joueur'} a gardé le Zombie !",
        });
      } else {
        int nextIndex = currentIndex;
        do {
          nextIndex = (nextIndex + 1) % playerOrder.length;
        } while (eliminated.contains(playerOrder[nextIndex]));

        updates['zombieCurrentPlayerIndex'] = nextIndex;
      }

      transaction.update(gameRef, updates);
    });
  }

  Future<void> handleZombieTimeout(String gameCode) async {
    final gameRef = _db.collection('games').doc(gameCode);
    final snap = await gameRef.get();
    if (!snap.exists) return;
    final data = snap.data() as Map<String, dynamic>;
    if (data['gameState'] != 'playing') return;

    List<String> playerOrder = List<String>.from(data['zombiePlayerOrder']);
    List<String> eliminated = List<String>.from(
      data['zombieEliminatedPlayers'] ?? [],
    );
    int currentIndex = data['zombieCurrentPlayerIndex'];
    String currentPlayerId = playerOrder[currentIndex];

    int targetIndex = currentIndex;
    do {
      targetIndex = (targetIndex + 1) % playerOrder.length;
    } while (eliminated.contains(playerOrder[targetIndex]) &&
        targetIndex != currentIndex);

    if (targetIndex == currentIndex) return;

    Map<String, List<dynamic>> hands = Map<String, List<dynamic>>.from(
      data['zombiePlayerHands'],
    );
    List<String> targetHand = List<String>.from(
      hands[playerOrder[targetIndex]] ?? [],
    );

    if (targetHand.isNotEmpty) {
      int randomIndex = Random().nextInt(targetHand.length);
      await zombieTakeCard(gameCode, currentPlayerId, randomIndex);
    }
  }

  // --- LOGIQUE DEVINE TÃŠTE MULTIJOUEUR ---
  Future<void> _startDevineTeteRound(
    DocumentReference gameRef,
    Map<String, dynamic> gameData,
  ) async {
    final players = Map<String, dynamic>.from(gameData['players']);
    final playerIds = players.keys.toList()..shuffle();
    final difficulty = gameData['difficulty'] ?? 'soft';
    final bool useTeams = gameData['devineTeteUseTeams'] == true;

    List<String> words = [];
    if (gameData['aiWords'] != null &&
        (gameData['aiWords'] as List).isNotEmpty) {
      words = List<String>.from(gameData['aiWords']);
    } else {
      words = List<String>.from(
        GameWords.devineTeteByDifficulty[difficulty] ??
            GameWords.devineTeteByDifficulty['soft']!,
      );
    }
    words.shuffle();

    Map<String, dynamic> updates = {
      'gameState': 'playing',
      'roundState': 'playing_turn',
      'devineTeteWords': words,
      'currentWord': words.removeAt(0),
      'guessedCount': 0,
      'turnTimerSeconds': 60,
      'turnStartTime': FieldValue.serverTimestamp(),
      'videoEnabled': true,
    };

    if (useTeams) {
      Map<String, dynamic> teams;
      if (gameData['teams'] != null && gameData['teams'].isNotEmpty) {
        teams = gameData['teams'];
      } else if (gameData['teamA'] != null && gameData['teamB'] != null) {
        teams = {'teamA': gameData['teamA'], 'teamB': gameData['teamB']};
      } else {
        int mid = playerIds.length ~/ 2;
        teams = {
          'teamA': playerIds.sublist(0, mid),
          'teamB': playerIds.sublist(mid),
        };
      }
      updates['teams'] = teams;
      updates['teamScores'] = {'teamA': 0, 'teamB': 0};
      updates['activeTeam'] = 'teamA';
      updates['teamATurnIndex'] = 1; // 0 est le premier devineur
      updates['teamBTurnIndex'] = 0;
      String firstGuesser = teams['teamA'][0];
      updates['currentGuesserId'] = firstGuesser;
      updates['currentPlayerIndex'] = playerIds.indexOf(firstGuesser);
    } else {
      updates['currentGuesserId'] = playerIds[0];
      updates['currentPlayerIndex'] = 0;
    }

    await gameRef.update(updates);
  }

  Future<void> actionDevineTete(
    String gameCode,
    String playerId,
    bool guessed,
  ) async {
    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;

      if (gameData['currentGuesserId'] != playerId ||
          gameData['roundState'] != 'playing_turn')
        return;

      List<String> words = List<String>.from(gameData['devineTeteWords'] ?? []);
      int guessedCount = gameData['guessedCount'] ?? 0;

      Map<String, dynamic> updates = {};

      if (guessed) {
        updates['players.$playerId.score'] = FieldValue.increment(1);
        updates['guessedCount'] = guessedCount + 1;
        if (gameData['devineTeteUseTeams'] == true) {
          String activeTeam = gameData['activeTeam'] ?? 'teamA';
          updates['teamScores.$activeTeam'] = FieldValue.increment(1);
        }
      }

      if (words.isNotEmpty) {
        updates['currentWord'] = words.removeAt(0);
        updates['devineTeteWords'] = words;
      } else {
        updates['roundState'] = 'turn_result';
        updates['turnStartTime'] = FieldValue.serverTimestamp();
      }

      transaction.update(gameRef, updates);
    });
  }

