  Future<void> nextHotPotatoRound(String gameCode) async {
    DocumentReference gameRef = _db.collection('games').doc(gameCode);
    DocumentSnapshot gameSnap = await gameRef.get();
    if (!gameSnap.exists) return;
    Map<String, dynamic> gameData = gameSnap.data() as Map<String, dynamic>;

    List<String> playerOrder = List<String>.from(
      gameData['playerOrder'] ?? gameData['players'].keys.toList(),
    );
    String gameType = gameData['gameType'] ?? '';

    // Check game-end condition for Categories
    if (gameType == 'Le Jeu des Catégories') {
      int currentRound = gameData['currentRound'] ?? 0;
      List<String> categories = List<String>.from(
        gameData['selectedCategories'] ?? [],
      );
      int maxRounds = max(categories.length, playerOrder.length * 2);
      if (currentRound >= maxRounds) {
        // Find winner (lowest score)
        Map<String, dynamic> players = Map<String, dynamic>.from(
          gameData['players'] ?? {},
        );
        String? winnerId;
        int lowestScore = 999;
        players.forEach((id, data) {
          int score = data['score'] ?? 0;
          if (score < lowestScore) {
            lowestScore = score;
            winnerId = id;
          }
        });
        String winnerName = players[winnerId]?['name'] ?? 'Personne';
        await gameRef.update({
          'gameState': 'gameOver',
          'gameEndReason':
              '$winnerName gagne avec $lowestScore point${lowestScore > 1 ? 's' : ''} !',
        });
        return;
      }
    }

    // RÃƒÂ©cupÃƒÂ©ration d'une catÃƒÂ©gorie alÃƒÂ©atoire parmi celles sÃƒÂ©lectionnÃƒÂ©es par l'hÃƒÂ´te
    List<String> availableCategories = List<String>.from(
      gameData['selectedCategories'] ?? GameData.categoriesGameList,
    );
    String category = "CatÃƒÂ©gorie";
    if (availableCategories.isNotEmpty) {
      category =
          availableCategories[Random().nextInt(availableCategories.length)];
    }

    int duration =
        gameData['hotPotatoUseGlobalTimer'] == true
            ? (gameData['hotPotatoGlobalDuration'] ?? 60)
            : (gameData['turnTimerSeconds'] ?? 30);

    // Pick a different player from the previous one if possible
    String? previousPlayerId = gameData['hotPotatoCurrentPlayerId'];
    String nextPlayerId = playerOrder[Random().nextInt(playerOrder.length)];
    if (playerOrder.length > 1 && nextPlayerId == previousPlayerId) {
      nextPlayerId =
          playerOrder[(playerOrder.indexOf(previousPlayerId!) + 1) %
              playerOrder.length];
    }

    await gameRef.update({
      'currentRound': FieldValue.increment(1),
      'roundState': 'playing',
      'hotPotatoCategory': category,
      'hotPotatoCurrentPlayerId': nextPlayerId,
      'hotPotatoSecondsLeft': duration,
      'hotPotatoUsedAnswers': [],
      'hotPotatoRoundStartedAt': FieldValue.serverTimestamp(),
      'turnStartTime': FieldValue.serverTimestamp(),
      'roundWinnerId': null,
      'gameEndReason': null,
    });
  }

  Future<void> playUnoCard(
    String gameCode,
    String playerId,
    String card, {
    String? chosenColor,
  }) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (currentAuthUid == null) throw Exception("Non authentifié.");

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) throw Exception("Partie non trouvée.");

      var gameData = gameSnap.data() as Map<String, dynamic>;
      final players = Map<String, dynamic>.from(gameData['players'] ?? {});

      // SÉCURITÉ : Vérifier l'authUid
      final voterAuthUid = players[playerId]?['authUid'] ?? playerId;
      if (currentAuthUid != voterAuthUid) {
        throw Exception("Action non autorisée.");
      }

      List<String> playerOrder = List<String>.from(
        gameData['unoPlayerOrder'] ?? [],
      );
      int currentPlayerIndex = gameData['unoCurrentPlayerIndex'] ?? 0;
      int unoDirection = gameData['unoDirection'] ?? 1;
      List<String> myHand = List<String>.from(
        gameData['unoPlayerHands']?[playerId] ?? [],
      );
      List<String> discardPile = List<String>.from(
        gameData['unoDiscardPile'] ?? [],
      );
      if (discardPile.isEmpty) throw Exception("La pile de défausse est vide.");
      String topCard = discardPile.last;
      String? wildColorChosen = gameData['unoWildColorChosen'];
      int pendingDraw = gameData['unoPendingDraw'] ?? 0;
      bool stackDraws = gameData['unoStackDraws'] ?? true;

      if (playerOrder[currentPlayerIndex] != playerId) {
        throw Exception("Ce n'est pas votre tour de jouer.");
      }

      if (!myHand.contains(card)) {
        throw Exception("Vous n'avez pas cette carte en main.");
      }

      if (pendingDraw > 0) {
        String cardValue = GameData.getUnoCardValue(card);
        bool isDrawCard = (cardValue == 'draw2' || cardValue == 'wild_draw4');

        if (!isDrawCard || !stackDraws) {
          throw Exception(
            "Vous devez piocher $pendingDraw cartes, ou jouer une carte +2/+4 si l'empilement est activé.",
          );
        }
      }

      if (gameData['unoDrawActionDone'] == true) {
        if (card != gameData['unoLastDrawnCard']) {
          throw Exception(
            "Vous devez jouer la carte que vous venez de piocher.",
          );
        }
      }

      if (!GameData.canPlayUnoCard(card, topCard, wildColorChosen)) {
        throw Exception(
          "Cette carte ne peut pas être jouée. La couleur ou le numéro ne correspond pas.",
        );
      }

      myHand.remove(card);
      discardPile.add(card);

      Map<String, dynamic> updates = {
        'unoPlayerHands.$playerId': myHand,
        'unoDiscardPile': discardPile,
        'unoWildColorChosen': null,
        'unoLastActionPlayerId': playerId,
        'unoCalledUno.$playerId': false,
        'unoDrawActionDone': false,
        'unoLastDrawnCard': null,
      };

      String cardValue = GameData.getUnoCardValue(card);
      int nextPlayerIdx =
          (currentPlayerIndex + unoDirection + playerOrder.length) %
          playerOrder.length;

      switch (cardValue) {
        case 'reverse':
          if (playerOrder.length == 2) {
            nextPlayerIdx = currentPlayerIndex; // Le joueur rejoue !
            updates['unoLog'] = FieldValue.arrayUnion([
              "${players[playerId]?['name'] ?? 'Joueur'} a joué une Inversion (Rejoue) !",
            ]);
          } else {
            unoDirection *= -1;
            updates['unoDirection'] = unoDirection;
            nextPlayerIdx =
                (currentPlayerIndex + unoDirection + playerOrder.length) %
                playerOrder.length;
            updates['unoLog'] = FieldValue.arrayUnion([
              "${players[playerId]?['name'] ?? 'Joueur'} a inversé le sens de jeu !",
            ]);
          }
          break;
        case 'skip':
          final skippedPlayerIndex = nextPlayerIdx;
          nextPlayerIdx =
              (nextPlayerIdx + unoDirection + playerOrder.length) %
              playerOrder.length;
          final skippedPlayerName =
              players[playerOrder[skippedPlayerIndex]]?['name'] ??
              'Joueur suivant';
          updates['unoLog'] = FieldValue.arrayUnion([
            "${players[playerId]?['name'] ?? 'Joueur'} a fait passer le tour de $skippedPlayerName!",
          ]);
          break;
        case 'draw2':
          if (stackDraws && pendingDraw > 0) {
            updates['unoPendingDraw'] = pendingDraw + 2;
            updates['unoLog'] = FieldValue.arrayUnion([
              "${players[playerId]?['name'] ?? 'Joueur'} a empilé un +2. Le joueur suivant doit piocher ${pendingDraw + 2} !",
            ]);
          } else {
            updates['unoPendingDraw'] = 2;
            updates['unoLog'] = FieldValue.arrayUnion([
              "${players[playerId]?['name'] ?? 'Joueur'} a joué un +2. Le joueur suivant doit piocher 2 !",
            ]);
          }
          break;
        case 'wild':
          if (chosenColor == null)
            throw Exception("Veuillez choisir une couleur pour le Joker.");
          updates['unoWildColorChosen'] = chosenColor;
          updates['unoLog'] = FieldValue.arrayUnion([
            "${players[playerId]?['name'] ?? 'Joueur'} a joué un Joker et a choisi la couleur $chosenColor !",
          ]);
          break;
        case 'wild_draw4':
          if (chosenColor == null)
            throw Exception(
              "Veuillez choisir une couleur pour le Super Joker +4.",
            );
          updates['unoWildColorChosen'] = chosenColor;
          if (stackDraws && pendingDraw > 0) {
            updates['unoPendingDraw'] = pendingDraw + 4;
            updates['unoLog'] = FieldValue.arrayUnion([
              "${players[playerId]?['name'] ?? 'Joueur'} a empilé un +4. Le joueur suivant doit piocher ${pendingDraw + 4} !",
            ]);
          } else {
            updates['unoPendingDraw'] = 4;
            updates['unoLog'] = FieldValue.arrayUnion([
              "${players[playerId]?['name'] ?? 'Joueur'} a joué un Super Joker +4. Le joueur suivant doit piocher 4 !",
            ]);
          }

          break;
      }

      updates['unoCurrentPlayerIndex'] = nextPlayerIdx;
      updates['turnStartTime'] = FieldValue.serverTimestamp();

      if (myHand.isEmpty) {
        updates['gameState'] = 'gameOver';
        updates['gameWinner'] = playerId;
        updates['gameEndReason'] =
            "${players[playerId]?['name'] ?? 'Joueur'} a posé sa dernière carte et gagne la manche !";

        int roundScore = 0;
        gameData['unoPlayerHands'].forEach((pId, hand) {
          if (pId != playerId) {
            (hand as List<String>).forEach(
              (c) => roundScore += GameData.getUnoCardScore(c),
            );
          }
        });
        updates['players.$playerId.score'] = FieldValue.increment(roundScore);
        updates['unoLog'] = FieldValue.arrayUnion([
          "${players[playerId]?['name'] ?? 'Joueur'} gagne la manche avec $roundScore points !",
        ]);
      } else if (myHand.length == 1) {
        updates['unoCalledUno.$playerId'] = false;
        updates['unoContraDeadline'] = Timestamp.fromDate(
          DateTime.now().add(const Duration(seconds: 3)),
        );
        updates['unoLog'] = FieldValue.arrayUnion([
          "${players[playerId]?['name'] ?? 'Joueur'} a maintenant une seule carte !",
        ]);
      }
      transaction.update(gameRef, updates);
    });
  }

  Future<void> drawUnoCard(String gameCode, String playerId) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (currentAuthUid == null) throw Exception("Non authentifié.");

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) throw Exception("Partie non trouvée.");

      var gameData = gameSnap.data() as Map<String, dynamic>;
      final players = Map<String, dynamic>.from(gameData['players'] ?? {});

      // SÉCURITÉ : Vérifier l'authUid
      final voterAuthUid = players[playerId]?['authUid'] ?? playerId;
      if (currentAuthUid != voterAuthUid) {
        throw Exception("Action non autorisée.");
      }

      List<String> playerOrder = List<String>.from(
        gameData['unoPlayerOrder'] ?? [],
      );
      int currentPlayerIndex = gameData['unoCurrentPlayerIndex'] ?? 0;
      int unoDirection = gameData['unoDirection'] ?? 1;
      List<String> myHand = List<String>.from(
        gameData['unoPlayerHands']?[playerId] ?? [],
      );
      List<String> deck = List<String>.from(gameData['unoDeck'] ?? []);
      List<String> discardPile = List<String>.from(
        gameData['unoDiscardPile'] ?? [],
      );
      int pendingDraw = gameData['unoPendingDraw'] ?? 0;

      if (playerOrder[currentPlayerIndex] != playerId) {
        throw Exception("Ce n'est pas votre tour de piocher.");
      }

      Map<String, dynamic> updates = {};

      if (deck.isEmpty) {
        if (discardPile.length > 1) {
          String topCard = discardPile.removeLast();
          deck.addAll(discardPile..shuffle());
          discardPile = [topCard];
          updates['unoDeck'] = deck;
          updates['unoDiscardPile'] = discardPile;
          updates['unoLog'] = FieldValue.arrayUnion([
            "La pioche est vide. La défausse est mélangée pour former une nouvelle pioche.",
          ]);
        } else {
          throw Exception(
            "Impossible de piocher, il n'y a plus de cartes disponibles.",
          );
        }
      }

      if (pendingDraw > 0) {
        List<String> drawnCards = [];
        for (int i = 0; i < pendingDraw; i++) {
          if (deck.isNotEmpty) {
            drawnCards.add(deck.removeAt(0));
          } else {
            if (discardPile.length > 1) {
              String topCard = discardPile.removeLast();
              deck.addAll(discardPile..shuffle());
              discardPile = [topCard];
              updates['unoDiscardPile'] = discardPile;
              i--; // Recommencer cette itération avec le nouveau deck
            } else {
              break; // Plus aucune carte à piocher
            }
          }
        }

        myHand.addAll(drawnCards);
        updates['unoPlayerHands.$playerId'] = myHand;
        updates['unoDeck'] = deck;
        updates['unoPendingDraw'] = 0; // La pénalité est purgée
        updates['unoLog'] = FieldValue.arrayUnion([
          "${players[playerId]?['name'] ?? 'Joueur'} a pioché $pendingDraw carte(s).",
        ]);

        int nextPlayerIdx =
            (currentPlayerIndex + unoDirection + playerOrder.length) %
            playerOrder.length;
        updates['unoCurrentPlayerIndex'] = nextPlayerIdx;
        updates['turnStartTime'] = FieldValue.serverTimestamp();

        transaction.update(gameRef, updates);
        return; // Fin de la logique pour la pioche forcée
      }

      String drawnCard = deck.removeAt(0);
      myHand.add(drawnCard);
      updates['unoPlayerHands.$playerId'] = myHand;
      updates['unoDeck'] = deck;

      if (discardPile.isEmpty) throw Exception("La pile de défausse est vide.");
      String topCard = discardPile.last;
      String? wildColor = gameData['unoWildColorChosen'];
      bool canPlayDrawnCard = GameData.canPlayUnoCard(
        drawnCard,
        topCard,
        wildColor,
      );

      if (canPlayDrawnCard) {
        updates['unoLog'] = FieldValue.arrayUnion([
          "${players[playerId]?['name'] ?? 'Joueur'} a pioché une carte et peut la jouer.",
        ]);
        updates['unoDrawActionDone'] =
            true; // Indique à l'UI de permettre de jouer la carte
        updates['unoLastDrawnCard'] = drawnCard;
      } else {
        updates['unoLog'] = FieldValue.arrayUnion([
          "${players[playerId]?['name'] ?? 'Joueur'} a pioché une carte et passe son tour.",
        ]);
        int nextPlayerIdx =
            (currentPlayerIndex + unoDirection + playerOrder.length) %
            playerOrder.length;
        updates['unoCurrentPlayerIndex'] = nextPlayerIdx;
        updates['turnStartTime'] = FieldValue.serverTimestamp();
      }

      transaction.update(gameRef, updates);
    });
  }

  Future<void> callUno(
    String gameCode,
    String callerId,
    String targetId,
  ) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (currentAuthUid == null) throw Exception("Non authentifié.");

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) throw Exception("Partie non trouvée.");

      var gameData = gameSnap.data() as Map<String, dynamic>;
      final players = Map<String, dynamic>.from(gameData['players'] ?? {});

      // SÉCURITÉ : Vérifier l'authUid de l'appelant
      final callerAuthUid = players[callerId]?['authUid'] ?? callerId;
      if (currentAuthUid != callerAuthUid) {
        throw Exception("Action non autorisée.");
      }

      Map<String, dynamic> unoPlayerHands = Map<String, dynamic>.from(
        gameData['unoPlayerHands'] ?? {},
      );
      List<String> targetHand = List<String>.from(
        unoPlayerHands[targetId] ?? [],
      );
      List<String> deck = List<String>.from(gameData['unoDeck'] ?? []);
      Map<String, dynamic> unoCalledUno = Map<String, dynamic>.from(
        gameData['unoCalledUno'] ?? {},
      );
      String? lastActionPlayerId = gameData['unoLastActionPlayerId'];

      if (targetHand.length != 1) {
        throw Exception(
          "${players[targetId]?['name'] ?? 'Le joueur'} n'a pas 1 carte, l'appel UNO est invalide.",
        );
      }
      Map<String, dynamic> updates = {};

      if (callerId != targetId &&
          !(unoCalledUno[targetId] ?? false) &&
          lastActionPlayerId == targetId) {
        List<String> penaltyCards = [];
        for (int i = 0; i < 2; i++) {
          if (deck.isNotEmpty) {
            penaltyCards.add(deck.removeAt(0));
          } else {
            break;
          }
        }
        targetHand.addAll(penaltyCards);
        updates['unoPlayerHands.$targetId'] = targetHand;
        updates['unoDeck'] = deck;
        updates['unoContraDeadline'] = null;
        updates['unoLog'] = FieldValue.arrayUnion([
          "${players[callerId]?['name'] ?? 'Joueur'} a crié Contre UNO ! ${players[targetId]?['name'] ?? 'Joueur'} pioche 2 cartes.",
        ]);

        updates['unoCalledUno.$targetId'] = true;
      } else if (callerId == targetId && targetHand.length == 1) {
        updates['unoCalledUno.$targetId'] = true;
        updates['unoContraDeadline'] = null;
        updates['unoLog'] = FieldValue.arrayUnion([
          "${players[targetId]?['name'] ?? 'Joueur'} a dit UNO !",
        ]);
      } else {
        throw Exception("Appel UNO invalide.");
      }

      transaction.update(gameRef, updates);
    });
  }

  Future<void> chooseWildColor(
    String gameCode,
    String playerId,
    String chosenColor,
  ) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (currentAuthUid == null) throw Exception("Non authentifié.");

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) throw Exception("Partie non trouvée.");

      var gameData = gameSnap.data() as Map<String, dynamic>;
      final players = Map<String, dynamic>.from(gameData['players'] ?? {});

      // SÉCURITÉ : Vérifier l'authUid
      final voterAuthUid = players[playerId]?['authUid'] ?? playerId;
      if (currentAuthUid != voterAuthUid) {
        throw Exception("Action non autorisée.");
      }

      List<String> playerOrder = List<String>.from(
        gameData['unoPlayerOrder'] ?? [],
      );
      int currentPlayerIndex = gameData['unoCurrentPlayerIndex'] ?? 0;

      if (playerOrder.isEmpty || playerOrder[currentPlayerIndex] != playerId) {
        throw Exception("Ce n'est pas votre tour de choisir la couleur.");
      }

      List<String> discardPile = List<String>.from(
        gameData['unoDiscardPile'] ?? [],
      );
      if (discardPile.isEmpty) throw Exception("La pile de défausse est vide.");
      String topCard = discardPile.last;
      String topCardValue = GameData.getUnoCardValue(topCard);

      if (GameData.unoWildCards.contains(topCardValue)) {
        transaction.update(gameRef, {
          'unoWildColorChosen': chosenColor,
          'unoLog': FieldValue.arrayUnion([
            "${players[playerId]?['name'] ?? 'Joueur'} a choisi la couleur $chosenColor !",
          ]),
        });
      } else {
        throw Exception("Vous ne pouvez pas choisir une couleur maintenant.");
      }
    });
  }

  Future<void> _nextUnoPlayer(
    DocumentReference gameRef,
    Map<String, dynamic> gameData,
  ) async {
    int currentPlayerIndex = gameData['unoCurrentPlayerIndex'] ?? 0;
    int unoDirection = gameData['unoDirection'] ?? 1;
    List<String> playerOrder = List<String>.from(
      gameData['unoPlayerOrder'] ?? [],
    );

    int nextPlayerIdx =
        (currentPlayerIndex + unoDirection + playerOrder.length) %
        playerOrder.length;

    await gameRef.update({
      'unoCurrentPlayerIndex': nextPlayerIdx,
      'unoDrawActionDone': false,
      'unoLastDrawnCard': null,
      'unoWildColorChosen': null,
    });
  }

  Future<void> nextRound(String gameCode) async {
    DocumentReference gameRef = _db.collection('games').doc(gameCode);
    DocumentSnapshot gameSnap = await gameRef.get();
    if (!gameSnap.exists) return;
    Map<String, dynamic> gameData = gameSnap.data() as Map<String, dynamic>;

    String gameType = gameData['gameType'];
    String difficulty = gameData['difficulty'];
    Map<String, dynamic> players = gameData['players'];
    if (players.keys.isEmpty) return;

    final random = Random();

    final List<String> playerOrder = List<String>.from(
      gameData['playerOrder'] ?? [],
    );
    final int currentPlayerIndex = gameData['currentPlayerIndex'] ?? -1;

    if (playerOrder.isEmpty) {
      print(
        "ERREUR CRITIQUE: playerOrder est vide dans nextRound. Impossible de continuer.",
      );
      return;
    }

    final int nextPlayerIndex = (currentPlayerIndex + 1) % playerOrder.length;
    String activePlayerId = playerOrder[nextPlayerIndex];

    String question = "Question non trouvÃƒÂ©e";
    String? currentTargetPlayerId;
    String? liarId;
    String? undercoverId;
    String? mrWhiteId;
    Map<String, dynamic> secretData = {};
    String? roundData;
    String roundState = 'answering';
    String? memeUrl;

    final List<dynamic>? _rawAiWords = gameData['aiWords'] as List<dynamic>?;
    final List<String>? _aiWordPool =
        (_rawAiWords != null && _rawAiWords.isNotEmpty)
            ? _rawAiWords.map((e) => e.toString()).toList()
            : null;

    if (gameType == 'Le Juge') {
      List<String> questions =
          _aiWordPool ?? GameData.multiplayerGameData[gameType]![difficulty]!;
      question = questions[random.nextInt(questions.length)];
      currentTargetPlayerId = activePlayerId; // Le joueur actif est la cible
      question = question.replaceAll(
        '{player}',
        players[currentTargetPlayerId]['name'],
      );
      roundState = 'answering';
    } else if (gameType == 'Qui Pourrait le Plus ?') {
      List<String> questions =
          _aiWordPool ?? GameData.multiplayerGameData[gameType]![difficulty]!;
      question =
          "Qui pourrait le plus ${questions[random.nextInt(questions.length)]}";
      roundState = 'voting';
    } else if (gameType == 'Le Menteur') {
      List<String> prompts =
          _aiWordPool ?? GameData.multiplayerGameData[gameType]![difficulty]!;
      question = prompts[random.nextInt(prompts.length)];
      roundState = 'answering';

      if (gameData['isSimplifiedLiar'] == true) {
        liarId = null;
        await gameRef.update({
          'storyTruths': {},
          'playerOrder': List<String>.from(players.keys.toList())..shuffle(),
          'revealIndex': 0,
        });
      } else {
        // MODE CLASSIQUE SÉCURISÉ : On choisit le menteur secrètement
        String secretLiarId = playerOrder[random.nextInt(playerOrder.length)];
        for (var pId in players.keys) {
          await gameRef.collection('private_data').doc(pId).set({
            'isLiar': (pId == secretLiarId),
            'role': (pId == secretLiarId) ? 'Menteur' : 'Honnête',
          });
        }
        liarId = null;
      }
    } else if (gameType == 'Infiltré & Mr. White') {
      if (playerOrder.length >= 3) {
        List<String> wordPairs =
            _aiWordPool ?? GameData.multiplayerGameData[gameType]![difficulty]!;
        String pair = wordPairs[random.nextInt(wordPairs.length)];
        List<String> words =
            pair.contains(':') ? pair.split(':') : [pair, pair];

        List<String> shuffledRoles = List.from(playerOrder)..shuffle();
        String secUndercoverId = shuffledRoles[0];
        String secMrWhiteId = shuffledRoles[1];

        question =
            "Décrivez votre mot secret en un seul mot. Imposteurs, bluffez !";
        for (var pId in players.keys) {
          String pRole =
              (pId == secUndercoverId)
                  ? 'Infiltré'
                  : (pId == secMrWhiteId ? 'Mr. White' : 'Civil');
          String pWord =
              (pId == secUndercoverId)
                  ? words[1]
                  : (pId == secMrWhiteId ? "Vous n'avez pas de mot" : words[0]);

          await gameRef.collection('private_data').doc(pId).set({
            'role': pRole,
            'secretWord': pWord,
            'specialAbilities': <String>[],
          });
        }
        undercoverId = null;
        mrWhiteId = null;
        secretData = {};
        roundData = null;
        roundState = 'answering';
      } else {
        question = "Pas assez de joueurs pour ce mode.";
        roundState = 'result';
      }
    } else if (gameType == 'Synonyme ou Banni') {
      List<String> words =
          _aiWordPool ?? GameData.multiplayerGameData[gameType]![difficulty]!;
      String word = words[random.nextInt(words.length)];
      question = "Trouvez le meilleur synonyme pour le mot : $word";
      roundData = word;
      roundState = 'answering';
    } else if (gameType == 'Le Roi des Mèmes') {
      memeUrl = await _fetchRandomMemeUrl();
      question = "Ajoute la description la plus drÃƒÂ´le ÃƒÂ  ce mÃƒÂ¨me !";
      roundState = 'answering';
    } else if (gameType == 'Skull') {
      await nextSkullRound(gameCode);
      return;
    } else if (gameType == 'Uno') {
      List<String> deck = GameData.generateUnoDeck();
      Map<String, List<String>> playerHands = {};
      int startingCards = gameData['unoStartingCards'] ?? 7;

      Map<String, dynamic> currentScores = Map<String, dynamic>.from(
        gameData['players'] ?? {},
      );
      Map<String, int> updatedScores = {};
      currentScores.forEach((id, data) {
        updatedScores[id] = data['score'] ?? 0;
      });

      String? overallWinnerId;
      for (var entry in updatedScores.entries) {
        if (entry.value >= 500) {
          overallWinnerId = entry.key;
          break;
        }
      }

      if (overallWinnerId != null) {
        await gameRef.update({
          'gameState': 'gameOver',
          'gameWinner': overallWinnerId,
          'gameEndReason':
              "${players[overallWinnerId]?['name']} a atteint ${updatedScores[overallWinnerId]} points et gagne la partie !",
        });
        return;
      }

      for (String pId in playerOrder) {
        playerHands[pId] = [];
        for (int i = 0; i < startingCards; i++) {
          playerHands[pId]!.add(deck.removeAt(0));
        }
      }

      String firstCard;
      do {
        firstCard = deck.removeAt(0);
      } while (GameData.getUnoCardColor(firstCard) == 'wild');

      await gameRef.update({
        'unoDeck': deck,
        'unoDiscardPile': [firstCard],
        'unoPlayerHands': playerHands,
        'unoCurrentPlayerIndex': 0,
        'unoDirection': 1,
        'unoPendingDraw': 0,
        'unoWildColorChosen': null,
        'unoCalledUno': {for (var pId in playerOrder) pId: false},
        'unoLastActionPlayerId': null,
        'gameState': 'playing',
        'roundState': 'playing_turn',
        'unoLog': FieldValue.arrayUnion([
          'Une nouvelle manche de Uno commence !',
        ]),
        'turnStartTime': FieldValue.serverTimestamp(),
      });
      await _applyFirstUnoCardEffect(gameRef, firstCard, playerOrder[0]);
      return; // On arrÃƒÂªte l'exÃƒÂ©cution ici pour Uno
    }

    final updateMap = {
      'currentPlayerIndex': nextPlayerIndex,
      'currentRound': FieldValue.increment(1),
      'roundState': roundState,
      'currentQuestion': question,
      'currentTargetPlayerId': currentTargetPlayerId,
      'activePlayerId': activePlayerId,
      'liarId': liarId,
      'undercoverId': undercoverId,
      'mrWhiteId': mrWhiteId,
      'secretData': secretData,
      'roundData': roundData,
      'answers': {},
      'votes': {},
      'accusations': {},
      'roundWinnerId': null,
      'voteResults': null,
      'gameEndReason': null,
      'memeUrl': memeUrl,
      'turnStartTime': FieldValue.serverTimestamp(),
    };

    if (currentPlayerIndex > -1) {
      String oldPlayerId = playerOrder[currentPlayerIndex];
      updateMap['inactiveTurnCounts.$oldPlayerId'] = 0;
    }

    await gameRef.update(updateMap);
  }

  int _nextSkullActiveIndex(
    List<String> playerOrder,
    int currentIndex,
    Map<String, dynamic> players, [
    Set<String> blockedPlayers = const <String>{},
  ]) {
    if (playerOrder.isEmpty) return -1;

    for (int step = 1; step <= playerOrder.length; step++) {
      final int nextIndex = (currentIndex + step) % playerOrder.length;
      final String candidateId = playerOrder[nextIndex];
      final Map<String, dynamic> candidatePlayer = Map<String, dynamic>.from(
        players[candidateId] ?? {},
      );
      final int cardsInHand = candidatePlayer['cardsInHand'] ?? 0;
      final bool isOut = candidatePlayer['isOut'] == true;

      if (!isOut && cardsInHand > 0 && !blockedPlayers.contains(candidateId)) {
        return nextIndex;
      }
    }

    return -1;
  }

  List<Map<String, dynamic>> _buildSkullRevealSequence(
    List<String> playerOrder,
    String challengerId,
    Map<String, dynamic> skullMats,
  ) {
    if (playerOrder.isEmpty) return [];

    final int challengerIndex = playerOrder.indexOf(challengerId);
    final List<String> orderedPlayers = [
      ...playerOrder.sublist(challengerIndex < 0 ? 0 : challengerIndex),
      ...playerOrder.sublist(0, challengerIndex < 0 ? 0 : challengerIndex),
    ];

    final List<Map<String, dynamic>> sequence = [];
    for (final ownerId in orderedPlayers) {
      final List<Map<String, dynamic>> matCards =
          List<Map<String, dynamic>>.from(
            (skullMats[ownerId] as List? ?? []).map(
              (card) => Map<String, dynamic>.from(card as Map),
            ),
          );
      for (int index = matCards.length - 1; index >= 0; index--) {
        if (matCards[index]['revealed'] == true) continue;
        sequence.add({
          'ownerId': ownerId,
          'index': index,
          'type': matCards[index]['type'],
        });
      }
    }

    return sequence;
  }

  Future<void> placeSkullCard(
    String gameCode,
    String playerId,
    String cardType,
  ) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (currentAuthUid == null) throw Exception("Non authentifié.");

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      final gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists || gameSnap.data() == null) return;

      final gameData = gameSnap.data() as Map<String, dynamic>;
      if (gameData['gameType'] != 'Skull' ||
          gameData['roundState'] != 'placing') {
        return;
      }

      final Map<String, dynamic> players = Map<String, dynamic>.from(
        gameData['players'] ?? {},
      );
      if (players[playerId]?['authUid'] != currentAuthUid) {
        throw Exception("Action non autorisée.");
      }

      final List<String> playerOrder = List<String>.from(
        gameData['playerOrder'] ?? [],
      );
      final int currentPlayerIndex = gameData['skullCurrentPlayerIndex'] ?? 0;
      if (playerOrder.isEmpty ||
          currentPlayerIndex < 0 ||
          currentPlayerIndex >= playerOrder.length ||
          playerOrder[currentPlayerIndex] != playerId) {
        return;
      }

      final Map<String, dynamic> skullHands = Map<String, dynamic>.from(
        gameData['skullHands'] ?? {},
      );
      final Map<String, dynamic> skullMats = Map<String, dynamic>.from(
        gameData['skullMats'] ?? {},
      );

      final List<String> myHand = List<String>.from(skullHands[playerId] ?? []);
      if (!myHand.contains(cardType)) {
        throw Exception("Vous n'avez pas cette carte en main.");
      }

      myHand.remove(cardType);
      skullHands[playerId] = myHand;

      final List<Map<String, dynamic>> myMat = List<Map<String, dynamic>>.from(
        (skullMats[playerId] as List? ?? []).map(
          (card) => Map<String, dynamic>.from(card as Map),
        ),
      );
      myMat.add({'type': cardType, 'revealed': false});
      skullMats[playerId] = myMat;

      players[playerId] = {
        ...Map<String, dynamic>.from(players[playerId] ?? {}),
        'cardsInHand': myHand.length,
        'isOut': false,
      };

      final int nextIndex = _nextSkullActiveIndex(
        playerOrder,
        currentPlayerIndex,
        players,
      );

      final Map<String, dynamic> updates = {
        'skullHands': skullHands,
        'skullMats': skullMats,
        'players': players,
        'turnStartTime': FieldValue.serverTimestamp(),
      };

      if (nextIndex == -1) {
        updates['roundState'] = 'result';
        updates['gameEndReason'] = 'Plus aucun joueur actif.';
        updates['gameState'] = 'gameOver';
        updates['gameWinner'] = playerId;
      } else {
        updates['skullCurrentPlayerIndex'] = nextIndex;
      }

      transaction.update(gameRef, updates);
    });
  }

  Future<void> startSkullBid(String gameCode, String playerId, int bid) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (currentAuthUid == null) throw Exception("Non authentifié.");

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      final gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists || gameSnap.data() == null) return;

      final gameData = gameSnap.data() as Map<String, dynamic>;
      if (gameData['gameType'] != 'Skull' ||
          gameData['roundState'] != 'placing') {
        return;
      }

      final Map<String, dynamic> players = Map<String, dynamic>.from(
        gameData['players'] ?? {},
      );
      if (players[playerId]?['authUid'] != currentAuthUid) {
        throw Exception("Action non autorisée.");
      }

      final List<String> playerOrder = List<String>.from(
        gameData['playerOrder'] ?? [],
      );
      final int currentPlayerIndex = gameData['skullCurrentPlayerIndex'] ?? 0;
      if (playerOrder.isEmpty || playerOrder[currentPlayerIndex] != playerId) {
        return;
      }

      final Map<String, dynamic> skullMats = Map<String, dynamic>.from(
        gameData['skullMats'] ?? {},
      );

      final List<String> activePlayers =
          playerOrder.where((pId) {
            final data = Map<String, dynamic>.from(players[pId] ?? {});
            return data['isOut'] != true && (data['cardsInHand'] ?? 0) > 0;
          }).toList();

      final bool allActivePlaced = activePlayers.every((pId) {
        final List mat = skullMats[pId] as List? ?? [];
        return mat.isNotEmpty;
      });

      if (!allActivePlaced) {
        throw Exception(
          "Chaque joueur actif doit poser au moins une carte avant de lancer une enchère.",
        );
      }

      final int totalCardsOnTables = skullMats.values.fold<int>(0, (
        sum,
        cards,
      ) {
        return sum + (cards is List ? cards.length : 0);
      });

      if (bid < 1 || bid > totalCardsOnTables) {
        throw Exception("Enchère invalide.");
      }

      final Map<String, dynamic> updates = {
        'roundState': 'bidding',
        'skullCurrentBid': bid,
        'skullHighestBidderId': playerId,
        'skullPassedPlayers': <String>[],
        'skullNextStarterId': playerId,
        'turnStartTime': FieldValue.serverTimestamp(),
      };

      final int nextIndex = _nextSkullActiveIndex(
        playerOrder,
        currentPlayerIndex,
        players,
        {playerId},
      );
      if (nextIndex == -1) {
        updates['roundState'] = 'result';
        updates['skullLastChallengeWinnerId'] = playerId;
        updates['skullLastChallengeOutcome'] = 'win';
      } else {
        updates['skullCurrentPlayerIndex'] = nextIndex;
      }

      transaction.update(gameRef, updates);
    });
  }

