class JoinGameScreen extends StatefulWidget {
  final String playerName;
  final String playerId; // <--- AJOUTER

  JoinGameScreen({
    required this.playerName,
    required this.playerId, // <--- AJOUTER
  });

  @override
  _JoinGameScreenState createState() => _JoinGameScreenState();
}

class _JoinGameScreenState extends State<JoinGameScreen> {
  final FirebaseService _firebaseService = FirebaseService();
  final FirebaseFirestore _db =
      FirebaseFirestore.instance; // Ajouter une instance de Firestore

  final _codeController = TextEditingController();
  bool _isLoading = false;

  void _joinGame() async {
    if (_codeController.text.trim().length != 6) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text("Le code doit comporter 6 chiffres.")),
      );
      return;
    }
    setState(() => _isLoading = true);

    final playerState = Provider.of<PlayerState>(context, listen: false);

    final gameCode = _codeController.text.trim();

    if (!await playerState.canPlayMultiplayer()) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            "Vous avez atteint votre limite de 20 parties multijoueur pour aujourd'hui.",
          ),
        ),
      );
      if (mounted) setState(() => _isLoading = false);
      return;
    }

    try {
      DocumentSnapshot gameSnap =
          await _db.collection('games').doc(gameCode).get();
      if (!gameSnap.exists || gameSnap['gameState'] != 'lobby') {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text(
              "Code de partie invalide ou partie dÃƒÂ©jÃƒÂ  commencÃƒÂ©e.",
            ),
          ),
        );
        if (mounted) setState(() => _isLoading = false);
        return;
      }

      bool isPremiumLobby = gameSnap['isPremiumLobby'] ?? false;

      if (!isPremiumLobby) {
        bool success = await playerState.spendCoins(
          1,
        ); // CoÃƒÂ»t pour rejoindre: 1 piÃƒÂ¨ce
        if (!success) {
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(
              content: Text(
                "Pas assez de piÃƒÂ¨ces pour rejoindre cette partie ! CoÃƒÂ»t : 1 piÃƒÂ¨ce.",
              ),
            ),
          );
          if (mounted) setState(() => _isLoading = false);
          return;
        }
      } else {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text("Vous rejoignez une partie VIP, c'est gratuit !"),
          ),
        );
      }

      await playerState.recordMultiplayerGame();
      bool success = await _firebaseService.joinGame(
        gameCode,
        widget.playerName,
        widget.playerId,
      );

      if (success) {
        Navigator.pushReplacement(
          context,
          MaterialPageRoute(
            builder:
                (_) => GameLobbyScreen(
                  gameCode: gameCode,
                  playerId: widget.playerId,
                ),
          ),
        );
      } else {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text("Impossible de rejoindre la partie.")),
        );
      }
    } catch (e) {
      ScaffoldMessenger.of(
        context,
      ).showSnackBar(SnackBar(content: Text("Erreur de connexion.")));
    } finally {
      if (mounted) {
        setState(() => _isLoading = false);
      }
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text("Rejoindre une Partie")),
      body:
          _isLoading
              ? Center(child: CircularProgressIndicator())
              : Padding(
                padding: const EdgeInsets.all(16.0),
                child: Column(
                  mainAxisAlignment: MainAxisAlignment.center,
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    TextField(
                      controller: _codeController,
                      decoration: InputDecoration(
                        labelText: "Code de la partie (6 chiffres)",
                      ),
                      keyboardType: TextInputType.number,
                      textAlign: TextAlign.center,
                      style: TextStyle(fontSize: 24, letterSpacing: 8),
                      inputFormatters: [
                        FilteringTextInputFormatter.digitsOnly,
                        LengthLimitingTextInputFormatter(6),
                      ],
                    ),
                    SizedBox(height: 30),
                    ElevatedButton(
                      onPressed: _joinGame,
                      child: Text("Rejoindre"),
                    ),
                  ],
                ),
              ),
    );
  }
}

class GameLobbyScreen extends StatefulWidget {
  final String gameCode;
  final String playerId;
  const GameLobbyScreen({required this.gameCode, required this.playerId});
  @override
  _GameLobbyScreenState createState() => _GameLobbyScreenState();
}

class _GameLobbyScreenState extends State<GameLobbyScreen> {
  final FirebaseService _firebaseService = FirebaseService();
  late LivekitService _livekitService;
  bool _livekitInitialized = false;

  @override
  void initState() {
    super.initState();
    _livekitService = Provider.of<LivekitService>(context, listen: false);
  }

  Future<void> _connectToLivekit(bool videoEnabled, bool audioEnabled) async {
    if (_livekitInitialized) return;
    _livekitInitialized = true;
    try {
      await _livekitService.initialize();
      await _livekitService.joinChannel(
        widget.gameCode,
        identity: widget.playerId,
        videoEnabled: videoEnabled,
        audioEnabled: audioEnabled,
      );
    } catch (e) {
      print("Erreur init Livekit au salon : $e");
    }
  }

  @override
  Widget build(BuildContext context) {
    final String gameCode = widget.gameCode;
    final String currentPlayerId = widget.playerId;

    return Scaffold(
      appBar: AppBar(title: const Text("Salon Privé")),
      body: StreamBuilder<DocumentSnapshot>(
        stream: _firebaseService.getGameStream(gameCode),
        builder: (context, snapshot) {
          if (!snapshot.hasData)
            return const Center(child: CircularProgressIndicator());
          if (snapshot.hasError)
            return const Center(child: Text("Erreur de connexion au salon."));
          if (!snapshot.data!.exists) {
            WidgetsBinding.instance.addPostFrameCallback((_) {
              if (mounted) {
                Navigator.of(context).popUntil((route) => route.isFirst);
              }
            });
            return const Center(child: Text("La partie n'existe plus."));
          }

          var gameData = snapshot.data!.data() as Map<String, dynamic>;
          var players = (gameData['players'] as Map<String, dynamic>?) ?? {};

          if (!_livekitInitialized &&
              (gameData['videoEnabled'] == true ||
                  gameData['audioEnabled'] == true)) {
            _connectToLivekit(
              gameData['videoEnabled'] == true,
              gameData['audioEnabled'] == true,
            );
          }

          String gameType = gameData['gameType'] ?? '';

          if (gameData['gameState'] == 'playing') {
            WidgetsBinding.instance.addPostFrameCallback((_) {
              if (mounted) {
                Navigator.pushReplacement(
                  context,
                  MaterialPageRoute(
                    builder:
                        (_) => MultiplayerGameScreen(
                          gameCode: gameCode,
                          playerId: currentPlayerId,
                        ),
                  ),
                );
              }
            });
            return const Center(child: Text("La partie commence..."));
          }

          bool isHost = gameData['hostId'] == currentPlayerId;
          bool isTeamGame = ['Codenames', 'Time\'s Up'].contains(gameType);
          Map<int, List<String>> teams = {};
          if (gameData['teams'] != null) {
            (gameData['teams'] as Map<String, dynamic>).forEach((key, value) {
              teams[int.parse(key)] = List<String>.from(value);
            });
          }

          bool canStart = true;
          String requirementMessage = "";

          if (isTeamGame) {
            final int totalAssignedPlayers = teams.values.fold(
              0,
              (sum, team) => sum + team.length,
            );
            if (players.length < 4) {
              canStart = false;
              requirementMessage = "Il faut au moins 4 joueurs.";
            } else if (teams.length < 2) {
              canStart = false;
              requirementMessage = "Veuillez créer au moins 2 équipes.";
            } else if (totalAssignedPlayers != players.length) {
              canStart = false;
              requirementMessage =
                  "Tous les joueurs doivent être assignés à une équipe.";
            } else if (teams.values.any((team) => team.length < 2)) {
              canStart = false;
              requirementMessage =
                  "Chaque équipe doit posséder au moins 2 joueurs.";
            }
          } else {
            switch (gameType) {
              case 'Loup-Garou':
                int selectedRolesCount = 0;
                if (gameData['roleSettings'] != null) {
                  (gameData['roleSettings'] as Map).values.forEach((v) {
                    selectedRolesCount += (v as num).toInt();
                  });
                }
                if (players.length < 5) {
                  canStart = false;
                  requirementMessage = "Au moins 5 joueurs requis.";
                } else if (selectedRolesCount != players.length) {
                  canStart = false;
                  requirementMessage =
                      "Rôles ($selectedRolesCount) ≠ Joueurs (${players.length}).";
                }
                break;
              case 'Zombie!':
                if (players.length != 4) {
                  canStart = false;
                  requirementMessage = "Ce jeu requiert exactement 4 joueurs.";
                }
                break;
              case 'Synonyme ou Banni':
                if (players.length < 3) {
                  canStart = false;
                  requirementMessage = "Au moins 3 joueurs requis.";
                }
                break;
              default:
                if (players.length < 2) {
                  canStart = false;
                  requirementMessage = "Au moins 2 joueurs requis.";
                }
                break;
            }
          }

          return Padding(
            padding: const EdgeInsets.all(16.0),
            child: SingleChildScrollView(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  Card(
                    color: Colors.deepPurple[950]?.withOpacity(0.3),
                    shape: RoundedRectangleBorder(
                      borderRadius: BorderRadius.circular(16),
                      side: const BorderSide(
                        color: Colors.deepPurpleAccent,
                        width: 1,
                      ),
                    ),
                    child: Padding(
                      padding: const EdgeInsets.all(16.0),
                      child: Column(
                        children: [
                          const Text(
                            "PARTAGEZ CE CODE AVEC VOS AMIS",
                            style: TextStyle(
                              color: Colors.white70,
                              fontSize: 12,
                              fontWeight: FontWeight.bold,
                              letterSpacing: 1,
                            ),
                          ),
                          const SizedBox(height: 10),
                          Row(
                            mainAxisAlignment: MainAxisAlignment.center,
                            children: [
                              SelectableText(
                                gameCode,
                                style: Theme.of(
                                  context,
                                ).textTheme.headlineMedium?.copyWith(
                                  fontSize: 36,
                                  letterSpacing: 4,
                                  fontWeight: FontWeight.bold,
                                  color: Colors.amberAccent,
                                ),
                              ),
                              const SizedBox(width: 12),
                              IconButton(
                                icon: const Icon(
                                  Icons.copy,
                                  color: Colors.amberAccent,
                                ),
                                onPressed: () {
                                  Clipboard.setData(
                                    ClipboardData(text: gameCode),
                                  );
                                  ScaffoldMessenger.of(context).showSnackBar(
                                    const SnackBar(
                                      content: Text("Code de salon copié !"),
                                    ),
                                  );
                                },
                              ),
                            ],
                          ),
                        ],
                      ),
                    ),
                  ),
                  const SizedBox(height: 20),
                  Card(
                    child: ListTile(
                      leading: const Icon(
                        Icons.games,
                        color: Colors.cyanAccent,
                      ),
                      title: Text(
                        "Jeu : $gameType",
                        style: const TextStyle(fontWeight: FontWeight.bold),
                      ),
                      subtitle: Text(
                        "Difficulté : ${gameData['difficulty'] ?? 'Standard'}",
                      ),
                    ),
                  ),
                  const SizedBox(height: 20),
                  Text(
                    "Joueurs présents (${players.length})",
                    style: Theme.of(context).textTheme.titleLarge,
                  ),
                  const SizedBox(height: 10),
                  ListView.builder(
                    shrinkWrap: true,
                    physics: const NeverScrollableScrollPhysics(),
                    itemCount: players.length,
                    itemBuilder: (context, idx) {
                      String pId = players.keys.elementAt(idx);
                      var pData = players[pId];
                      bool isPlayerHost = pId == gameData['hostId'];

                      Color? teamColor;
                      int? teamIndex;
                      for (var teamEntry in teams.entries) {
                        if (teamEntry.value.contains(pId)) {
                          teamIndex = teamEntry.key;
                          break;
                        }
                      }

                      if (teamIndex != null) {
                        const List<Color> teamColors = [
                          Colors.redAccent,
                          Colors.blueAccent,
                          Colors.greenAccent,
                          Colors.orangeAccent,
                        ];
                        teamColor = teamColors[teamIndex % teamColors.length]
                            .withOpacity(0.15);
                      }

                      return Card(
                        color: teamColor,
                        child: ListTile(
                          leading: Icon(
                            isPlayerHost
                                ? Icons.admin_panel_settings
                                : Icons.person,
                            color: isPlayerHost ? Colors.amber : Colors.white70,
                          ),
                          title: Text(
                            pData['name'] ?? 'Joueur',
                            style: const TextStyle(fontWeight: FontWeight.bold),
                          ),
                          trailing: const Chip(
                            label: Text("Prêt"),
                            backgroundColor: Colors.green,
                          ),
                        ),
                      );
                    },
                  ),
                  const SizedBox(height: 24),
                  if (isHost) ...[
                    ElevatedButton.icon(
                      icon: const Icon(Icons.person_add),
                      label: const Text("Inviter mes Amis"),

                      onPressed: () {
                        // Ouvre le bottom sheet pour inviter
                        showModalBottomSheet(
                          context: context,
                          backgroundColor: Colors.grey[900],
                          builder: (ctx) {
                            final ps = Provider.of<PlayerState>(
                              context,
                              listen: false,
                            );
                            final myFriends = ps.friends;
                            if (myFriends.isEmpty) {
                              return Container(
                                height: 200,
                                child: Center(
                                  child: Text(
                                    "Vous n'avez pas encore d'amis !",
                                  ),
                                ),
                              );
                            }
                            return Column(
                              children: [
                                Padding(
                                  padding: const EdgeInsets.all(16.0),
                                  child: Text(
                                    "Inviter au salon",
                                    style:
                                        Theme.of(context).textTheme.titleLarge,
                                  ),
                                ),
                                Expanded(
                                  child: ListView.builder(
                                    itemCount: myFriends.length,
                                    itemBuilder: (context, i) {
                                      String fId = myFriends[i];
                                      String fName =
                                          ps.friendNamesCache[fId] ?? 'Ami';
                                      return ListTile(
                                        leading: CircleAvatar(
                                          child: Text(fName[0]),
                                        ),
                                        title: Text(fName),
                                        trailing: ElevatedButton(
                                          style: ElevatedButton.styleFrom(
                                            backgroundColor: Colors.green,
                                          ),
                                          child: Text("Inviter"),
                                          onPressed: () {
                                            ps.sendGameInvite(
                                              fId,
                                              widget.gameCode,
                                            );
                                            ScaffoldMessenger.of(
                                              context,
                                            ).showSnackBar(
                                              SnackBar(
                                                content: Text(
                                                  "Invitation envoyÃ©e Ã  $fName !",
                                                ),
                                              ),
                                            );
                                            Navigator.pop(ctx);
                                          },
                                        ),
                                      );
                                    },
                                  ),
                                ),
                              ],
                            );
                          },
                        );
                      },
                    ),
                  ],

                  if (isHost && isTeamGame)
                    Padding(
                      padding: const EdgeInsets.only(bottom: 8.0),
                      child: OutlinedButton.icon(
                        icon: Icon(Icons.groups),
                        label: Text("Composer les ÃƒÂ©quipes"),
                        onPressed: () {
                          showDialog(
                            context: context,
                            builder:
                                (dContext) => MultiplayerTeamSelectionDialog(
                                  gameCode: gameCode,
                                  players: players,
                                  initialTeams:
                                      teams, // C'ÃƒÂ©tait dÃƒÂ©jÃƒÂ  correct
                                  gameName: gameType,
                                ),
                          );
                        },
                      ),
                    ),
                  if (isHost)
                    ElevatedButton(
                      onPressed:
                          canStart
                              ? () {
                                _firebaseService.startGame(gameCode).catchError(
                                  (e) {
                                    if (mounted) {
                                      ScaffoldMessenger.of(
                                        context,
                                      ).showSnackBar(
                                        SnackBar(
                                          content: Text("Erreur: $e"),
                                          backgroundColor: Colors.red,
                                        ),
                                      );
                                    }
                                  },
                                );
                              }
                              : null,
                      child: Text("DÃƒÂ©marrer la partie"),
                    )
                  else
                    Text(
                      "En attente de l'hÃƒÂ´te...",
                      style: TextStyle(
                        fontStyle: FontStyle.italic,
                        color: Colors.white70,
                      ),
                      textAlign: TextAlign.center,
                    ),
                  if (isHost && !canStart)
                    Padding(
                      padding: const EdgeInsets.only(top: 8.0),
                      child: Text(
                        requirementMessage,
                        textAlign: TextAlign.center,
                        style: TextStyle(color: Colors.amber),
                      ),
                    ),
                ],
              ),
            ),
          );
        },
      ),
    );
  }
}

class MultiplayerGameScreen extends StatefulWidget {
  final String gameCode;
  final String playerId;
  final String? loungeId;

  MultiplayerGameScreen({
    required this.gameCode,
    required this.playerId,
    this.loungeId,
  });

  @override
  _MultiplayerGameScreenState createState() => _MultiplayerGameScreenState();
}

class _MultiplayerGameScreenState extends State<MultiplayerGameScreen>
    with WidgetsBindingObserver {
  void _exitGame() async {
    final String playerId = widget.playerId;

    // Nettoyage complet du salon avant de quitter pour Ã©viter la boucle de redirection
    if (widget.loungeId != null) {
      try {
        final loungeDocRef = FirebaseFirestore.instance
            .collection('lounges')
            .doc(widget.loungeId);
        final loungeSnap = await loungeDocRef.get();

        if (loungeSnap.exists) {
          final loungeData = loungeSnap.data() as Map<String, dynamic>;
          final pendingGame = loungeData['pendingGame'];

          if (pendingGame != null) {
            if (pendingGame['hostId'] == playerId) {
              // Si vous Ãªtes l'hÃ´te, annulez complÃ¨tement le pendingGame pour tout le monde
              await loungeDocRef.update({'pendingGame': FieldValue.delete()});
            } else {
              // Sinon, retirez-vous simplement de la liste des joueurs ayant rejoint
              await loungeDocRef.update({
                'pendingGame.joinedPlayers': FieldValue.arrayRemove([playerId]),
              });
            }
          }
        }
      } catch (e) {
        print("Erreur lors du nettoyage du salon de jeu : $e");
      }

      if (mounted) {
        Navigator.of(context).pop();
      }
    } else {
      Navigator.of(context).popUntil((route) => route.isFirst);
    }
  }

  final FirebaseService _firebaseService = FirebaseService();
  final TextEditingController _answerController = TextEditingController();

  Map<String, String> _playerLivekitIdentities =
      {}; // Mapping playerId -> agoraUid
  final _answerControllers = <String, TextEditingController>{};
  int _lastProcessedRound = 0;
  // Dans _MultiplayerGameScreenState
  Timer? _postGameTimer;
  int _postGameCountdown = 15; // Temps pour voter
  int _refillCountdown = 10; // Temps pour trouver des joueurs
  List<String> _selectedPresidentCards = [];
  List<String> _selectedRamiCards = [];
  List<String> _selectedBigTwoCards = [];
  String? _selectedCheckersPiece; // Pour stocker la piÃ¨ce sÃ©lectionnÃ©e "r,c"
  Timer? _playerTurnTimer;
  String?
  _zeroPointeAction; // Valeurs possibles: 'take_discard', 'use_drawn', 'discard_drawn', null
  // --- Variables Loup Garou (Refonte UX) ---
  String _lgLastSubPhase = '';
  String _lgLastPhase = '';
  bool _showLgTransition = false;
  String _lgTransitionText = '';
  List<String> _lgLocalSelection = [];
  String _lgActionMode = 'normal';
  // DANS _MultiplayerGameScreenState

  // --- BLOKUS ---
  int? _selectedBlokusPieceId;
  int _blokusRotation = 0;
  bool _blokusFlipped = false; // NOUVEAU
  Offset? _blokusPreviewPosition;
  bool _blokusCanPlace = false;
