  // Straight-line drawing mode (used when pictionaryOnly30Strokes == true)
  final GlobalKey _straightLineKey = GlobalKey();
  List<Offset> _straightLinePoints =
      []; // flat pairs [start1, end1, start2, end2, ...]
  Offset? _straightLineStart;
  Offset? _straightLineCurrentEnd;
  String? _viewedOpponentId;

