  Widget _buildBMCSelectionPhase(
    BuildContext context,
    Map<String, dynamic> playedCards,
    Map<String, dynamic> players,
    String judgeId,
    List<String> myHand,
    bool amIJudge,
    String playerId,
  ) {
    int nonJudgeCount = players.length - 1;
    int playedCount = playedCards.length;
    bool hasPlayed = playedCards.containsKey(playerId);

    if (amIJudge) {
      return Column(
        mainAxisAlignment: MainAxisAlignment.center,
        children: [
          Icon(Icons.hourglass_top, size: 48, color: Colors.amberAccent),
          SizedBox(height: 16),
          Text(
            "En attente des cartes des joueurs...",
            style: TextStyle(fontSize: 18, color: Colors.white),
            textAlign: TextAlign.center,
          ),
          SizedBox(height: 8),
          Text(
            "$playedCount / $nonJudgeCount joueurs ont répondu",
            style: TextStyle(
              fontSize: 16,
              color: Colors.white70,
              fontWeight: FontWeight.bold,
            ),
          ),
        ],
      );
    }

    if (hasPlayed) {
      String myPlayedCard = playedCards[playerId] ?? '';
      return Column(
        mainAxisAlignment: MainAxisAlignment.center,
        children: [
          Icon(Icons.check_circle_outline, size: 48, color: Colors.greenAccent),
          SizedBox(height: 12),
          Text(
            "Carte envoyée !",
            style: TextStyle(
              fontSize: 18,
              fontWeight: FontWeight.bold,
              color: Colors.greenAccent,
            ),
          ),
          SizedBox(height: 8),
          Container(
            padding: EdgeInsets.all(12),
            decoration: BoxDecoration(
              color: Colors.white,
              borderRadius: BorderRadius.circular(10),
            ),
            child: Text(
              myPlayedCard,
              style: TextStyle(
                color: Colors.black,
                fontWeight: FontWeight.bold,
              ),
            ),
          ),
          SizedBox(height: 16),
          Text(
            "En attente des autres joueurs ($playedCount / $nonJudgeCount)...",
            style: TextStyle(color: Colors.white54),
          ),
        ],
      );
    }

    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Text(
          "Choisissez votre meilleure réponse :",
          style: TextStyle(color: Colors.white70, fontSize: 14),
        ),
        SizedBox(height: 8),
        Expanded(
          child: ListView.builder(
            scrollDirection: Axis.horizontal,
            itemCount: myHand.length,
            itemBuilder: (context, index) {
              String cardText = myHand[index];
              return GestureDetector(
                onTap:
                    _isActionPending
                        ? null
                        : () {
                          setState(() => _isActionPending = true);
                          _firebaseService
                              .playBMCCard(widget.gameCode, playerId, cardText)
                              .whenComplete(() {
                                if (mounted)
                                  setState(() => _isActionPending = false);
                              });
                        },
                child: Container(
                  width: 140,
                  margin: EdgeInsets.only(right: 12, bottom: 8),
                  padding: EdgeInsets.all(14),
                  decoration: BoxDecoration(
                    color: Colors.white,
                    borderRadius: BorderRadius.circular(14),
                    border: Border.all(color: Colors.grey[300]!, width: 2),
                    boxShadow: [
                      BoxShadow(
                        color: Colors.black38,
                        blurRadius: 6,
                        offset: Offset(2, 4),
                      ),
                    ],
                  ),
                  child: Column(
                    mainAxisAlignment: MainAxisAlignment.spaceBetween,
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        cardText,
                        style: TextStyle(
                          color: Colors.black87,
                          fontSize: 15,
                          fontWeight: FontWeight.w600,
                          height: 1.2,
                        ),
                      ),
                      Align(
                        alignment: Alignment.bottomRight,
                        child: Icon(
                          Icons.touch_app,
                          color: Colors.deepPurple,
                          size: 20,
                        ),
                      ),
                    ],
                  ),
                ),
              );
            },
          ),
        ),
      ],
    );
  }

