                child: Container(
                  padding: EdgeInsets.all(12),
                  decoration: BoxDecoration(
                    color: Colors.white,
                    borderRadius: BorderRadius.circular(12),
                    border: Border.all(
                      color: amIJudge ? Colors.amber : Colors.transparent,
                      width: amIJudge ? 2 : 0,
                    ),
                    boxShadow: [
                      BoxShadow(
                        color: Colors.black26,
                        blurRadius: 6,
                        offset: Offset(0, 3),
                      ),
                    ],
                  ),
                  child: Column(
                    mainAxisAlignment: MainAxisAlignment.spaceBetween,
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Expanded(
                        child: Text(
                          cardText,
                          style: TextStyle(
                            color: Colors.black87,
                            fontSize: 14,
                            fontWeight: FontWeight.w600,
                          ),
                          overflow: TextOverflow.fade,
                        ),
                      ),
                      if (amIJudge)
                        Align(
                          alignment: Alignment.bottomRight,
                          child: Icon(
                            Icons.star,
                            color: Colors.amber[800],
                            size: 24,
                          ),
                        ),
                    ],
                  ),
                ),
              );
            },
          ),
        ),
      ],
    );
  }

  Widget _buildPersistentChatInput(
    String gameCode,
    String playerId,
    String playerName,
    Map<String, dynamic> gameData,
  ) {
    return Container(
      color: Colors.grey[900],
      padding: EdgeInsets.symmetric(horizontal: 8.0, vertical: 4.0),
      child: Row(
        children: [
          Expanded(
            child: TextField(
              controller: _chatController,
              decoration: InputDecoration(
                hintText: "Envoyer un message ou proposer un mot...",
                border: OutlineInputBorder(
                  borderRadius: BorderRadius.circular(20),
                ),
                contentPadding: EdgeInsets.symmetric(
                  horizontal: 16,
                  vertical: 8,
                ),
              ),
              onSubmitted: (text) {
                if (text.trim().isNotEmpty) {
                  bool isPictionaryGuessing =
                      gameData['gameType'] == 'Pictionary' &&
                      (gameData['roundState'] == 'drawing' ||
                          gameData['roundState'] == 'guessing_drawing') &&
                      gameData['currentDrawingPlayerId'] != playerId;

                  if (isPictionaryGuessing) {
                    _firebaseService.submitPictionaryGuess(
                      gameCode,
                      playerId,
                      playerName,
                      text.trim(),
                    );
                  } else {
                    _firebaseService.sendChatMessage(
                      gameCode,
                      playerId,
                      text.trim(),
                      'global',
                    );
                  }
                  _chatController.clear();
                }
              },
            ),
          ),
          IconButton(
            icon: Icon(Icons.send, color: Colors.blue),
            onPressed: () {
              final text = _chatController.text.trim();
              if (text.isNotEmpty) {
                bool isPictionaryGuessing =
                    gameData['gameType'] == 'Pictionary' &&
                    (gameData['roundState'] == 'drawing' ||
                        gameData['roundState'] == 'guessing_drawing') &&
                    gameData['currentDrawingPlayerId'] != playerId;

                if (isPictionaryGuessing) {
                  _firebaseService.submitPictionaryGuess(
                    gameCode,
                    playerId,
                    playerName,
                    text.trim(),
                  );
                } else {
                  _firebaseService.sendChatMessage(
                    gameCode,
                    playerId,
                    text.trim(),
                    'global',
                  );
                }
                _chatController.clear();
              }
            },
          ),
        ],
      ),
    );
  }

  PreferredSizeWidget? _buildTurnTimerIndicator(Map<String, dynamic> gameData) {
    bool useTimer = gameData['useTimer'] ?? true;
    if (!useTimer) return null;

    final turnStartTimeStamp = gameData['turnStartTime'] as Timestamp?;
    final roundState = gameData['roundState'];
    final currentPhase = gameData['currentPhase'];
    final loupGarouPhase = gameData['phase']; // Loup-Garou uses 'phase' field

    // Liste des ÃƒÂ©tats oÃƒÂ¹ le timer doit s'afficher
    final statesWithTimer = [
      'playing_turn', 'player_turn', 'voting', 'result', 'round_end',
      'pre-flop', 'flop', 'turn', 'river', 'hand_over',
      'clue_giving', 'turn_result',
      'answering',
      'guesser_chooses_word',
      'reveal_clues',
      'initial_writing', 'drawing', 'guessing',
      'nuit', 'jour_discussion', 'jour_vote',
      'showing_photo',
      'placing', 'bidding', // <-- AJOUT POUR SKULL
    ];

    bool shouldShow =
        statesWithTimer.contains(roundState) ||
        statesWithTimer.contains(currentPhase) ||
        (loupGarouPhase != null && statesWithTimer.contains(loupGarouPhase));

    if (turnStartTimeStamp == null ||
        gameData['gameState'] != 'playing' ||
        !shouldShow) {
      return null;
    }

    final turnStartTime = turnStartTimeStamp.toDate();

    double turnDurationSeconds =
        (gameData['turnTimerSeconds'] as num?)?.toDouble() ?? 30.0;

    if (roundState == 'result' ||
        roundState == 'round_end' ||
        roundState == 'hand_over' ||
        currentPhase == 'turn_result') {
      turnDurationSeconds =
          (gameData['resultTimerSeconds'] as num?)?.toDouble() ?? 15.0;
    }

    return PreferredSize(
      preferredSize: Size.fromHeight(20.0),
      child: StreamBuilder(
        stream: Stream.periodic(const Duration(milliseconds: 100)),
        builder: (context, snapshot) {
          final elapsedSeconds =
              DateTime.now().difference(turnStartTime).inMilliseconds / 1000.0;
          final progress =
              (turnDurationSeconds - elapsedSeconds) / turnDurationSeconds;
          final remainingSeconds =
              (turnDurationSeconds - elapsedSeconds).ceil();

          if (progress < 0) return const SizedBox.shrink();

          return Stack(
            alignment: Alignment.center,
            children: [
              LinearProgressIndicator(
                value: progress.clamp(0.0, 1.0),
                backgroundColor: Colors.grey[700],
                valueColor: AlwaysStoppedAnimation<Color>(
                  progress > 0.5
                      ? Colors.greenAccent
                      : (progress > 0.2
                          ? Colors.orangeAccent
                          : Colors.redAccent),
                ),
                minHeight: 20,
              ),
              Text(
                "$remainingSeconds",
                style: TextStyle(
                  color: Colors.white,
                  fontWeight: FontWeight.bold,
                  shadows: [
                    Shadow(blurRadius: 2, color: Colors.black.withOpacity(0.8)),
                  ],
                ),
              ),
            ],
          );
        },
      ),
    );
  }

  Widget _buildScoreHeader(
    BuildContext context,
    Map<String, dynamic> players,
    Map<String, dynamic> gameData,
  ) {
    String gameType = gameData['gameType'] ?? '';

    // Liste des jeux où voir la main adverse est pertinent
    bool canViewHands = [
      'Président',
      'Uno',
      'Zéro Pointé',
      'Poker',
      'Big Two', // Ajouté ici !
    ].contains(gameType);

    // Trie les joueurs par score
    List<MapEntry<String, dynamic>> sortedPlayers =
        players.entries.toList()..sort(
          (a, b) => (b.value['score'] ?? 0).compareTo(a.value['score'] ?? 0),
        );

    // Pour Zéro Pointé, on trie par score total croissant (le plus bas gagne)
    if (gameType == 'Zéro Pointé') {
      sortedPlayers.sort((a, b) {
        int scoreA = (gameData['totalScores']?[a.key] ?? 0);
        int scoreB = (gameData['totalScores']?[b.key] ?? 0);
        return scoreA.compareTo(scoreB);
      });
    }

    return Card(
      elevation: 4,
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),
      child: Padding(
        padding: const EdgeInsets.all(8.0),
        child: Container(
          width: double.infinity,
          child: Wrap(
            spacing: 8,
            runSpacing: 8,
            alignment: WrapAlignment.center,
            children:
                sortedPlayers.map((entry) {
                  String pId = entry.key;
                  String pName = entry.value['name'] ?? 'Inconnu';
                  int pScore = entry.value['score'] ?? 0;
                  bool isMe = pId == widget.playerId;
                  bool isSelected = _viewedOpponentId == pId;

                  // Gestion particulière du score pour Zéro Pointé
                  if (gameType == 'Zéro Pointé') {
                    pScore = (gameData['totalScores']?[pId] ?? 0);
                  }

                  return ActionChip(
                    avatar: CircleAvatar(
                      backgroundColor:
                          isMe ? Colors.deepPurpleAccent : Colors.grey[700],
                      child: Text(
                        pName.isNotEmpty ? pName[0].toUpperCase() : "?",
                        style: TextStyle(color: Colors.white, fontSize: 12),
                      ),
                    ),
                    label: Text(
                      "$pName: $pScore",
                    ), // Finis les symboles buggés !
                    backgroundColor:
                        isSelected ? Colors.deepPurple.withOpacity(0.5) : null,
                    side:
                        isSelected
                            ? BorderSide(
                              color: Colors.deepPurpleAccent,
                              width: 2,
                            )
                            : null,
                    onPressed:
                        (canViewHands && !isMe)
                            ? () {
                              setState(() {
                                if (_viewedOpponentId == pId) {
                                  _viewedOpponentId = null;
                                } else {
                                  _viewedOpponentId = pId;
                                }
                              });
                            }
                            : null,
                  );
                }).toList(),
          ),
        ),
      ),
    );
  }

  Widget _buildOpponentHandView(
    Map<String, dynamic> gameData,
    String opponentId,
  ) {
    final String gameType = gameData['gameType'];

    Widget buildFaceDownCard() => Container(
      width: 40,
      height: 60,
      decoration: BoxDecoration(
        color: Colors.indigo,
        borderRadius: BorderRadius.circular(4),
        border: Border.all(color: Colors.white24),
        boxShadow: [
          BoxShadow(color: Colors.black45, offset: Offset(1, 1), blurRadius: 2),
        ],
      ),
    );

    // Fonction Helper pour afficher en éventail
    Widget buildFannedCards(int count, {List<String>? visibleCards}) {
      if (count == 0)
        return Text(
          "N'a plus de cartes",
          style: TextStyle(color: Colors.white70),
        );
      return SizedBox(
        height: 65,
        child: SingleChildScrollView(
          scrollDirection: Axis.horizontal,
          child: Row(
            children: [
              ...List.generate(count, (index) {
                Widget cardWidget;
                if (visibleCards != null && index < visibleCards.length) {
                  cardWidget = _buildCard(
                    card: visibleCards[index],
                    isSelected: false,
                    scale: 0.6,
                  );
                } else {
                  cardWidget = buildFaceDownCard();
                }

                return Align(
                  widthFactor:
                      0.4, // C'EST CECI QUI CRÉE L'EFFET DE SUPERPOSITION
                  alignment: Alignment.centerLeft,
                  child: cardWidget,
                );
              }),
              SizedBox(width: 30), // Marge pour ne pas couper la dernière carte
            ],
          ),
        ),
      );
    }

    Widget buildZeroPointeOpponentGrid() {
      final gridData = List<Map<String, dynamic>>.from(
        gameData['playerGrids']?[opponentId] ?? [],
      );
      if (gridData.isEmpty)
        return Text("Aucune carte", style: TextStyle(color: Colors.white70));

      return Container(
        width: 200,
        child: GridView.builder(
          shrinkWrap: true,
          physics: NeverScrollableScrollPhysics(),
          gridDelegate: SliverGridDelegateWithFixedCrossAxisCount(
            crossAxisCount: 4,
            childAspectRatio: 0.7,
            mainAxisSpacing: 4,
            crossAxisSpacing: 4,
          ),
          itemCount: gridData.length,
          itemBuilder: (context, index) {
            final card = gridData[index];
            if (card['value'] == -100) {
              return Container(
                decoration: BoxDecoration(
                  color: Colors.black.withOpacity(0.2),
                  borderRadius: BorderRadius.circular(4),
                  border: Border.all(color: Colors.white12),
                ),
              );
            } else if (card['revealed'] == true) {
              return Card(
                color: Colors.grey[700],
                child: Center(
                  child: Text(
                    "${card['value']}",
                    style: TextStyle(fontSize: 16, fontWeight: FontWeight.bold),
                  ),
                ),
              );
            } else {
              return buildFaceDownCard();
            }
          },
        ),
      );
    }

    switch (gameType) {
      case 'Président':
        final hand = List<String>.from(
          gameData['playerHands']?[opponentId] ?? [],
        );
        return Column(
          children: [
            Text(
              "${hand.length} cartes restantes",
              style: TextStyle(color: Colors.white70),
            ),
            SizedBox(height: 10),
            buildFannedCards(hand.length),
          ],
        );

      case 'Big Two':
        int count =
            (gameData['bigTwoPlayerHands']?[opponentId] as List?)?.length ?? 0;
        return Column(
          children: [
            Text(
              "$count cartes restantes",
              style: TextStyle(color: Colors.white70),
            ),
            SizedBox(height: 10),
            buildFannedCards(count),
          ],
        );

      case 'Uno':
        final handUno = List<String>.from(
          gameData['unoPlayerHands']?[opponentId] ?? [],
        );
        return Column(
          children: [
            Text(
              "${handUno.length} cartes restantes",
              style: TextStyle(color: Colors.white70),
            ),
            SizedBox(height: 10),
            buildFannedCards(handUno.length),
          ],
        );

      case 'Poker':
        final pData = gameData['playerData']?[opponentId] ?? {};
        final chips = pData['chips'] ?? 0;
        final bet = pData['currentBet'] ?? 0;
        final status = pData['status'] ?? 'out';
        final hand = List<String>.from(pData['hand'] ?? []);
        return Column(
          children: [
            Text(
              "Jetons: $chips \$ | Mise: $bet \$",
              style: TextStyle(
                color: Colors.amberAccent,
                fontWeight: FontWeight.bold,
              ),
            ),
            Text("Statut: $status", style: TextStyle(color: Colors.white70)),
            SizedBox(height: 10),
            (gameData['phase'] == 'showdown' || status == 'all-in')
                ? buildFannedCards(hand.length, visibleCards: hand)
                : buildFannedCards(hand.length),
          ],
        );

      case 'Zéro Pointé':
        return buildZeroPointeOpponentGrid();

      default:
        return SizedBox.shrink();
    }
  }

