    // --- Phase Initiale : RÃƒÂ©vÃƒÂ©ler 2 cartes ---
    if (roundState == 'revealing_initial') {
      int revealedCount = gameData['revealedInitialCardsCount'][playerId] ?? 0;
      return Column(
        mainAxisAlignment: MainAxisAlignment.center,
        children: [
          Text(
