        Wrap(
          spacing: 4,
          runSpacing: 4,
          children:
              cards
                  .map(
                    (c) => Chip(
                      label: Text(c, style: TextStyle(fontSize: 10)),
                      backgroundColor: color.withOpacity(0.2),
                    ),
                  )
                  .toList(),
        ),
      ],
