                    false, // Au Uno, on joue direct, pas de prÃƒÂ©sÃƒÂ©lection
            onCardTap: (card) => _onUnoCardTapped(card),
          ),

        SizedBox(height: 20),

        // 4. BOUTONS D'ACTION
        _buildUnoActionButtons(
          context,
          gameData,
          playerId,
          isMyTurn,
          myHand,
          pendingDraw,
        ),
      ],
    );
  }

