  Widget _buildUnoPlayerHand(
    BuildContext context,
    Map<String, dynamic> gameData,
    bool isMyTurn,
    List<String> myHand,
    String topCard,
    String? wildColorChosen,
    int pendingDraw,
  ) {
    return Expanded(
      child:
          myHand.isEmpty
              ? Center(child: Text("Vous n'avez plus de cartes !"))
              : GridView.builder(
                gridDelegate: SliverGridDelegateWithFixedCrossAxisCount(
                  crossAxisCount: 5,
                  childAspectRatio: 0.7,
                  crossAxisSpacing: 8,
                  mainAxisSpacing: 8,
                ),
                itemCount: myHand.length,
                itemBuilder: (context, index) {
                  String card = myHand[index];
                  bool canPlayNormally = GameData.canPlayUnoCard(
                    card,
                    topCard,
                    wildColorChosen,
                  );
                  bool isPlayableInContext = false;

                  if (isMyTurn && !_isActionPending) {
                    if (pendingDraw > 0) {
                      String cardValue = GameData.getUnoCardValue(card);
                      bool isDrawCard =
                          (cardValue == 'draw2' || cardValue == 'wild_draw4');
                      if (canPlayNormally &&
                          isDrawCard &&
                          (gameData['unoStackDraws'] ?? true)) {
                        isPlayableInContext = true;
                      }
                    } else if (_unoDrawActionDone) {
                      if (card == myHand.last && canPlayNormally) {
                        isPlayableInContext = true;
                      }
                    } else {
                      isPlayableInContext = canPlayNormally;
                    }
                  }

                  return Opacity(
                    opacity: isPlayableInContext ? 1.0 : 0.5,
                    child: _buildUnoCardWidget(
                      card,
                      isTopCard: false,
                      isPlayable: isPlayableInContext,
                    ),
                  );
                },
              ),
    );
  }

  Widget _buildUnoActionButtons(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
    bool isMyTurn,
    List<String> myHand,
    int pendingDraw,
  ) {
    final String? lastActionPlayerId = gameData['unoLastActionPlayerId'];
    final Map<String, dynamic> unoCalledUno = Map<String, dynamic>.from(
      gameData['unoCalledUno'] ?? {},
    );
    final Timestamp? contraDeadline =
        gameData['unoContraDeadline'] as Timestamp?;
    // Le bouton Contre UNO apparaÃƒÂ®t APRÃƒË†S le dÃƒÂ©lai de 3s (le joueur n'a pas dit UNO ÃƒÂ  temps)
    final bool contraDelayPassed =
        contraDeadline != null &&
        DateTime.now().isAfter(contraDeadline.toDate());
    final bool targetHasNotCalledUno =
        lastActionPlayerId != null &&
        !(unoCalledUno[lastActionPlayerId] ?? true);
    final bool canContraUno =
        !isMyTurn &&
        lastActionPlayerId != null &&
        lastActionPlayerId != playerId &&
        targetHasNotCalledUno &&
        contraDelayPassed;
    // Le bouton UNO reste actif tant que le joueur a 1 carte et n'a pas encore dit UNO
    final bool canSayUno =
        myHand.length == 1 &&
        !(unoCalledUno[playerId] ?? true) &&
        contraDeadline != null;

    return Wrap(
      spacing: 12,
      alignment: WrapAlignment.center,
      children: [
        if (isMyTurn && pendingDraw > 0)
          ElevatedButton.icon(
            icon: Icon(Icons.download_for_offline_rounded),
            label: Text("Piocher $pendingDraw cartes"),
            onPressed: _isActionPending ? null : () => _onUnoDrawTapped(),
            style: ElevatedButton.styleFrom(backgroundColor: Colors.red),
          ),
        ElevatedButton.icon(
          icon: Icon(Icons.flash_on),
          label: Text("UNO!"),
          onPressed:
