  Widget _buildUnoCardWidget(
    String card, {
    required bool isTopCard,
    required bool isPlayable,
    String? wildColor,
  }) {
    String color = GameData.getUnoCardColor(card);
    String value = GameData.getUnoCardValue(card);

    Color cardColor = _mapUnoColorToFlutterColor(color);
    Color textColor = Colors.white;
    if (color == 'yellow') textColor = Colors.black;

    String cardText;
    switch (value) {
      case 'skip':
        cardText = 'Ã°Å¸Å¡Â«';
        break;
      case 'reverse':
        cardText = 'Ã°Å¸â€â€ž';
        break;
      case 'draw2':
        cardText = '+2';
        break;
      case 'wild':
        cardText = 'Ã°Å¸Å’Ë†';
        break;
      case 'wild_draw4':
        cardText = '+4';
        break;
      default:
        cardText = value;
        break;
    }

    if (isTopCard &&
        wildColor != null &&
        (value == 'wild' || value == 'wild_draw4')) {
      cardColor = _mapUnoColorToFlutterColor(wildColor);
      if (wildColor == 'yellow') textColor = Colors.black;
    }

    return GestureDetector(
      onTap: isPlayable ? () => _onUnoCardTapped(card) : null,
      child: Container(
        width: 70,
        height: 100,
        decoration: BoxDecoration(
          color: cardColor,
          borderRadius: BorderRadius.circular(8),
          border: Border.all(color: Colors.white24, width: 1),
          boxShadow:
              isPlayable
                  ? [
                    BoxShadow(
                      color: Colors.greenAccent.withOpacity(0.7),
                      blurRadius: 10,
                      spreadRadius: 2,
                    ),
                  ]
                  : [],
        ),
        child: Center(
          child: Text(
            cardText,
            style: TextStyle(
              fontSize: 24,
              fontWeight: FontWeight.bold,
              color: textColor,
              shadows: [
                Shadow(blurRadius: 1, color: Colors.black.withOpacity(0.5)),
              ],
            ),
          ),
        ),
      ),
    );
  }

  Color _mapUnoColorToFlutterColor(String unoColor) {
    switch (unoColor) {
      case 'red':
        return Colors.red;
      case 'yellow':
        return Colors.yellow;
      case 'green':
        return Colors.green;
      case 'blue':
        return Colors.blue;
      case 'wild':
        return Colors.black;
      default:
        return Colors.grey;
    }
  }

  void _onUnoCardTapped(String card) async {
    if (_isActionPending) return;

    final String playerId = widget.playerId;
    String cardValue = GameData.getUnoCardValue(card);

    if (cardValue == 'wild' || cardValue == 'wild_draw4') {
      _showColorPicker(card);
    } else {
      setState(() => _isActionPending = true);
      try {
        await _firebaseService.playUnoCard(widget.gameCode, playerId, card);
      } catch (e) {
        if (mounted)
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(
              content: Text(
                "Erreur: ${e.toString().replaceAll('Exception: ', '')}",
              ),
            ),
          );
      } finally {
        if (mounted) setState(() => _isActionPending = false);
      }
    }
  }

  // Animation visuelle simple : Fait apparaÃƒÂ®tre une carte au centre qui descend vers le bas
  // Animation visuelle simple : Fait apparaÃƒÂ®tre une carte au centre qui descend vers le bas
  void _animateCardFly(BuildContext context) {
    OverlayEntry? entry;

    entry = OverlayEntry(
      builder: (context) {
        // DÃƒÂ©marre au centre (deck) et va vers le bas (main)
        return TweenAnimationBuilder<double>(
          tween: Tween(begin: 0.0, end: 1.0),
          duration: Duration(milliseconds: 600),
          curve: Curves.easeInOutCubic,
          onEnd: () {
            entry?.remove(); // On nettoie ÃƒÂ  la fin
          },
          builder: (context, value, child) {
            // Interpolation de position
            // Start: Centre ÃƒÂ©cran (MediaQuery / 2)
            // End: Bas ÃƒÂ©cran (Main du joueur)
            final size = MediaQuery.of(context).size;
            final startY = size.height * 0.4; // Un peu au-dessus du centre
            final endY = size.height * 0.85; // Vers la main

            final currentY = startY + (endY - startY) * value;
            final scale =
                0.5 +
                (0.5 * value); // La carte grandit en approchant (effet 3D)

            return Positioned(
              top: currentY,
              left:
                  (size.width / 2) -
                  30, // CentrÃƒÂ© horizontalement (- moitiÃƒÂ© largeur carte)
              child: Opacity(
                opacity:
                    1.0 -
                    value * 0.5, // Disparait doucement en arrivant dans la main
                child: Transform.scale(
                  scale: scale,
                  child: Container(
                    width: 60,
                    height: 90,
                    decoration: BoxDecoration(
                      color: Colors.white,
                      borderRadius: BorderRadius.circular(8),
                      border: Border.all(color: Colors.white),
                      boxShadow: [
                        BoxShadow(color: Colors.black54, blurRadius: 10),
                      ],
                    ),
                    // Dos de carte gÃƒÂ©nÃƒÂ©rique
                    child: Center(child: Icon(Icons.style, color: Colors.red)),
                  ),
                ),
              ),
            );
          },
        );
      },
    );

    Overlay.of(context).insert(entry);
  }

  void _onUnoDrawTapped() async {
    if (_isActionPending) return;
    _animateCardFly(context);

    setState(() => _isActionPending = true);

    final String playerId = widget.playerId;

    try {
      await _firebaseService.drawUnoCard(widget.gameCode, playerId);
    } catch (e) {
      if (mounted)
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text(
              "Erreur: ${e.toString().replaceAll('Exception: ', '')}",
            ),
          ),
        );
    } finally {
      if (mounted) setState(() => _isActionPending = false);
    }
  }

