  Widget _buildDobbleUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final String roundState = gameData['roundState'] ?? 'waiting';
    final List<String> centerCard =
        gameData['dobbleCenterCard'] != null
            ? List<String>.from(gameData['dobbleCenterCard'])
            : [];
    final Map<String, dynamic> playerCards =
        gameData['dobblePlayerCards'] != null
            ? Map<String, dynamic>.from(gameData['dobblePlayerCards'])
            : {};
    final List<String> myCard =
        playerCards[playerId] != null
            ? List<String>.from(playerCards[playerId])
            : [];
    final Map<String, dynamic> players = Map<String, dynamic>.from(
      gameData['players'] ?? {},
    );

    // RÃƒÂ©cupÃƒÂ©ration des infos pour le HUD
    final List<dynamic> deck = gameData['dobbleDeck'] ?? [];
    final int cardsLeftInDeck = deck.length;
    final int myScore = players[playerId]?['score'] ?? 0;

    // Gestion Game Over
    if (gameData['gameState'] == 'gameOver') {
      List<MapEntry<String, dynamic>> sortedPlayers =
          players.entries.toList()..sort(
            (a, b) => (b.value['score'] ?? 0).compareTo(a.value['score'] ?? 0),
          );
      String winnerName =
          sortedPlayers.isNotEmpty
              ? sortedPlayers.first.value['name']
              : "Personne";

      return Center(
        child: Card(
          elevation: 10,
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(20),
          ),
          child: Padding(
            padding: const EdgeInsets.all(24.0),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                Text(
                  "Partie TerminÃƒÂ©e !",
                  style: Theme.of(context).textTheme.headlineMedium?.copyWith(
                    color: Colors.deepPurple,
                    fontWeight: FontWeight.bold,
                  ),
                ),
                SizedBox(height: 10),
                Text(
                  "Vainqueur : $winnerName",
                  style: TextStyle(
                    fontSize: 20,
                    color: Colors.amber[800],
                    fontWeight: FontWeight.bold,
                  ),
                ),
                Text(
                  "avec ${sortedPlayers.first.value['score']} cartes",
                  style: TextStyle(color: Colors.grey[600]),
                ),
                SizedBox(height: 20),
                ElevatedButton(
                  onPressed:
                      () => Navigator.of(
                        context,
                      ).popUntil((route) => route.isFirst),
                  child: Text("Retour ÃƒÂ  l'accueil"),
                ),
              ],
            ),
          ),
        ),
      );
    }

    // Chargement initial
    if (myCard.isEmpty || centerCard.isEmpty) {
      return Center(
        child: _buildWaitingWidget("Distribution des cartes...", players, 0, 0),
      );
    }

    // Fond d'ÃƒÂ©cran style "Table de jeu"
    return Container(
      width: double.infinity,
      height: double.infinity,
      decoration: BoxDecoration(
        gradient: LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: [
            Color(0xFF2C3E50),
            Color(0xFF4CA1AF),
          ], // DÃƒÂ©gradÃƒÂ© Bleu Gris Pro
        ),
      ),
      child: SafeArea(
        child:
            roundState == 'playing'
                ? _buildDobblePlayingUI(
                  context,
                  gameData,
                  playerId,
                  centerCard,
                  myCard,
                  players,
                  cardsLeftInDeck,
                  myScore,
                )
                : _buildDobbleResultUI(
                  context,
                  gameData,
                  playerId,
                  gameData['roundWinnerId'],
                  gameData['commonSymbol'],
                ),
      ),
    );
  }

