  String _getLgTransitionLogs(
    String phase,
    String subPhase,
    List<dynamic> logs,
  ) {
    if (logs.isEmpty) return "";
    if (phase == 'nuit' && subPhase == 'initial') {
      return "La nuit tombe sur le village...\n\nFermez les yeux.";
    } else if (phase == 'jour_discussion' && subPhase.isEmpty) {
      List<String> morningLogs = [];
      for (int i = logs.length - 1; i >= 0; i--) {
        String log = logs[i].toString();
        morningLogs.insert(0, log);
        if (log.contains("Le soleil se lÃ¨ve")) break;
      }
      return morningLogs.join("\n\n");
    } else if (phase == 'jour_vote') {
      return "Le moment est venu...\n\nLe village doit voter.";
    }
    return "";
  }

  Widget _buildLoupGarouUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final String phase = gameData['phase'] ?? 'lobby';
    final String subPhase = gameData['subPhase'] ?? '';
    final Map<String, dynamic> playerData = Map<String, dynamic>.from(
      gameData['playerData'] ?? {},
    );
    final List<String> playerOrder = List<String>.from(
      gameData['playerOrder'] ?? [],
    );
    final List<dynamic> gameLog = List<dynamic>.from(gameData['gameLog'] ?? []);
    final Map<String, dynamic> nightActions = Map<String, dynamic>.from(
      gameData['nightActions'] ?? {},
    );
    final Map<String, dynamic> dayVotes = Map<String, dynamic>.from(
      gameData['dayVotes'] ?? {},
    );
    final String? captainId = gameData['captainId'];
    final List<String> lovers = List<String>.from(gameData['lovers'] ?? []);
    final int nightNumber = gameData['nightNumber'] ?? 0;

    final myData = playerData[playerId] ?? {};
    final myRole = myData['role'] ?? 'Inconnu';
    final myStatus = myData['status'] ?? 'vivant';
    final myPrivateInfo = myData['privateInfo'];
    final bool amILoup =
        GameData.roleCamps[myRole] == 'loups' ||
        myData['infectionStatus'] == 'infecte';
    final bool isHost = gameData['hostId'] == playerId;

    // --- Gestion des transitions d'histoire ---
    if (_lgLastSubPhase != subPhase || _lgLastPhase != phase) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted) {
          setState(() {
            _lgLastSubPhase = subPhase;
            _lgLastPhase = phase;
            _lgLocalSelection.clear();
            _lgActionMode = 'normal';
            _lgTransitionText = _getLgTransitionLogs(phase, subPhase, gameLog);
            if (_lgTransitionText.isNotEmpty) {
              _showLgTransition = true;
              Timer(const Duration(seconds: 4), () {
                if (mounted) setState(() => _showLgTransition = false);
              });
            }
          });
        }
      });
    }

    String promptText = "En attente...";
    Widget? actionWidget; // Boutons additionnels (Valider, Empoisonner, etc)

    // Calcul des votes reÃ§us
    Map<String, List<String>> votesReceived = {};
    if (phase == 'jour_vote') {
      dayVotes.forEach((voterId, targetId) {
        final voterName = playerData[voterId]?['name'] ?? 'Inconnu';
        votesReceived.putIfAbsent(targetId, () => []).add(voterName);
      });
    } else if (phase == 'nuit' && subPhase == 'loups_turn') {
      if (nightActions['votes'] != null) {
        (nightActions['votes'] as Map<String, dynamic>).forEach((
          voterId,
          targetId,
        ) {
          final voterName = playerData[voterId]?['name'] ?? 'Un Loup';
          votesReceived.putIfAbsent(targetId, () => []).add(voterName);
        });
      }
    }

    List<String> contaminatedPlayers = List<String>.from(
      gameData['ratMaladeContaminated'] ?? [],
    );

    // Fonction de vÃ©rification de ciblÃ©
    bool canSelectTarget(String targetId) {
      if (targetId == playerId &&
          !(subPhase == 'garde_turn' || subPhase == 'cupidon_turn'))
        return false; // Ne peut pas se cibler sauf cas spÃ©ciaux
      if (playerData[targetId]?['status'] != 'vivant')
        return false; // Doit Ãªtre vivant

      if (phase == 'nuit') {
        switch (subPhase) {
          case 'cupidon_turn':
            return myRole == 'Cupidon' &&
                myStatus == 'vivant' &&
                lovers.isEmpty &&
                !lovers.contains(targetId);
          case 'heritier_turn':
            return myRole == 'HÃ©ritier' &&
                myStatus == 'vivant' &&
                myData['testateurId'] == null;
          case 'garde_turn':
            return myRole == 'Garde' &&
                myStatus == 'vivant' &&
                nightActions['gardeActed'] != true &&
                myData['lastProtectedId'] != targetId;
          case 'voyante_turn':
            return myRole == 'Voyante' &&
                myStatus == 'vivant' &&
                nightActions['voyanteActed'] != true;
          case 'rat_malade_turn':
            return myRole == 'Rat Malade' &&
                myStatus == 'vivant' &&
                !contaminatedPlayers.contains(targetId);
          case 'loups_turn':
            bool targetIsLoup =
                GameData.roleCamps[playerData[targetId]?['role']] == 'loups' ||
                playerData[targetId]?['infectionStatus'] == 'infecte';
            if (amILoup && myStatus == 'vivant') return !targetIsLoup;
            if (myRole == 'Petite Fille' && myStatus == 'vivant' && !amILoup)
              return true; // La petite fille espionne
            return false;
          case 'loup_blanc_turn':
            return myRole == 'Loup Blanc' &&
                myStatus == 'vivant' &&
                nightNumber % 2 != 0 &&
                nightActions['loupBlancActed'] != true;
          case 'sorciere_turn':
            return myRole == 'SorciÃ¨re' &&
                myStatus == 'vivant' &&
                _lgActionMode == 'poison' &&
                myData['potions']?['poison'] == true;
          case 'pyromancien_turn':
            return myRole == 'Pyromancien' &&
                myStatus == 'vivant' &&
                _lgActionMode == 'placer_tonneau';
        }
      } else if (phase == 'jour_discussion') {
        if (subPhase == 'captain_designate')
          return gameData['activePlayerId'] == playerId;
        if (subPhase == 'chasseur_revenge')
          return gameData['activePlayerId'] == playerId;
        if (subPhase == 'fossoyeur_reveal')
          return gameData['activePlayerId'] == playerId;
        if (subPhase == 'dictateur_coup')
          return gameData['activePlayerId'] == playerId;
      } else if (phase == 'jour_vote') {
        return myStatus == 'vivant' && !dayVotes.containsKey(playerId);
      }
      return false;
    }

    // Gestion de l'action selon la phase
    void handleTargetSelection(String targetId) async {
      if (_isActionPending) return;

      if (phase == 'nuit') {
        switch (subPhase) {
          case 'cupidon_turn':
          case 'rat_malade_turn':
            setState(() {
              if (_lgLocalSelection.contains(targetId)) {
                _lgLocalSelection.remove(targetId);
              } else {
                if (subPhase == 'cupidon_turn' && _lgLocalSelection.length < 2)
                  _lgLocalSelection.add(targetId);
                if (subPhase == 'rat_malade_turn' &&
                    _lgLocalSelection.length < 2)
                  _lgLocalSelection.add(targetId);
              }
            });
            break;
          case 'heritier_turn':
            setState(() => _isActionPending = true);
            await _firebaseService.heritierChooseTestateur(
              widget.gameCode,
              playerId,
              targetId,
            );
            setState(() => _isActionPending = false);
            break;
          case 'garde_turn':
            setState(() => _isActionPending = true);
            await _firebaseService.gardeProtect(
              widget.gameCode,
              playerId,
              targetId,
            );
            setState(() => _isActionPending = false);
            break;
          case 'voyante_turn':
            setState(() => _isActionPending = true);
            await _firebaseService.voyanteSee(
              widget.gameCode,
              playerId,
              targetId,
            );
            setState(() => _isActionPending = false);
            break;
          case 'loups_turn':
            setState(() => _isActionPending = true);
            if (amILoup)
              await _firebaseService.loupGarouVote(
                widget.gameCode,
                playerId,
                targetId,
              );
            if (myRole == 'Petite Fille')
              await _firebaseService.petiteFilleSpy(
                widget.gameCode,
                playerId,
                targetId,
              );
            setState(() => _isActionPending = false);
            break;
          case 'loup_blanc_turn':
            setState(() => _isActionPending = true);
            await _firebaseService.loupBlancDevour(
              widget.gameCode,
              playerId,
              targetId,
            );
            setState(() => _isActionPending = false);
            break;
          case 'sorciere_turn':
            if (_lgActionMode == 'poison') {
              setState(() => _isActionPending = true);
              await _firebaseService.sorciereUsePotion(
                widget.gameCode,
                playerId,
                'poison',
                targetId,
              );
              setState(() {
                _isActionPending = false;
                _lgActionMode = 'normal';
              });
            }
            break;
          case 'pyromancien_turn':
            if (_lgActionMode == 'placer_tonneau') {
              setState(() => _isActionPending = true);
              await _firebaseService.pyromancienAct(
                widget.gameCode,
                playerId,
                'place',
                targetId,
              );
              setState(() {
                _isActionPending = false;
                _lgActionMode = 'normal';
              });
            }
            break;
        }
      } else if (phase == 'jour_discussion') {
        setState(() => _isActionPending = true);
        if (subPhase == 'captain_designate')
          await _firebaseService.captainDesignate(
            widget.gameCode,
            playerId,
            targetId,
          );
        if (subPhase == 'chasseur_revenge')
          await _firebaseService.chasseurShoot(
            widget.gameCode,
            playerId,
            targetId,
          );
        if (subPhase == 'fossoyeur_reveal')
          await _firebaseService.fossoyeurReveal(
            widget.gameCode,
            playerId,
            targetId,
          );
        if (subPhase == 'dictateur_coup')
          await _firebaseService.dictateurCoup(
            widget.gameCode,
            playerId,
            targetId,
          );
        setState(() => _isActionPending = false);
      } else if (phase == 'jour_vote') {
        setState(() => _isActionPending = true);
        await _firebaseService.submitDayVote(
          widget.gameCode,
          playerId,
          targetId,
        );
        setState(() => _isActionPending = false);
      }
    }

    // --- SETUP DES MESSAGES ET BOUTONS SPÉCIAUX ---
    if (phase == 'nuit') {
      promptText = "Le village s'endort...";
      switch (subPhase) {
        case 'cupidon_turn':
          promptText =
              lovers.isEmpty
                  ? "Sélectionnez DEUX amoureux."
                  : "Amoureux désignés !";
          if (myRole == 'Cupidon' && myStatus == 'vivant' && lovers.isEmpty) {
            actionWidget = ElevatedButton(
              onPressed:
                  _lgLocalSelection.length == 2 && !_isActionPending
                      ? () async {
                        setState(() => _isActionPending = true);
                        for (String tgt in _lgLocalSelection) {
                          await _firebaseService.selectCupidonLover(
                            widget.gameCode,
                            playerId,
                            tgt,
                          );
                        }
                        setState(() {
                          _isActionPending = false;
                          _lgLocalSelection.clear();
                        });
                      }
                      : null,
              child: Text("Valider les Amoureux"),
            );
          }
          break;
        case 'heritier_turn':
          promptText = "L'Héritier choisit son testateur.";
          if (myRole == 'Héritier' &&
              myStatus == 'vivant' &&
              myData['testateurId'] == null)
            promptText = "Touchez le joueur dont vous voulez hériter.";
          break;
        case 'garde_turn':
          promptText = "Le Garde choisit qui protéger.";
          if (myRole == 'Garde' &&
              myStatus == 'vivant' &&
              nightActions['gardeActed'] != true)
            promptText = "Touchez le joueur à protéger cette nuit.";
          break;
        case 'voyante_turn':
          promptText = "La Voyante sonde une âme.";
          if (myRole == 'Voyante' &&
              myStatus == 'vivant' &&
              nightActions['voyanteActed'] != true)
            promptText = "Touchez un joueur pour connaître son rôle.";
          break;
        case 'rat_malade_turn':
          promptText = "Le Rat Malade propage la maladie...";
          if (myRole == 'Rat Malade' && myStatus == 'vivant') {
            promptText = "Sélectionnez jusqu'à 2 joueurs à contaminer.";
            actionWidget = ElevatedButton(
              onPressed:
                  _lgLocalSelection.isNotEmpty && !_isActionPending
                      ? () async {
                        setState(() => _isActionPending = true);
                        await _firebaseService.ratMaladeContaminate(
                          widget.gameCode,
                          playerId,
                          _lgLocalSelection,
                        );
                        setState(() {
                          _isActionPending = false;
                          _lgLocalSelection.clear();
                        });
                      }
                      : null,
              child: Text("Contaminer"),
            );
          }
          break;
        case 'loups_turn':
          promptText = "Les Loups se réveillent et dévorent.";
          if (amILoup && myStatus == 'vivant')
            promptText = "Touchez votre victime...";
          if (myRole == 'Petite Fille' && myStatus == 'vivant' && !amILoup)
            promptText = "Touchez quelqu'un pour espionner...";
          break;
        case 'loup_noir_action':
          promptText = "Le Loup Noir observe la victime...";
          String? loupNoirId =
              playerData.entries
                  .firstWhere(
                    (e) =>
                        e.value['role'] == 'Loup Noir' &&
                        e.value['status'] == 'vivant',
                    orElse: () => MapEntry('', {}),
                  )
                  .key;
          if (loupNoirId == playerId &&
              myStatus == 'vivant' &&
              !(myData['infectionUsed'] ?? true) &&
              nightActions['loupTarget'] != null) {
            String targetName =
                playerData[nightActions['loupTarget']]?['name'] ?? 'la victime';
            promptText = "Victime : $targetName.";
            actionWidget = Row(
              mainAxisAlignment: MainAxisAlignment.center,
              children: [
                ElevatedButton(
                  style: ElevatedButton.styleFrom(
                    backgroundColor: Colors.purple,
                  ),
                  onPressed:
                      () => _firebaseService.loupNoirInfect(
                        widget.gameCode,
                        playerId,
                        true,
                      ),
                  child: Text("Infecter"),
                ),
                SizedBox(width: 10),
                ElevatedButton(
                  style: ElevatedButton.styleFrom(backgroundColor: Colors.red),
                  onPressed:
                      () => _firebaseService.loupNoirInfect(
                        widget.gameCode,
                        playerId,
                        false,
                      ),
                  child: Text("Laisser mourir"),
                ),
              ],
            );
          }
          break;
        case 'loup_blanc_turn':
          promptText = "Le Loup Blanc peut dévorer un joueur.";
          if (myRole == 'Loup Blanc' &&
              myStatus == 'vivant' &&
              nightNumber % 2 != 0 &&
              nightActions['loupBlancActed'] != true) {
            promptText = "Touchez votre victime.";
          }
          break;
        case 'sorciere_turn':
          promptText = "La Sorcière se réveille...";
          if (myRole == 'Sorcière' &&
              myStatus == 'vivant' &&
              nightActions['sorciereActed'] != true) {
            final victimeId = nightActions['loupTarget'];
            final victimeName = playerData[victimeId]?['name'] ?? 'personne';
            promptText = "Victime des loups : $victimeName";
            if (_lgActionMode == 'poison')
              promptText = "Touchez le joueur à empoisonner.";

            actionWidget = Row(
              mainAxisAlignment: MainAxisAlignment.center,
              children: [
                if (myData['potions']?['guerison'] == true && victimeId != null)
                  ElevatedButton(
                    style: ElevatedButton.styleFrom(
                      backgroundColor: Colors.green,
                    ),
                    onPressed:
                        () => _firebaseService.sorciereUsePotion(
                          widget.gameCode,
                          playerId,
                          'guerison',
                          victimeId,
                        ),
                    child: Text("Guérir"),
                  ),
                SizedBox(width: 10),
                if (myData['potions']?['poison'] == true)
                  ElevatedButton(
                    style: ElevatedButton.styleFrom(
                      backgroundColor:
                          _lgActionMode == 'poison'
                              ? Colors.purpleAccent
                              : Colors.purple,
                    ),
                    onPressed:
                        () => setState(
                          () =>
                              _lgActionMode =
                                  _lgActionMode == 'poison'
                                      ? 'normal'
                                      : 'poison',
                        ),
                    child: Text("Empoisonner"),
                  ),
                SizedBox(width: 10),
                ElevatedButton(
                  onPressed:
                      () => _firebaseService.sorciereUsePotion(
                        widget.gameCode,
                        playerId,
                        'rien',
                        null,
                      ),
                  child: Text("Rien"),
                ),
              ],
            );
          }
          break;
        case 'pyromancien_turn':
          promptText = "Le Pyromancien manie le feu...";
          if (myRole == 'Pyromancien' && myStatus == 'vivant') {
            if (_lgActionMode == 'placer_tonneau')
              promptText = "Touchez le joueur chez qui placer le tonneau.";
            actionWidget = Row(
              mainAxisAlignment: MainAxisAlignment.center,
              children: [
                ElevatedButton(
                  style: ElevatedButton.styleFrom(
                    backgroundColor:
                        _lgActionMode == 'placer_tonneau'
                            ? Colors.orangeAccent
                            : Colors.orange,
                  ),
                  onPressed:
                      () => setState(
                        () =>
                            _lgActionMode =
                                _lgActionMode == 'placer_tonneau'
                                    ? 'normal'
                                    : 'placer_tonneau',
                      ),
                  child: Text("Placer"),
                ),
                SizedBox(width: 10),
                ElevatedButton(
                  style: ElevatedButton.styleFrom(backgroundColor: Colors.red),
                  onPressed:
                      () => _firebaseService.pyromancienAct(
                        widget.gameCode,
                        playerId,
                        'detonate',
                        null,
                      ),
                  child: Text("DÃ©toner"),
                ),
              ],
            );
          }
          break;
      }
    } else if (phase == 'jour_discussion') {
      promptText = "Le village dÃ©bat...";
      if (subPhase == 'captain_designate') {
        promptText = "Le Capitaine dÃ©signe son successeur.";
        if (gameData['activePlayerId'] == playerId)
          promptText = "Touchez votre successeur.";
      } else if (subPhase == 'chasseur_revenge') {
        promptText = "Le Chasseur se venge.";
        if (gameData['activePlayerId'] == playerId)
          promptText = "Touchez la cible Ã  abattre.";
      } else if (subPhase == 'fossoyeur_reveal') {
        promptText = "Le Fossoyeur rÃ©vÃ¨le une tombe.";
        if (gameData['activePlayerId'] == playerId)
          promptText = "Touchez le joueur Ã  rÃ©vÃ©ler.";
      } else if (subPhase == 'dictateur_coup') {
        promptText = "Le Dictateur s'empare du pouvoir.";
        if (gameData['activePlayerId'] == playerId)
          promptText = "Touchez le joueur Ã  exÃ©cuter.";
      } else {
        if (myRole == 'Dictateur' &&
            myStatus == 'vivant' &&
            !(myData['powerUsed'] ?? false) &&
            !(gameData['dictatorUsed'] ?? false)) {
          actionWidget = ElevatedButton.icon(
            icon: Icon(Icons.gavel),
            label: Text("Coup d'Ã‰tat"),
            style: ElevatedButton.styleFrom(
              backgroundColor: Colors.purple[800],
            ),
            onPressed:
                () => _firebaseService.triggerDictateurCoup(
                  widget.gameCode,
                  playerId,
                ),
          );
        }
        if (isHost) {
          actionWidget = ElevatedButton(
            onPressed:
                () => _firebaseService.startDayVotePhase(widget.gameCode),
            child: Text("Lancer la phase de vote"),
          );
        }
      }
    } else if (phase == 'jour_vote') {
      promptText = "Il est temps de voter.";
      if (myStatus == 'vivant' && !dayVotes.containsKey(playerId)) {
        promptText = "Touchez le joueur Ã  Ã©liminer.";
      } else if (isHost) {
        actionWidget = ElevatedButton(
          onPressed: () => _firebaseService.processDayVote(widget.gameCode),
          child: Text("Forcer la fin du vote"),
        );
      }
    } else if (phase == 'gameOver') {
      promptText = "Partie TerminÃ©e !";
      actionWidget = Column(
        children: [
          Text(
            gameLog.last,
            style: Theme.of(context).textTheme.titleLarge,
            textAlign: TextAlign.center,
          ),
          SizedBox(height: 10),
          ElevatedButton(
            onPressed: () => _exitGame(),
            child: Text("Retour Ã  l'accueil"),
          ),
          if (isHost)
            ElevatedButton(
              style: ElevatedButton.styleFrom(backgroundColor: Colors.green),
              onPressed:
                  () => _firebaseService.resetLoupGarouGame(widget.gameCode),
              child: Text("Rejouer !"),
            ),
        ],
      );
    }

    final bool canSeeLovers = lovers.contains(playerId) || myRole == 'Cupidon';

    return Stack(
      children: [
        // 1. Fond et Cercle des Joueurs
        Positioned.fill(
          child: LayoutBuilder(
            builder: (context, constraints) {
              // Ajustement du cercle pour laisser de la place au tchat
              final double centerX = constraints.maxWidth / 2;
              final double centerY =
                  constraints.maxHeight * 0.45; // LÃ©gÃ¨rement plus haut
              final double radius =
                  min(constraints.maxWidth, constraints.maxHeight) * 0.38;
              const double avatarHalfSize = 30.0;

              return Stack(
                children:
                    playerOrder.map((pId) {
                      final int index = playerOrder.indexOf(pId);
                      final double angle =
                          (2 * pi * index) / playerOrder.length - (pi / 2);
                      final pData = playerData[pId] ?? {};
                      final x = radius * cos(angle);
                      final y = radius * sin(angle);

                      bool isSelectable = canSelectTarget(pId);
                      bool isSelected = _lgLocalSelection.contains(pId);

                      return Positioned(
                        left: centerX + x - avatarHalfSize,
                        top: centerY + y - avatarHalfSize,
                        child: _buildPlayerAvatar(
                          pData,
                          pId,
                          pId == playerId,
                          votesReceived[pId],
                          captainId,
                          lovers,
                          amILoup,
                          nightNumber,
                          currentRoundState: phase,
                          contaminatedPlayers: contaminatedPlayers,
                          canSeeLovers: canSeeLovers,
                          isSelectable: isSelectable,
                          isSelected: isSelected,
                          onTap: () => handleTargetSelection(pId),
                        ),
                      );
                    }).toList(),
              );
            },
          ),
        ),

        // 2. Barre d'Infos SupÃ©rieure
        Positioned(
          top: 10,
          left: 10,
          right: 10,
          child: Card(
            color: Colors.black.withOpacity(0.6),
            shape: RoundedRectangleBorder(
              borderRadius: BorderRadius.circular(15),
            ),
            child: Padding(
              padding: const EdgeInsets.symmetric(
                vertical: 8.0,
                horizontal: 16.0,
              ),
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  if (myPrivateInfo != null)
                    Text(
                      myPrivateInfo,
                      style: TextStyle(
                        color: Colors.lightBlueAccent,
                        fontStyle: FontStyle.italic,
                        fontSize: 12,
                      ),
                      textAlign: TextAlign.center,
                    ),
                  Text(
                    "RÃ´le : $myRole",
                    style: TextStyle(
                      fontWeight: FontWeight.bold,
                      color: Colors.amberAccent,
                      fontSize: 16,
                    ),
                  ),
                  Text(
                    promptText,
                    style: TextStyle(color: Colors.white, fontSize: 14),
                    textAlign: TextAlign.center,
                  ),
                ],
              ),
            ),
          ),
        ),

        // 3. Actions / Boutons au Centre
        if (actionWidget != null)
          Positioned(
            top: 120,
            left: 20,
            right: 20,
            child: Center(
              child: Container(
                padding: EdgeInsets.all(12),
                decoration: BoxDecoration(
                  color: Colors.black87,
                  borderRadius: BorderRadius.circular(20),
                  border: Border.all(color: Colors.white24),
                ),
                child: actionWidget,
              ),
            ),
          ),

        // 4. Tchat en bas Ã  gauche faÃ§on "Live"
        Positioned(
          bottom: 10,
          left: 10,
          width:
              MediaQuery.of(context).size.width *
              0.75, // Prend 75% de la largeur
          height:
              MediaQuery.of(context).size.height * 0.35, // 35% de la hauteur
          child: _buildChatInterface(gameData, playerId, isLiveStyle: true),
        ),

        // 5. Overlay Narratif de Transition
        if (_showLgTransition)
          Positioned.fill(
            child: AnimatedOpacity(
              opacity: _showLgTransition ? 1.0 : 0.0,
              duration: Duration(milliseconds: 500),
              child: Container(
                color: Colors.black.withOpacity(0.9),
                child: Center(
                  child: Padding(
                    padding: const EdgeInsets.all(32.0),
                    child: Text(
                      _lgTransitionText,
                      textAlign: TextAlign.center,
                      style: TextStyle(
                        fontSize: 26,
                        color: Colors.white,
                        fontWeight: FontWeight.bold,
                        height: 1.4,
                        shadows: [
                          Shadow(color: Colors.redAccent, blurRadius: 10),
                        ],
                      ),
                    ),
                  ),
                ),
              ),
            ),
          ),
      ],
    );
  }

  // --- MISE Ã€ JOUR DE L'AVATAR POUR LE RENDRE INTERACTIF ---
  Widget _buildPlayerAvatar(
    Map<String, dynamic> pData,
    String pId,
    bool isMe,
    List<String>? voters,
    String? captainId,
    List<String> lovers,
    bool amICurrentPlayerLoup,
    int nightNumber, {
    required String currentRoundState,
    required List<String> contaminatedPlayers,
    bool canSeeLovers = true,
    bool isSelectable = false,
    bool isSelected = false,
    VoidCallback? onTap,
  }) {
    bool isDead = pData['status'] == 'mort';
    String roleToShow =
        isDead ? "(${pData['revealedRole'] ?? pData['role']})" : "";
    bool isLover = lovers.contains(pId);
    bool isContaminated = contaminatedPlayers.contains(pId);
    bool isInfectedLoup = pData['infectionStatus'] == 'infecte';

    Color? avatarBgColor =
        isMe
            ? Colors.deepPurpleAccent
            : (isDead ? Colors.grey[800] : Colors.grey[600]);

    if (currentRoundState == 'nuit' &&
        (amICurrentPlayerLoup || isInfectedLoup) &&
        (GameData.roleCamps[pData['role']] == 'loups' || isInfectedLoup)) {
      avatarBgColor = Colors.red[900]!;
    }
    if (isContaminated && contaminatedPlayers.contains(widget.playerId)) {
      avatarBgColor = Colors.lightGreen[900]!;
    }

    Widget avatarContent = Column(
      mainAxisSize: MainAxisSize.min,
      children: [
        Stack(
          alignment: Alignment.center,
          children: [
            AnimatedContainer(
              duration: Duration(milliseconds: 200),
              padding: EdgeInsets.all(isSelectable ? 3 : 0),
              decoration: BoxDecoration(
                shape: BoxShape.circle,
                border: Border.all(
                  color:
                      isSelected
                          ? Colors.green
                          : (isSelectable
                              ? Colors.greenAccent
                              : Colors.transparent),
                  width: isSelectable ? 3 : 0,
                ),
                boxShadow:
                    isSelectable
                        ? [
                          BoxShadow(
                            color: Colors.greenAccent.withOpacity(0.6),
                            blurRadius: 10,
                            spreadRadius: 2,
                          ),
                        ]
                        : [],
              ),
              child: CircleAvatar(
                radius: 25, // Un peu plus petit pour la lisibilitÃ©
                backgroundColor: avatarBgColor,
                child: Padding(
                  padding: EdgeInsets.all(2),
                  child: FittedBox(
                    fit: BoxFit.scaleDown,
                    child: Text(
                      pData['name'] ?? '?',
                      style: TextStyle(
                        fontWeight: FontWeight.bold,
                        color: Colors.white,
                      ),
                    ),
                  ),
                ),
              ),
            ),
            if (pId == captainId)
              Positioned(
                top: -5,
                right: -5,
                child: Icon(Icons.king_bed, color: Colors.yellow, size: 18),
              ),
            if (isLover && canSeeLovers)
              Positioned(
                bottom: -5,
                right: -5,
                child: Icon(Icons.favorite, color: Colors.pink, size: 18),
              ),
            if (isInfectedLoup)
              Positioned(
                top: -5,
                left: -5,
                child: Icon(Icons.bug_report, color: Colors.purple, size: 18),
              ),
            if (isContaminated)
              Positioned(
                bottom: -5,
                left: -5,
                child: Icon(
                  Icons.sick,
                  color: Colors.lightGreenAccent,
                  size: 18,
                ),
              ),
          ],
        ),
        if (isDead)
          Text(
            roleToShow,
            style: TextStyle(
              color: Colors.grey[500],
              fontSize: 9,
              backgroundColor: Colors.black54,
            ),
          ),
        if (voters != null && voters.isNotEmpty)
          Container(
            color: Colors.black54,
            padding: EdgeInsets.symmetric(horizontal: 2),
            child: Column(
              children: [
                Text(
                  "${voters.length} Vote(s)",
                  style: TextStyle(
                    color: Colors.amber,
                    fontSize: 9,
                    fontWeight: FontWeight.bold,
                  ),
                ),
              ],
            ),
          ),
      ],
    );

    return GestureDetector(
      onTap: isSelectable ? onTap : null,
      child: avatarContent,
    );
  }

  Widget _buildSyncTimer(Timestamp? startTime, int durationInSeconds) {
    if (startTime == null) return const SizedBox.shrink();

    // TweenAnimationBuilder permet un chrono visuel super fluide sans Timer bloquant et setState manuel, ce qui allÃƒÂ¨ge grandement le thread (Point 4)
    final endTime = startTime.toDate().add(
      Duration(seconds: durationInSeconds),
    );
    final remaining = endTime.difference(DateTime.now());

    if (remaining.isNegative)
      return Text(
        "0 s",
        style: Theme.of(
          context,
        ).textTheme.headlineSmall?.copyWith(color: Colors.redAccent),
      );

    return TweenAnimationBuilder<Duration>(
      duration: remaining,
      tween: Tween(begin: remaining, end: Duration.zero),
      builder: (BuildContext context, Duration value, Widget? child) {
        final seconds = value.inSeconds;
        return Text(
          "Temps restant : $seconds s",
          style: Theme.of(context).textTheme.headlineSmall?.copyWith(
            color: seconds < 20 ? Colors.redAccent : Colors.amberAccent,
          ),
        );
      },
    );
  }

  Widget _buildChatInterface(
    Map<String, dynamic> gameData,
    String playerId, {
    bool isLiveStyle = false,
  }) {
    final Map<String, dynamic> playerData = Map<String, dynamic>.from(
      gameData['playerData'] ?? {},
    );
    final myData = playerData[playerId] ?? {};
    final myStatus = myData['status'] ?? 'vivant';
    final myRole = myData['role'] ?? 'Inconnu';
    final bool amILoup =
        GameData.roleCamps[myRole] == 'loups' ||
        myData['infectionStatus'] == 'infecte';
    final bool amIDead = myStatus == 'mort';
    final bool amILover = (gameData['lovers'] ?? []).contains(playerId);
    final bool amINecromancer = myRole == 'NÃ©cromancien';
    final List<String> lovers = List<String>.from(gameData['lovers'] ?? []);
    List<dynamic> currentChatMessages;
    bool canSendMessage = false;

    switch (_selectedChatType) {
      case 'wolf':
        currentChatMessages = List<dynamic>.from(
          gameData['wolfChatMessages'] ?? [],
        );
        canSendMessage = amILoup && !amIDead;
        break;
      case 'dead':
        currentChatMessages = List<dynamic>.from(
          gameData['deadChatMessages'] ?? [],
        );
        canSendMessage = amIDead || amINecromancer;
        break;
      case 'lover':
        List<String> lovers = List<String>.from(gameData['lovers'] ?? []);
        if (lovers.isNotEmpty && lovers.contains(playerId)) {
          lovers.sort();
          String chatKey = lovers.join('_');
          Map<String, dynamic> loverChat = Map<String, dynamic>.from(
            gameData['loverChatMessages']?[chatKey] ?? {},
          );
          currentChatMessages = List<dynamic>.from(loverChat['messages'] ?? []);
          canSendMessage = amILover && !amIDead;
        } else {
          currentChatMessages = [];
          canSendMessage = false;
        }
        break;
      default:
        currentChatMessages = List<dynamic>.from(
          gameData['chatMessages'] ?? [],
        );
        canSendMessage = !amIDead;
        break;
    }

    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        // Boutons de Filtre
        SingleChildScrollView(
          scrollDirection: Axis.horizontal,
          child: Row(
            children: [
              FilterChip(
                label: Text("Global", style: TextStyle(fontSize: 10)),
                selected: _selectedChatType == 'global',
                materialTapTargetSize: MaterialTapTargetSize.shrinkWrap,
                visualDensity: VisualDensity.compact,
                backgroundColor: isLiveStyle ? Colors.black45 : null,
                onSelected: (bool selected) {
                  if (selected) setState(() => _selectedChatType = 'global');
                },
              ),
              SizedBox(width: 4),

              if (GameData.roleCamps[myRole] == 'loups' ||
                  myData['infectionStatus'] == 'infecte' ||
                  (amIDead &&
                      (GameData.roleCamps[myRole] == 'loups' ||
                          myData['infectionStatus'] == 'infecte')))
                FilterChip(
                  label: Text("Loups", style: TextStyle(fontSize: 10)),
                  selected: _selectedChatType == 'wolf',
                  materialTapTargetSize: MaterialTapTargetSize.shrinkWrap,
                  visualDensity: VisualDensity.compact,
                  backgroundColor:
                      isLiveStyle ? Colors.red[900]?.withOpacity(0.5) : null,
                  onSelected: (bool selected) {
                    if (selected) setState(() => _selectedChatType = 'wolf');
                  },
                ),
              SizedBox(width: 4),

              if (amIDead || amINecromancer)
                FilterChip(
                  label: Text("Morts", style: TextStyle(fontSize: 10)),
                  selected: _selectedChatType == 'dead',
                  materialTapTargetSize: MaterialTapTargetSize.shrinkWrap,
                  visualDensity: VisualDensity.compact,
                  backgroundColor:
                      isLiveStyle ? Colors.grey[800]?.withOpacity(0.5) : null,
                  onSelected: (bool selected) {
                    if (selected) setState(() => _selectedChatType = 'dead');
                  },
                ),
              SizedBox(width: 4),

              if (amILover && lovers.length == 2)
                FilterChip(
                  label: Text("Amoureux", style: TextStyle(fontSize: 10)),
                  selected: _selectedChatType == 'lover',
                  materialTapTargetSize: MaterialTapTargetSize.shrinkWrap,
                  visualDensity: VisualDensity.compact,
                  backgroundColor:
                      isLiveStyle ? Colors.pink[800]?.withOpacity(0.5) : null,
                  onSelected: (bool selected) {
                    if (selected) setState(() => _selectedChatType = 'lover');
                  },
                ),
            ],
          ),
        ),

        // Liste des messages (Fond transparent en mode Live)
        Expanded(
          child: Container(
            color: isLiveStyle ? Colors.transparent : Colors.grey[900],
            child: ListView.builder(
              reverse: true,
              itemCount: currentChatMessages.length,
              itemBuilder: (context, index) {
                final messageData =
                    currentChatMessages[currentChatMessages.length - 1 - index];
                final senderId = messageData['senderId'];
                final senderName = messageData['senderName'];
                final message = messageData['message'];

                final isMine = senderId == playerId;

                if (isLiveStyle) {
                  // Style Live Stream (Texte brut avec ombres)
                  Color nameColor =
                      isMine ? Colors.amberAccent : Colors.lightBlueAccent;
                  if (_selectedChatType == 'wolf') nameColor = Colors.redAccent;
                  if (_selectedChatType == 'dead') nameColor = Colors.grey;

                  return Padding(
                    padding: const EdgeInsets.symmetric(vertical: 2.0),
                    child: RichText(
                      text: TextSpan(
                        style: TextStyle(
                          fontSize: 13,
                          shadows: [
                            Shadow(
                              color: Colors.black,
                              blurRadius: 4,
                              offset: Offset(1, 1),
                            ),
                          ],
                        ),
                        children: [
                          TextSpan(
                            text: "${isMine ? 'Vous' : senderName}: ",
                            style: TextStyle(
                              fontWeight: FontWeight.bold,
                              color: nameColor,
                            ),
                          ),
                          TextSpan(
                            text: message,
                            style: TextStyle(color: Colors.white),
                          ),
                        ],
                      ),
                    ),
                  );
                } else {
                  // Style Chat Classique (Bulles)
                  Color messageBgColor =
                      isMine ? Colors.deepPurple[700]! : Colors.grey[800]!;
                  if (_selectedChatType == 'wolf')
                    messageBgColor = Colors.red[900]!.withOpacity(0.5);
                  else if (_selectedChatType == 'dead')
                    messageBgColor = Colors.grey[700]!.withOpacity(0.5);

                  return Align(
                    alignment:
                        isMine ? Alignment.centerRight : Alignment.centerLeft,
                    child: Container(
                      margin: const EdgeInsets.symmetric(
                        vertical: 4.0,
                        horizontal: 8.0,
                      ),
                      padding: const EdgeInsets.all(10.0),
                      decoration: BoxDecoration(
                        color: messageBgColor,
                        borderRadius: BorderRadius.circular(12.0),
                      ),
                      child: Column(
                        crossAxisAlignment:
                            isMine
                                ? CrossAxisAlignment.end
                                : CrossAxisAlignment.start,
                        children: [
                          Text(
                            isMine ? "Vous" : senderName,
                            style: TextStyle(
                              fontWeight: FontWeight.bold,
                              color: Colors.white70,
                              fontSize: 10,
                            ),
                          ),
                          Text(
                            message,
                            style: TextStyle(color: Colors.white, fontSize: 13),
                          ),
                        ],
                      ),
                    ),
                  );
                }
              },
            ),
          ),
        ),

        // Barre d'entrÃ©e
        if (canSendMessage)
          Padding(
            padding: const EdgeInsets.only(top: 4.0),
            child: Row(
              children: [
                Expanded(
                  child: Container(
                    height: 35,
                    child: TextField(
                      controller: _chatController,
                      style: TextStyle(fontSize: 12),
                      decoration: InputDecoration(
                        hintText: "Message...",
                        hintStyle: TextStyle(
                          color: Colors.white54,
                          fontSize: 12,
                        ),
                        border: OutlineInputBorder(
                          borderRadius: BorderRadius.circular(20),
                          borderSide: BorderSide.none,
                        ),
                        filled: true,
                        fillColor:
                            isLiveStyle ? Colors.black54 : Colors.grey[800],
                        contentPadding: EdgeInsets.symmetric(
                          horizontal: 10,
                          vertical: 0,
                        ),
                      ),
                      onSubmitted: (text) {
                        if (text.trim().isNotEmpty) {
                          _firebaseService.sendChatMessage(
                            widget.gameCode,
                            playerId,
                            text.trim(),
                            _selectedChatType,
                          );
                          _chatController.clear();
                        }
                      },
                    ),
                  ),
                ),
                SizedBox(width: 4),
                IconButton(
                  icon: Icon(Icons.send, color: Colors.amberAccent, size: 20),
                  padding: EdgeInsets.zero,
                  constraints: BoxConstraints(),
                  onPressed: () {
                    if (_chatController.text.trim().isNotEmpty) {
                      _firebaseService.sendChatMessage(
                        widget.gameCode,
                        playerId,
                        _chatController.text.trim(),
                        _selectedChatType,
                      );
                      _chatController.clear();
                    }
                  },
                ),
              ],
            ),
          ),
      ],
    );
  }

  Widget _buildPetitsChevauxUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final players = Map<String, dynamic>.from(gameData['players']);
    final playerOrder = List<String>.from(gameData['petitsChevauxPlayerOrder']);
    final positions = Map<String, dynamic>.from(
      gameData['petitsChevauxPositions'],
    );
    final int currentIndex = gameData['petitsChevauxCurrentIndex'];
    final String currentPlayerId = playerOrder[currentIndex];
    final bool isMyTurn = currentPlayerId == playerId;
    final int dice = gameData['petitsChevauxDice'] ?? 0;
    final bool hasRolled = gameData['petitsChevauxHasRolled'] ?? false;

    final List<Color> playerColors = [
      Colors.redAccent,
      Colors.blueAccent,
      Colors.greenAccent,
      Colors.amber,
    ];

    // VÃƒÂ©rification de la fin de partie
    if (gameData['gameState'] == 'gameOver') {
      return Center(
        child: Card(
          child: Padding(
            padding: EdgeInsets.all(24),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                Text(
                  "Partie TerminÃƒÂ©e !",
                  style: Theme.of(context).textTheme.headlineMedium,
                ),
                Text(
                  "${players[gameData['gameWinner']]['name']} a gagnÃƒÂ© !",
                  style: TextStyle(color: Colors.amber, fontSize: 20),
                ),
                SizedBox(height: 20),
                ElevatedButton(
                  onPressed:
                      () => Navigator.of(
                        context,
                      ).popUntil((route) => route.isFirst),
                  child: Text("Retour"),
                ),
              ],
            ),
          ),
        ),
      );
    }

    return Column(
      children: [
        // --- INDICATEUR DE TOUR ---
        Container(
          padding: EdgeInsets.all(12),
          color: isMyTurn ? Colors.green.withOpacity(0.2) : Colors.transparent,
          child: Text(
            isMyTurn
                ? "C'est ÃƒÂ  toi de lancer le dÃƒÂ© !"
                : "Au tour de ${players[currentPlayerId]['name']}...",
            style: TextStyle(
              fontSize: 18,
              fontWeight: FontWeight.bold,
              color: isMyTurn ? Colors.greenAccent : Colors.white70,
            ),
          ),
        ),

        // --- PLATEAU CIRCULAIRE ---
        Expanded(
          flex: 3,
          child: LayoutBuilder(
            builder: (context, constraints) {
              double size =
                  min(constraints.maxWidth, constraints.maxHeight) * 0.95;
              return Center(
                child: SizedBox(
                  width: size,
                  height: size,
                  child: Stack(
                    alignment: Alignment.center,
                    children: [
                      // Dessin du plateau
                      CustomPaint(
                        size: Size(size, size),
                        painter: _LudoBoardPainter(playerColors),
                      ),
                      // Pions
                      ..._buildLudoPawns(
                        size,
                        positions,
                        playerOrder,
                        playerColors,
                        playerId,
                        isMyTurn,
                        dice,
                        hasRolled,
                        widget.gameCode,
                        _firebaseService,
                        gameData['petitsChevauxTeamMode'] ?? false,
                      ),
                    ],
                  ),
                ),
              );
            },
          ),
        ),

        // --- CONTROLES (DÃƒâ€° ET ACTIONS) ---
        Expanded(
          flex: 1,
          child: Container(
            padding: EdgeInsets.all(16),
            child: Row(
              mainAxisAlignment: MainAxisAlignment.spaceEvenly,
              children: [
                // DÃƒÂ©
                Container(
                  width: 80,
                  height: 80,
                  decoration: BoxDecoration(
                    color: Colors.white,
                    borderRadius: BorderRadius.circular(12),
                    boxShadow: [
                      BoxShadow(
                        color: Colors.black26,
                        blurRadius: 8,
                        offset: Offset(0, 4),
                      ),
                    ],
                  ),
                  child: Center(
                    child: Text(
                      dice > 0 ? "$dice" : "?",
                      style: TextStyle(
                        fontSize: 40,
                        fontWeight: FontWeight.bold,
                        color: Colors.deepPurple,
                      ),
                    ),
                  ),
                ),
                // Boutons
                Column(
                  mainAxisAlignment: MainAxisAlignment.center,
                  children: [
                    if (isMyTurn && !hasRolled)
                      ElevatedButton.icon(
                        icon: Icon(Icons.casino),
                        label: Text("Lancer"),
                        onPressed:
                            () => _firebaseService.rollDicePetitsChevaux(
                              widget.gameCode,
                              playerId,
                            ),
                        style: ElevatedButton.styleFrom(
                          backgroundColor: Colors.deepPurple,
                        ),
                      )
                    else if (isMyTurn && hasRolled)
                      ElevatedButton.icon(
                        icon: Icon(Icons.skip_next),
                        label: Text("Passer"),
                        onPressed:
                            () => _firebaseService.passTurnPetitsChevaux(
                              widget.gameCode,
                              playerId,
                            ),
                        style: ElevatedButton.styleFrom(
                          backgroundColor: Colors.grey[700],
                        ),
                      )
                    else
                      Text(
                        "En attente...",
                        style: TextStyle(color: Colors.white54),
                      ),
                  ],
                ),
              ],
            ),
          ),
        ),
      ],
    );
  }

  Widget _buildDominoesUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    // â”€â”€ Extraction des donnÃ©es â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    final players = Map<String, dynamic>.from(gameData['players'] ?? {});
    final playerOrder = List<String>.from(
      gameData['dominoesPlayerOrder'] ?? [],
    );
    final int currentIndex = gameData['dominoesCurrentPlayerIndex'] ?? 0;
    final currentPlayerId =
        playerOrder.isNotEmpty ? playerOrder[currentIndex] : '';
    final bool isMyTurn = currentPlayerId == playerId;

    final hands = Map<String, dynamic>.from(
      gameData['dominoesPlayerHands'] ?? {},
    );
    final myHand = List<String>.from(hands[playerId] ?? []);
    final openEnds = List<int>.from(gameData['dominoesOpenEnds'] ?? []);
    final boardChain = List<dynamic>.from(gameData['dominoesBoardChain'] ?? []);
    final boneyard = List<String>.from(gameData['dominoesBoneyard'] ?? []);
    final scores = Map<String, int>.from(gameData['dominoesScores'] ?? {});
    final bool roundOver = gameData['dominoesRoundOver'] ?? false;
    final String mode = gameData['dominoesMode'] ?? 'pioche';

    // â”€â”€ Helpers â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    bool canPlayTile(String tile) {
      if (openEnds.isEmpty) return true;
      final p = tile.split('-');
      final a = int.parse(p[0]);
      final b = int.parse(p[1]);
      return openEnds.contains(a) || openEnds.contains(b);
    }

    bool hasPlayableTile() => myHand.any(canPlayTile);

    // Calcule l'extrÃ©mitÃ© de correspondance, retourne null si ambigu
    int? getMatchEnd(String tile) {
      if (boardChain.isEmpty) return -1; // premier domino
      final p = tile.split('-');
      final a = int.parse(p[0]);
      final b = int.parse(p[1]);
      final matchA = openEnds.contains(a);
      final matchB = openEnds.contains(b);
      if (matchA && matchB && a != b) return null; // ambigu
      if (matchA) return a;
      if (matchB) return b;
      return -99; // invalide
    }

    void onTileTap(String tile) {
      if (!isMyTurn || roundOver) return;
      if (!canPlayTile(tile)) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text("Impossible de jouer ce domino ici.")),
        );
        return;
      }

      final matchEnd = getMatchEnd(tile);

      if (matchEnd == null) {
        // Ambigu : afficher un dialogue pour choisir l'extrÃ©mitÃ©
        showDialog(
          context: context,
          builder: (_) {
            final p = tile.split('-');
            final a = int.parse(p[0]);
            final b = int.parse(p[1]);
            final options =
                openEnds.where((e) => e == a || e == b).toSet().toList();
            return AlertDialog(
              backgroundColor: const Color(0xFF1e3828),
              shape: RoundedRectangleBorder(
                borderRadius: BorderRadius.circular(16),
              ),
              title: const Text(
                "Choisir l'extrÃ©mitÃ©",
                style: TextStyle(color: Colors.white),
              ),
              content: Text(
                "Sur quelle extrÃ©mitÃ© poser le $tile ?",
                style: const TextStyle(color: Colors.white70),
              ),
              actions:
                  options.map((end) {
                    return TextButton(
                      onPressed: () {
                        Navigator.pop(context);
                        _firebaseService
                            .playDominoesTile(
                              widget.gameCode,
                              playerId,
                              tile,
                              end,
                            )
                            .catchError((e) {
                              if (!mounted) return;
                              ScaffoldMessenger.of(context).showSnackBar(
                                SnackBar(content: Text(e.toString())),
                              );
                            });
                      },
                      child: Text(
                        "Sur le $end",
                        style: const TextStyle(color: Color(0xFF34d399)),
                      ),
                    );
                  }).toList(),
            );
          },
        );
        return;
      }

      if (matchEnd == -99) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text("Aucune extrÃ©mitÃ© compatible.")),
        );
        return;
      }

      _firebaseService
          .playDominoesTile(widget.gameCode, playerId, tile, matchEnd!)
          .catchError((e) {
            if (!mounted) return;
            ScaffoldMessenger.of(
              context,
            ).showSnackBar(SnackBar(content: Text(e.toString())));
          });
    }

    // â”€â”€ Build â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    return Column(
      children: [
        // â”€â”€ Barre de scores â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
        Container(
          padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 8),
          color: Colors.black.withOpacity(0.35),
          child: Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            children: [
              const Text(
                "Dominos",
                style: TextStyle(
                  color: Colors.white,
                  fontWeight: FontWeight.w500,
                  fontSize: 15,
                ),
              ),
              Row(
                children:
                    playerOrder.map((pId) {
                      final isActive = pId == currentPlayerId;
                      return Container(
                        margin: const EdgeInsets.only(left: 8),
                        padding: const EdgeInsets.symmetric(
                          horizontal: 12,
                          vertical: 4,
                        ),
                        decoration: BoxDecoration(
                          color:
                              isActive
                                  ? Colors.green.withOpacity(0.2)
                                  : Colors.white.withOpacity(0.08),
                          borderRadius: BorderRadius.circular(20),
                          border: Border.all(
                            color:
                                isActive
                                    ? Colors.greenAccent.withOpacity(0.5)
                                    : Colors.white.withOpacity(0.12),
                          ),
                        ),
                        child: Row(
                          mainAxisSize: MainAxisSize.min,
                          children: [
                            Container(
                              width: 6,
                              height: 6,
                              margin: const EdgeInsets.only(right: 5),
                              decoration: BoxDecoration(
                                shape: BoxShape.circle,
                                color:
                                    isActive
                                        ? Colors.greenAccent
                                        : Colors.white38,
                              ),
                            ),
                            Text(
                              players[pId]?['name']
                                      ?.toString()
