    // --- Ãƒâ€°CRAN FIN DE MANCHE ---
    if (roundState == 'round_over') {
      return Center(
        child: Card(
          child: Padding(
            padding: const EdgeInsets.all(24.0),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                Text(
                  "Manche TerminÃƒÂ©e !",
                  style: Theme.of(context).textTheme.headlineMedium,
                ),
                SizedBox(height: 20),
                Text(
                  "Ãƒâ€°quipe A: ${teamScores['teamA'] ?? 0} pts",
