              Text(
                isGameOver ? "Partie TerminÃƒÂ©e !" : "Fin de la Manche",
                style: Theme.of(context).textTheme.headlineMedium,
              ),
              SizedBox(height: 10),
              if (isGameOver)
                Text(
                  "Vainqueur : ${players[gameData['gameWinner']]?['name']}",
                  style: TextStyle(color: Colors.amber, fontSize: 20),
                ),
              SizedBox(height: 20),
              Text("Scores :", style: Theme.of(context).textTheme.titleLarge),
              ...sortedScores.map(
                (e) => Text("${players[e.key]?['name']}: ${e.value} pts"),
              ),
              SizedBox(height: 20),
              if (isHost && !isGameOver)
                ElevatedButton(
                  onPressed: () => _firebaseService.startGame(widget.gameCode),
                  child: Text("Manche Suivante"),
                )
              else if (!isHost && !isGameOver)
                Text("En attente de l'hÃƒÂ´te..."),
              if (isGameOver)
                ElevatedButton(
                  onPressed:
                      () => Navigator.of(
                        context,
                      ).popUntil((route) => route.isFirst),
                  child: Text("Retour ÃƒÂ  l'accueil"),
                ),
            ],
          ),
        ),
      ),
    );
  }

  // NOUVELLE UI BLOKUS COMPLÃˆTE
  // NOUVELLE UI BLOKUS COMPLÈTE
  Widget _buildBlokusUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final board = Map<String, String>.from(gameData['blokusBoard'] ?? {});
    final myColor = gameData['blokusPlayerColors']?[playerId] ?? 'blue';
    final myHand = List<int>.from(
      gameData['blokusPlayerHands']?[playerId] ?? [],
    );
    final playerOrder = List<String>.from(gameData['blokusPlayerOrder'] ?? []);
    final currentPlayerId =
        playerOrder.isNotEmpty
            ? playerOrder[gameData['blokusCurrentPlayerIndex'] ?? 0]
            : '';
    final bool isMyTurn = currentPlayerId == playerId;
    final players = gameData['players'] as Map<String, dynamic>;
    final passedPlayers = List<String>.from(
      gameData['blokusPassedPlayers'] ?? [],
    );
    final isFirstPiece =
        !(gameData['blokusFirstPiecePlaced']?[playerId] ?? false);

    // --- CORRECTION 1 : NETTOYAGE SI FIN DU CHRONO OU TOUR PASSÉ ---
    if (!isMyTurn && _selectedBlokusPieceId != null) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted) {
          setState(() {
            _selectedBlokusPieceId = null;
            _blokusStartRow = null;
            _blokusStartCol = null;
            _blokusCanPlace = false;
          });
        }
      });
    }

    if (gameData['gameState'] == 'gameOver') {
      final scores = Map<String, int>.from(gameData['blokusScores'] ?? {});
      final sortedScores =
          scores.entries.toList()..sort((a, b) => b.value.compareTo(a.value));
      return Center(
        child: Card(
          child: Padding(
            padding: const EdgeInsets.all(24),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                Icon(Icons.emoji_events, size: 60, color: Colors.amber),
                SizedBox(height: 20),
                Text(
                  "Partie Terminée !",
                  style: Theme.of(context).textTheme.headlineMedium,
                ),
                SizedBox(height: 20),
                ...sortedScores.map(
                  (e) => Text(
                    "${players[e.key]?['name'] ?? 'Joueur'}: ${e.value} pts",
                    style: TextStyle(fontSize: 18),
                  ),
                ),
                SizedBox(height: 20),
                ElevatedButton(
                  onPressed:
                      () => Navigator.of(
                        context,
                      ).popUntil((route) => route.isFirst),
                  child: Text("Retour"),
                ),
              ],
            ),
          ),
        ),
      );
    }

    Color getColor(String c) {
      switch (c) {
        case 'blue':
          return Colors.blue;
        case 'red':
          return Colors.red;
        case 'green':
          return Colors.green;
        case 'yellow':
          return Colors.yellow;
        default:
          return Colors.grey;
      }
    }

    final double gridSize = 20;

    return LayoutBuilder(
      builder: (context, constraints) {
        final double boardPixelSize = constraints.maxWidth - 16;
        final double cellSize = boardPixelSize / gridSize;

        // --- CORRECTION 2 : FONCTION UNIFIÉE DE DÉPLACEMENT ---
        void _updatePiecePosition(Offset localOffset) {
          if (_selectedBlokusPieceId != null) {
            final col = (localOffset.dx / cellSize).floor();
            // On positionne TOUJOURS la pièce 3 cases au-dessus du doigt
            final row = ((localOffset.dy / cellSize) - 3).floor();
            if (_blokusStartRow != row || _blokusStartCol != col) {
              setState(() {
                _blokusStartRow = row;
                _blokusStartCol = col;
                _checkBlokusPlacement(board, myColor, isFirstPiece);
              });
            }
          }
        }

        return DragTarget<int>(
          onWillAcceptWithDetails: (details) => isMyTurn,
          onAcceptWithDetails: (details) {
            setState(() {
              _selectedBlokusPieceId = details.data;
              _checkBlokusPlacement(board, myColor, isFirstPiece);
            });
          },
          onMove: (details) {
            final RenderBox? renderBox =
                _canvasKey.currentContext?.findRenderObject() as RenderBox?;
            if (renderBox != null) {
              final localOffset = renderBox.globalToLocal(details.offset);
              _updatePiecePosition(localOffset);
            }
          },
          builder: (context, candidateData, rejectedData) {
            return Column(
              children: [
                // --- EN-TÊTE ---
                Container(
                  padding: EdgeInsets.symmetric(horizontal: 12, vertical: 8),
                  decoration: BoxDecoration(
                    color:
                        isMyTurn
                            ? getColor(myColor).withOpacity(0.15)
                            : Colors.transparent,
                    borderRadius: BorderRadius.circular(12),
                  ),
                  child: Row(
                    mainAxisAlignment: MainAxisAlignment.spaceBetween,
                    children: [
                      Expanded(
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          mainAxisSize: MainAxisSize.min,
                          children: [
                            Text(
                              isMyTurn
                                  ? "C'est votre tour !"
                                  : "Au tour de ${players[currentPlayerId]?['name'] ?? '...'}",
                              style: TextStyle(
                                color:
                                    isMyTurn ? getColor(myColor) : Colors.white,
                                fontWeight: FontWeight.bold,
                                fontSize: 15,
                              ),
                              overflow: TextOverflow.ellipsis,
                            ),
                            if (isFirstPiece && isMyTurn)
                              Text(
                                "Placez dans votre coin !",
                                style: TextStyle(
                                  color: Colors.amberAccent,
                                  fontSize: 11,
                                ),
                              ),
                          ],
                        ),
                      ),

                      if (isMyTurn && _selectedBlokusPieceId != null) ...[
                        IconButton(
                          icon: Icon(
                            Icons.rotate_right,
                            color: Colors.deepPurpleAccent,
                          ),
                          tooltip: "Tourner",
                          constraints: BoxConstraints(),
                          padding: EdgeInsets.symmetric(horizontal: 8),
                          onPressed:
                              () => setState(() {
                                _blokusRotation = (_blokusRotation + 1) % 4;
                                _checkBlokusPlacement(
                                  board,
                                  myColor,
                                  isFirstPiece,
                                );
                              }),
                        ),
                        IconButton(
                          icon: Icon(Icons.flip, color: Colors.tealAccent),
                          tooltip: "Retourner",
                          constraints: BoxConstraints(),
                          padding: EdgeInsets.symmetric(horizontal: 8),
                          onPressed:
                              () => setState(() {
                                _blokusFlipped = !_blokusFlipped;
                                _checkBlokusPlacement(
                                  board,
                                  myColor,
                                  isFirstPiece,
                                );
                              }),
                        ),
                        IconButton(
                          icon: Icon(
                            Icons.check_circle,
                            color:
                                _blokusCanPlace
                                    ? Colors.greenAccent
                                    : Colors.grey,
                          ),
                          tooltip: "Valider le placement",
                          constraints: BoxConstraints(),
                          padding: EdgeInsets.symmetric(horizontal: 8),
                          onPressed:
                              _blokusCanPlace &&
                                      _blokusStartRow != null &&
                                      _blokusStartCol != null
                                  ? () async {
                                    try {
                                      await _firebaseService.placeBlokusPiece(
                                        widget.gameCode,
                                        playerId,
                                        _selectedBlokusPieceId!,
                                        _blokusStartRow!,
                                        _blokusStartCol!,
                                        _blokusRotation,
                                        flipped: _blokusFlipped,
                                      );
                                      setState(() {
                                        _selectedBlokusPieceId = null;
                                        _blokusRotation = 0;
                                        _blokusFlipped = false;
                                        _blokusStartRow = null;
                                        _blokusStartCol = null;
                                        _blokusCanPlace = false;
                                      });
                                    } catch (e) {
                                      ScaffoldMessenger.of(
                                        context,
                                      ).showSnackBar(
                                        SnackBar(
                                          content: Text(
                                            e.toString().replaceAll(
                                              'Exception: ',
                                              '',
                                            ),
                                          ),
                                        ),
                                      );
                                    }
                                  }
                                  : null,
                        ),
                        IconButton(
                          icon: Icon(Icons.cancel, color: Colors.redAccent),
                          tooltip: "Annuler",
                          constraints: BoxConstraints(),
                          padding: EdgeInsets.symmetric(horizontal: 8),
                          onPressed:
                              () => setState(() {
                                _selectedBlokusPieceId = null;
                                _blokusStartRow = null;
                                _blokusStartCol = null;
                                _blokusCanPlace = false;
                              }),
                        ),
                      ],

                      if (isMyTurn && _selectedBlokusPieceId == null)
                        ElevatedButton(
                          style: ElevatedButton.styleFrom(
                            backgroundColor: Colors.red[900],
                            padding: EdgeInsets.symmetric(
                              horizontal: 12,
                              vertical: 8,
                            ),
                            minimumSize: Size(0, 36),
                          ),
                          onPressed: () {
                            _firebaseService.passBlokusTurn(
                              widget.gameCode,
                              playerId,
                            );
                            // --- CORRECTION 3 : Retirer la pièce sélectionnée en passant ---
                            setState(() {
                              _selectedBlokusPieceId = null;
                              _blokusStartRow = null;
                              _blokusStartCol = null;
                              _blokusCanPlace = false;
                            });
                          },
                          child: Text("Passer", style: TextStyle(fontSize: 12)),
                        ),
                    ],
                  ),
                ),

                // --- PLATEAU DE JEU ---
                Expanded(
                  child: Center(
                    child: Container(
                      width: boardPixelSize,
                      height: boardPixelSize,
                      decoration: BoxDecoration(
                        border: Border.all(color: Colors.white24, width: 2),
                        borderRadius: BorderRadius.circular(8),
                      ),
                      child: GestureDetector(
                        onPanStart:
                            isMyTurn
                                ? (details) =>
                                    _updatePiecePosition(details.localPosition)
                                : null,
                        onPanUpdate:
                            isMyTurn
                                ? (details) =>
                                    _updatePiecePosition(details.localPosition)
                                : null,
                        onTapDown:
                            isMyTurn
                                ? (details) =>
                                    _updatePiecePosition(details.localPosition)
                                : null,
                        child: CustomPaint(
                          key: _canvasKey,
                          size: Size(boardPixelSize, boardPixelSize),
                          painter: _BlokusBoardPainter(
                            board: board,
                            gridSize: gridSize,
                            cellSize: cellSize,
                            previewPiece:
                                _selectedBlokusPieceId != null &&
                                        _blokusStartRow != null &&
                                        _blokusStartCol != null
                                    ? GameData.getRotatedPiece(
                                      _selectedBlokusPieceId!,
                                      _blokusRotation,
                                      flipped: _blokusFlipped,
                                    )
                                    : null,
                            previewRow: _blokusStartRow,
                            previewCol: _blokusStartCol,
                            previewColor: getColor(myColor),
                            canPlace: _blokusCanPlace,
                          ),
                        ),
                      ),
                    ),
                  ),
                ),

                // --- RACK DE PIÈCES ---
                Container(
                  height: 140,
                  padding: EdgeInsets.symmetric(vertical: 8, horizontal: 12),
                  decoration: BoxDecoration(
                    gradient: LinearGradient(
                      colors: [
                        Colors.black.withOpacity(0.6),
                        Colors.grey[900]!.withOpacity(0.85),
                      ],
                      begin: Alignment.topCenter,
                      end: Alignment.bottomCenter,
                    ),
                    borderRadius: BorderRadius.vertical(
                      top: Radius.circular(20),
                    ),
                    border: Border.all(color: Colors.white10, width: 1.5),
                    boxShadow: [
                      BoxShadow(
                        color: Colors.black54,
                        blurRadius: 10,
                        offset: Offset(0, -4),
                      ),
                    ],
                  ),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.stretch,
                    children: [
                      Padding(
                        padding: const EdgeInsets.only(bottom: 6.0),
                        child: Row(
                          mainAxisAlignment: MainAxisAlignment.spaceBetween,
                          children: [
                            Text(
                              "Vos pièces",
                              style: TextStyle(
                                color: Colors.white70,
                                fontSize: 12,
                                fontWeight: FontWeight.w600,
                                letterSpacing: 0.5,
                              ),
                            ),
                          ],
                        ),
                      ),
                      Expanded(
                        child: ListView.builder(
                          scrollDirection: Axis.horizontal,
                          itemCount: myHand.length,
                          itemBuilder: (context, index) {
                            int pieceId = myHand[index];
                            bool isSelected = _selectedBlokusPieceId == pieceId;

                            Widget pieceWidget = Container(
                              width: 85,
                              height: 85,
                              margin: EdgeInsets.symmetric(
                                horizontal: 4,
                                vertical: 2,
                              ),
                              decoration: BoxDecoration(
                                color:
                                    isSelected
                                        ? getColor(myColor).withOpacity(0.25)
                                        : Colors.white.withOpacity(0.04),
                                borderRadius: BorderRadius.circular(12),
                                border: Border.all(
                                  color:
                                      isSelected
                                          ? getColor(myColor)
                                          : Colors.white12,
                                  width: isSelected ? 2.5 : 1.0,
                                ),
                                boxShadow:
                                    isSelected
                                        ? [
                                          BoxShadow(
                                            color: getColor(
                                              myColor,
                                            ).withOpacity(0.3),
                                            blurRadius: 8,
                                            spreadRadius: 1,
                                          ),
                                        ]
                                        : [],
                              ),
                              child: CustomPaint(
                                painter: _BlokusPiecePainter(
                                  pieceId,
                                  isSelected ? _blokusRotation : 0,
                                  getColor(myColor),
                                  flipped: isSelected ? _blokusFlipped : false,
                                ),
                              ),
                            );

                            return GestureDetector(
                              onTap:
                                  isMyTurn
                                      ? () {
                                        setState(() {
                                          if (isSelected) {
                                            _selectedBlokusPieceId = null;
                                          } else {
                                            _selectedBlokusPieceId = pieceId;
                                            _blokusRotation = 0;
                                            _blokusFlipped = false;
                                            _checkBlokusPlacement(
                                              board,
                                              myColor,
                                              isFirstPiece,
                                            );
                                          }
                                        });
                                      }
                                      : null,
                              child: Draggable<int>(
                                data: pieceId,
                                maxSimultaneousDrags: isMyTurn ? 1 : 0,
                                affinity: Axis.vertical,
                                onDragStarted: () {
                                  setState(() {
                                    _selectedBlokusPieceId = pieceId;
                                    _blokusRotation = 0;
                                    _blokusFlipped = false;
                                  });
                                },
                                feedback: const SizedBox.shrink(),
                                childWhenDragging: Opacity(
                                  opacity: 0.25,
                                  child: pieceWidget,
                                ),
                                child: pieceWidget,
                              ),
                            );
                          },
                        ),
                      ),
                    ],
                  ),
                ),
              ],
            );
          },
        );
      },
    );
  }

  // Fonction de vÃ©rification du placement
  void _checkBlokusPlacement(
    Map<String, String> board,
    String myColor,
    bool isFirstPiece,
  ) {
    if (_selectedBlokusPieceId == null ||
        _blokusStartRow == null ||
        _blokusStartCol == null) {
      setState(() => _blokusCanPlace = false);
      return;
    }
    final rotatedPiece = GameData.getRotatedPiece(
      _selectedBlokusPieceId!,
      _blokusRotation,
      flipped: _blokusFlipped,
    );
    final absoluteCoords =
        rotatedPiece
            .map((p) => [p[0] + _blokusStartRow!, p[1] + _blokusStartCol!])
            .toList();

    for (var c in absoluteCoords) {
      if (c[0] < 0 || c[0] >= 20 || c[1] < 0 || c[1] >= 20) {
        setState(() => _blokusCanPlace = false);
        return;
      }
      if (board.containsKey("${c[0]}_${c[1]}")) {
        setState(() => _blokusCanPlace = false);
        return;
      }
    }
    for (var c in absoluteCoords) {
      List<List<int>> neighbors = [
        [c[0] - 1, c[1]],
        [c[0] + 1, c[1]],
        [c[0], c[1] - 1],
        [c[0], c[1] + 1],
      ];
      for (var n in neighbors) {
        if (board["${n[0]}_${n[1]}"] == myColor) {
          setState(() => _blokusCanPlace = false);
          return;
        }
      }
    }
    bool touchesCorner = false;
    for (var c in absoluteCoords) {
      List<List<int>> diags = [
        [c[0] - 1, c[1] - 1],
        [c[0] - 1, c[1] + 1],
        [c[0] + 1, c[1] - 1],
        [c[0] + 1, c[1] + 1],
      ];
      for (var d in diags) {
        if (board["${d[0]}_${d[1]}"] == myColor) {
          touchesCorner = true;
          break;
        }
      }
      if (touchesCorner) break;
    }

    if (isFirstPiece) {
      String cornerTarget =
          myColor == 'blue'
              ? "0_0"
              : myColor == 'red'
              ? "19_19"
              : myColor == 'green'
              ? "0_19"
              : "19_0";
      bool coversCorner = absoluteCoords.any(
        (c) => "${c[0]}_${c[1]}" == cornerTarget,
      );
      setState(() => _blokusCanPlace = coversCorner);
    } else {
      setState(() => _blokusCanPlace = touchesCorner);
    }
  }
}

// PAINTER POUR LE PLATEAU BLOKUS
class _BlokusBoardPainter extends CustomPainter {
  final Map<String, String> board;
  final double gridSize;
  final double cellSize;
  final List<List<int>>? previewPiece;
  final int? previewRow;
  final int? previewCol;
  final Color previewColor;
  final bool canPlace;

  _BlokusBoardPainter({
    required this.board,
    required this.gridSize,
    required this.cellSize,
    this.previewPiece,
    this.previewRow,
    this.previewCol,
    required this.previewColor,
    required this.canPlace,
  });

  @override
  void paint(Canvas canvas, Size size) {
    // Fond de la grille
    final bgPaint = Paint()..color = Colors.grey[900]!;
    canvas.drawRect(Rect.fromLTWH(0, 0, size.width, size.height), bgPaint);

    // Dessiner les cellules
    for (int r = 0; r < gridSize; r++) {
      for (int c = 0; c < gridSize; c++) {
        final rect = Rect.fromLTWH(
          c * cellSize,
          r * cellSize,
          cellSize,
          cellSize,
        );
        final key = "${r}_${c}";
        final cellColor = board[key];

        if (cellColor != null) {
          Color color;
          switch (cellColor) {
            case 'blue':
              color = Colors.blue;
              break;
            case 'red':
              color = Colors.red;
              break;
            case 'green':
              color = Colors.green;
              break;
            case 'yellow':
              color = Colors.yellow;
              break;
            default:
              color = Colors.grey;
          }
          final paint = Paint()..color = color;
          canvas.drawRect(rect.inflate(-1), paint);
        } else {
          // Grille vide
          final paint = Paint()..color = Colors.grey[800]!;
          canvas.drawRect(rect.inflate(-1), paint);
        }

        // Bordure
        final borderPaint =
            Paint()
              ..color = Colors.white10
              ..style = PaintingStyle.stroke;
        canvas.drawRect(rect, borderPaint);
      }
    }

    // --- AJOUT : Indications visuelles des coins de dÃ©part ---
    void drawStartCorner(int r, int c, Color color) {
      if (board["${r}_${c}"] == null) {
        final rect = Rect.fromLTWH(
          c * cellSize,
          r * cellSize,
          cellSize,
          cellSize,
        );
        canvas.drawRect(
          rect.inflate(-2),
          Paint()
            ..color = color.withOpacity(0.3)
            ..style = PaintingStyle.fill,
        );
        canvas.drawCircle(
          rect.center,
          cellSize * 0.2,
          Paint()..color = color.withOpacity(0.8),
        );
      }
    }

    // On dessine les 4 coins d'aide (Bleu, Rouge opposÃ©)
    drawStartCorner(0, 0, Colors.blue);
    drawStartCorner(19, 19, Colors.red);
    drawStartCorner(0, 19, Colors.green);
    drawStartCorner(19, 0, Colors.yellow);
    // ---------------------------------------------------------

    // Preview de la pièce
    if (previewPiece != null && previewRow != null && previewCol != null) {
      // --- CORRECTION 4 : La pièce garde TOUJOURS la couleur du joueur (avec opacité) ---
      final previewPaint =
          Paint()
            ..color = previewColor.withOpacity(
              0.6,
            ); // Toujours la bonne couleur

      for (var p in previewPiece!) {
        final row = p[0] + previewRow!;
        final col = p[1] + previewCol!;
        if (row >= 0 && row < gridSize && col >= 0 && col < gridSize) {
          final rect = Rect.fromLTWH(
            col * cellSize,
            row * cellSize,
            cellSize,
            cellSize,
          );
          canvas.drawRect(rect.inflate(-1), previewPaint);
        }
      }

      // --- CORRECTION 5 : Seule la BORDURE devient rouge si le placement est invalide ---
      final borderPaint =
          Paint()
            ..color = canPlace ? Colors.greenAccent : Colors.redAccent
            ..style = PaintingStyle.stroke
            ..strokeWidth = 2;

      for (var p in previewPiece!) {
        final row = p[0] + previewRow!;
        final col = p[1] + previewCol!;
        if (row >= 0 && row < gridSize && col >= 0 && col < gridSize) {
          final rect = Rect.fromLTWH(
            col * cellSize,
            row * cellSize,
            cellSize,
            cellSize,
          );
          canvas.drawRect(rect, borderPaint);
        }
      }
    }
  }

  @override
  bool shouldRepaint(covariant CustomPainter oldDelegate) => true;
}

// PAINTER POUR LES PIÃˆCES DANS LA MAIN
class _BlokusPiecePainter extends CustomPainter {
  final int pieceId;
  final int rotation;
  final Color color;
  final bool flipped; // NOUVEAU

  _BlokusPiecePainter(
    this.pieceId,
    this.rotation,
    this.color, {
    this.flipped = false,
  });

  @override
  void paint(Canvas canvas, Size size) {
    final piece = GameData.getRotatedPiece(pieceId, rotation, flipped: flipped);
    if (piece.isEmpty) return;

    int maxR = piece.map((p) => p[0]).reduce((a, b) => a > b ? a : b);
    int maxC = piece.map((p) => p[1]).reduce((a, b) => a > b ? a : b);

    double cellW = size.width / (maxC + 1);
    double cellH = size.height / (maxR + 1);
    double cellSize = cellW < cellH ? cellW : cellH;

    double offsetX = (size.width - (maxC + 1) * cellSize) / 2;
    double offsetY = (size.height - (maxR + 1) * cellSize) / 2;

    final paint = Paint()..color = color;
    final borderPaint =
        Paint()
          ..color = Colors.white
          ..style = PaintingStyle.stroke
          ..strokeWidth = 1;

    for (var p in piece) {
      final rect = Rect.fromLTWH(
        offsetX + p[1] * cellSize,
        offsetY + p[0] * cellSize,
        cellSize * 0.9,
        cellSize * 0.9,
      );
      canvas.drawRect(rect, paint);
      canvas.drawRect(rect, borderPaint);
    }
  }

  @override
  bool shouldRepaint(covariant CustomPainter oldDelegate) => true;
}

// Painter for straight-line-only Pictionary drawing mode
class _StraightLinePainter extends CustomPainter {
  final List<Offset> points; // flat list of [start1, end1, start2, end2, ...]
  final Offset? currentStart;
  final Offset? currentEnd;

  const _StraightLinePainter({
    required this.points,
    this.currentStart,
    this.currentEnd,
  });

  @override
  void paint(Canvas canvas, Size size) {
    final paint =
        Paint()
          ..color = Colors.black
          ..strokeWidth = 3.0
          ..strokeCap = StrokeCap.round;

    for (int i = 0; i + 1 < points.length; i += 2) {
      canvas.drawLine(points[i], points[i + 1], paint);
    }
    if (currentStart != null && currentEnd != null) {
      canvas.drawLine(
        currentStart!,
        currentEnd!,
        paint..color = Colors.black54,
      );
    }
  }

  @override
  bool shouldRepaint(_StraightLinePainter old) =>
      old.points != points ||
      old.currentStart != currentStart ||
      old.currentEnd != currentEnd;
}

class DrawingScreen extends StatefulWidget {
  final String prompt;
  final bool limitStrokes;
  final int maxStrokes;
  final SignatureController? initialController;
  final String? backgroundDrawingData;

  const DrawingScreen({
    Key? key,
    required this.prompt,
    this.limitStrokes = false,
    this.maxStrokes = 30,
    this.initialController,
    this.backgroundDrawingData,
  }) : super(key: key);

  @override
  _DrawingScreenState createState() => _DrawingScreenState();
}

class _DrawingScreenState extends State<DrawingScreen> {
  late SignatureController _controller;
  int _currentStrokeCount = 0;

  final GlobalKey _canvasKey = GlobalKey();

  static const double CANVAS_WIDTH = 800.0;
  static const double CANVAS_HEIGHT = 600.0;

  @override
  void initState() {
    super.initState();
    _controller =
        widget.initialController ??
        SignatureController(
          penStrokeWidth: 5,
          penColor: Colors.black,
          exportBackgroundColor: Colors.transparent,
        );
    _controller.addListener(_updateStrokeCount);
  }

  @override
  void dispose() {
    _controller.removeListener(_updateStrokeCount);
    if (widget.initialController == null) {
      _controller.dispose();
    }
    super.dispose();
  }

  void _updateStrokeCount() {
    if (mounted) {
      setState(() {
        _currentStrokeCount =
            _controller.points.where((p) => p == null).length +
            (_controller.points.isNotEmpty ? 1 : 0);
      });
    }
  }

  Future<Uint8List?> _captureCanvas() async {
    try {
      RenderRepaintBoundary boundary =
          _canvasKey.currentContext!.findRenderObject()
              as RenderRepaintBoundary;

      ui.Image image = await boundary.toImage(pixelRatio: 1.0);
      ByteData? byteData = await image.toByteData(
        format: ui.ImageByteFormat.png,
      );

      return byteData?.buffer.asUint8List();
    } catch (e) {
      print("Erreur lors de la capture: $e");
      return null;
    }
  }

  Future<String?> _exportMergedImage() async {
    final Uint8List? canvasBytes = await _captureCanvas();

    if (canvasBytes == null) return null;

    final img.Image? capturedImage = img.decodeImage(canvasBytes);
    if (capturedImage == null) return null;

    final img.Image finalImage = img.copyResize(
      capturedImage,
      width: CANVAS_WIDTH.round(),
      height: CANVAS_HEIGHT.round(),
      interpolation:
          img
              .Interpolation
              .nearest, // Pas d'interpolation pour garder la nettetÃƒÂ©
    );

    return base64Encode(img.encodePng(finalImage));
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: Text("Dessine !"),
        actions: [
          IconButton(
            icon: Icon(Icons.undo),
            onPressed: () => _controller.undo(),
          ),
          IconButton(
            icon: Icon(Icons.clear),
            onPressed: () => _controller.clear(),
          ),
        ],
        automaticallyImplyLeading: false,
      ),
      body: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          Padding(
            padding: const EdgeInsets.all(16.0),
            child: Text(
              widget.prompt,
              textAlign: TextAlign.center,
              style: Theme.of(context).textTheme.headlineSmall,
            ),
          ),
          Expanded(
            child: Center(
              child: Container(
                margin: EdgeInsets.all(16),
                width: CANVAS_WIDTH,
                height: CANVAS_HEIGHT,
                decoration: BoxDecoration(
                  color: Colors.white,
                  borderRadius: BorderRadius.circular(12),
                  border: Border.all(color: Colors.deepPurple, width: 2),
                ),
                child: ClipRRect(
                  borderRadius: BorderRadius.circular(11),

                  child: RepaintBoundary(
                    key: _canvasKey,
                    child: Stack(
                      children: [
                        Positioned.fill(child: Container(color: Colors.white)),

                        if (widget.backgroundDrawingData != null)
                          Positioned.fill(
                            child: Image.memory(
                              base64Decode(widget.backgroundDrawingData!),
                              fit: BoxFit.fill,
                            ),
                          ),

                        Positioned.fill(
                          child: Signature(
                            controller: _controller,
                            backgroundColor: Colors.transparent,
                          ),
                        ),
                      ],
                    ),
                  ),
                ),
              ),
            ),
          ),
          Padding(
            padding: const EdgeInsets.all(16.0),
            child: ElevatedButton(
              onPressed: () async {
                if (_controller.isEmpty &&
                    widget.backgroundDrawingData == null) {
                  ScaffoldMessenger.of(context).showSnackBar(
                    SnackBar(
                      content: Text("Vous devez dessiner quelque chose !"),
                    ),
                  );
                  return;
                }

                final String? mergedBase64 = await _exportMergedImage();

                if (mergedBase64 != null) {
                  Navigator.of(context).pop({
                    'drawing': mergedBase64,
                    'strokeCount': _currentStrokeCount,
                  });
                } else {
                  ScaffoldMessenger.of(context).showSnackBar(
                    SnackBar(
                      content: Text("Erreur lors de la sauvegarde du dessin."),
                    ),
                  );
                }
              },
              child: Text("J'ai fini !"),
            ),
          ),
        ],
      ),
    );
  }
}

class LocalPlayerSetupScreen extends StatefulWidget {
