class _LocalPlayerSetupScreenState extends State<LocalPlayerSetupScreen> {
  final _nameController = TextEditingController();
  final List<String> _players = [];

  void _addPlayer() {
    final name = _nameController.text.trim();
    if (name.isNotEmpty && !_players.contains(name)) {
      setState(() {
        _players.add(name);
        _nameController.clear();
      });
    } else if (name.isNotEmpty) {
      ScaffoldMessenger.of(
        context,
      ).showSnackBar(SnackBar(content: Text("Ce joueur existe dÃƒÂ©jÃƒÂ  !")));
    }
  }

  void _removePlayer(String name) {
    setState(() {
      _players.remove(name);
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text("Participants (Mode Local)")),
      body: Padding(
        padding: const EdgeInsets.all(16.0),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Text(
              "Ajoutez les joueurs",
              style: Theme.of(context).textTheme.headlineSmall,
            ),
            SizedBox(height: 16),
            Row(
              children: [
                Expanded(
                  child: TextField(
                    controller: _nameController,
                    decoration: InputDecoration(
                      labelText: "PrÃƒÂ©nom du joueur",
                    ),
                    onSubmitted: (_) => _addPlayer(),
                  ),
                ),
                SizedBox(width: 8),
                IconButton(
                  icon: Icon(
                    Icons.add_circle,
                    color: Colors.deepPurpleAccent,
                    size: 30,
                  ),
                  onPressed: _addPlayer,
                ),
              ],
            ),
            SizedBox(height: 16),
            Expanded(
              child:
                  _players.isEmpty
                      ? Center(
                        child: Text(
                          "Ajoutez au moins 2 joueurs pour commencer.",
                          style: TextStyle(color: Colors.white70),
                        ),
                      )
                      : ListView.builder(
                        itemCount: _players.length,
                        itemBuilder: (context, index) {
                          final player = _players[index];
                          return Card(
                            child: ListTile(
                              leading: CircleAvatar(
                                child: Text((index + 1).toString()),
                              ),
                              title: Text(player),
                              trailing: IconButton(
                                icon: Icon(
                                  Icons.remove_circle_outline,
                                  color: Colors.redAccent,
                                ),
                                onPressed: () => _removePlayer(player),
                              ),
                            ),
                          );
                        },
                      ),
            ),
            SizedBox(height: 16),
            ElevatedButton(
              onPressed:
                  _players.length < 2
                      ? null
                      : () {
                        if (widget.targetGame != null) {
                          // Lancer directement le bon jeu !
                          _launchLocalGame(widget.targetGame!);
                        } else {
                          // S'il n'y a pas de target, on ouvre le menu
                          Navigator.push(
                            context,
                            MaterialPageRoute(
                              builder:
                                  (_) => OfflineMenuScreen(players: _players),
                            ),
                          );
                        }
                      },
              child: Text(
                widget.targetGame != null
                    ? "Lancer ${widget.targetGame}"
                    : "Choisir un jeu",
              ),
            ),
          ],
        ),
      ),
    );
  }

  void _launchLocalGame(String gameName) {
    Widget screen;
    bool isTeamGame = gameName == "Codenames" || gameName == "Time's Up";

    if (isTeamGame) {
      showDialog(
        context: context,
        builder: (BuildContext dialogContext) {
          return TeamSelectionDialog(
            allPlayers: _players,
            gameName: gameName,
            onTeamsConfirmed: (teamA, teamB) {
              if (gameName == "Codenames") {
                return CodenamesLocalGameScreen(
                  players: _players,
                  redTeam: teamA,
                  blueTeam: teamB,
                );
              } else {
                return TimesUpLocalGameScreen(
                  players: _players,
                  teamA: teamA,
                  teamB: teamB,
                );
              }
            },
          );
        },
      );
      return; // On arrÃƒÂªte ici, le dialog s'occupe du reste
    }

    // Assignation des jeux classiques
    switch (gameName) {
      case 'Qui Pourrait le Plus ?':
        screen = WhoIsMostLikelyLocalScreen(players: _players);
        break;
      case 'Infiltré & Mr. White':
      case 'Infiltré & Mr. White':
      case 'Undercover Local':
        screen = UndercoverLocalGameScreen(players: _players);
        break;
      case 'La Patate Chaude':
        screen = HotPotatoLocalScreen(players: _players);
        break;
      case 'Synonyme ou Banni':
        screen = SynonymOrBannedLocalScreen(players: _players);
        break;
      case 'Action ou Vérité':
        screen = OfflineTruthOrDareScreen(players: _players);
        break;
      case 'Jeu de la Pièce':
        screen = OfflineGameScreen(gameType: 'coin_flip', players: _players);
        break;
      case 'Le Dilemme':
        screen = OfflineGameScreen(gameType: 'dilemma', players: _players);
        break;
      case 'On se passe un objet rapidement':
        screen = PassTheObjectGameScreen(players: _players);
        break;
      case 'Devine Tête':
        screen = GuessTheWordLocalScreen(players: _players);
        break;
      case 'Dobble':
        screen = DobbleLocalScreen(players: _players);
        break;
      default:
        screen = OfflineMenuScreen(players: _players);
        break;
    }

    Navigator.pushReplacement(
      context,
      MaterialPageRoute(builder: (_) => screen),
    );
  }
}

class TeamSelectionDialog extends StatefulWidget {
  final List<String> allPlayers;
  final Widget Function(List<String> teamA, List<String> teamB)
  onTeamsConfirmed;
  final int minPlayersPerTeam;
  final String gameName;

  const TeamSelectionDialog({
    Key? key,
    required this.allPlayers,
    required this.onTeamsConfirmed,
    required this.gameName,
    this.minPlayersPerTeam = 2,
  }) : super(key: key);

  @override
  _TeamSelectionDialogState createState() => _TeamSelectionDialogState();
}

class _TeamSelectionDialogState extends State<TeamSelectionDialog> {
  late List<String> unassignedPlayers;
  List<String> teamA = [];
  List<String> teamB = [];

  @override
  void initState() {
    super.initState();
    unassignedPlayers = List.from(widget.allPlayers);
  }

  void _assignPlayer(String player, String team) {
    setState(() {
      unassignedPlayers.remove(player);
      teamA.remove(player);
      teamB.remove(player);

      if (team == 'A') teamA.add(player);
      if (team == 'B') teamB.add(player);
    });
  }

  void _unassignPlayer(String player) {
    setState(() {
      teamA.remove(player);
      teamB.remove(player);
      if (!unassignedPlayers.contains(player)) {
        unassignedPlayers.add(player);
      }
    });
  }

  void _autoBalance() {
    setState(() {
      List<String> all = List.from(widget.allPlayers)..shuffle();
      teamA.clear();
      teamB.clear();
      unassignedPlayers.clear();
      for (int i = 0; i < all.length; i++) {
        if (i % 2 == 0) {
          teamA.add(all[i]);
        } else {
          teamB.add(all[i]);
        }
      }
    });
  }

  @override
  Widget build(BuildContext context) {
    bool canConfirm =
        unassignedPlayers.isEmpty &&
        teamA.length >= widget.minPlayersPerTeam &&
        teamB.length >= widget.minPlayersPerTeam;

    return AlertDialog(
      title: Text("Ãƒâ€°quipes pour ${widget.gameName}"),
      content: Container(
        width: double.maxFinite,
        height: 400,
        child: Column(
          children: [
            ElevatedButton.icon(
              icon: Icon(Icons.sync),
              label: Text("Ãƒâ€°quilibrer AlÃƒÂ©atoirement"),
              onPressed: _autoBalance,
            ),
            SizedBox(height: 10),
            Expanded(
              child: Row(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  _buildTeamColumn(
                    "Ãƒâ€°quipe A (Rouge)",
                    teamA,
                    'A',
                    Colors.redAccent,
                  ),
                  _buildTeamColumn(
                    "Ãƒâ€°quipe B (Bleue)",
                    teamB,
                    'B',
                    Colors.blueAccent,
                  ),
                ],
              ),
            ),
            Divider(),
            Text("Joueurs non assignÃƒÂ©s"),
            Expanded(
              child: SingleChildScrollView(
                child: Wrap(
                  spacing: 6,
                  children:
                      unassignedPlayers
                          .map(
                            (p) => ActionChip(
                              label: Text(p),
                              onPressed: () {
                                if (teamA.length <= teamB.length) {
                                  _assignPlayer(p, 'A');
                                } else {
                                  _assignPlayer(p, 'B');
                                }
                              },
                            ),
                          )
                          .toList(),
                ),
              ),
            ),
          ],
        ),
      ),
      actions: [
        TextButton(
          onPressed: () => Navigator.of(context).pop(),
          child: Text("Annuler"),
        ),
        ElevatedButton(
          onPressed:
              canConfirm
                  ? () {
                    Navigator.of(context).pop();
                    Navigator.push(
                      context,
                      MaterialPageRoute(
                        builder: (_) => widget.onTeamsConfirmed(teamA, teamB),
                      ),
                    );
                  }
                  : null,
          child: Text("Confirmer & Lancer"),
        ),
      ],
    );
  }

  Widget _buildTeamColumn(
    String title,
    List<String> team,
    String teamId,
    Color color,
  ) {
    return Expanded(
      child: Column(
        children: [
          Text(
            title,
            style: TextStyle(color: color, fontWeight: FontWeight.bold),
          ),
          Expanded(
            child: ListView(
              children:
                  team
                      .map(
                        (p) => ListTile(
                          title: Text(p),
                          trailing: IconButton(
                            icon: Icon(Icons.undo, size: 18),
                            onPressed: () => _unassignPlayer(p),
                          ),
                        ),
                      )
                      .toList(),
            ),
          ),
        ],
      ),
    );
  }
}

