class _OfflineTruthOrDareScreenState extends State<OfflineTruthOrDareScreen> {
  String _difficulty = 'soft';
  String _currentContent = "";
  int _currentPlayerIndex = -1;
  bool _isSpinning = false;
  bool _playerHasToChoose = false;

  void _onWheelStopped(int selectedIndex) {
    setState(() {
      _currentPlayerIndex = selectedIndex;
      _isSpinning = false;
      _playerHasToChoose = true;
      _currentContent = "";
    });
  }

  void _generateNewContent(String type) {
    List<String> contentList =
        (type == 'truth')
            ? GameData.offlineTruths[_difficulty]!
            : GameData.offlineDares[_difficulty]!;

    String content = contentList[Random().nextInt(contentList.length)];

    if (content.contains('{player}')) {
      List<String> otherPlayers = List.from(widget.players);
      if (_currentPlayerIndex != -1) {
        otherPlayers.removeAt(_currentPlayerIndex);
      }
      if (otherPlayers.isNotEmpty) {
        content = content.replaceAll(
          '{player}',
          otherPlayers[Random().nextInt(otherPlayers.length)],
        );
      } else {
        content = content.replaceAll('{player}', 'toi-mÃƒÂªme');
      }
    }

    setState(() {
      _currentContent = content;
      _playerHasToChoose = false;
    });
  }

  @override
  Widget build(BuildContext context) {
    final currentPlayer =
        _currentPlayerIndex != -1 ? widget.players[_currentPlayerIndex] : "";

    return Scaffold(
      appBar: AppBar(
        title: Text("Action ou Vérité"),
        actions: [
          IconButton(
            icon: Icon(Icons.info_outline),
            onPressed: () => showGameRules(context, 'Action ou Vérité'),
          ),
        ],
      ),
      body: Padding(
        padding: const EdgeInsets.all(16.0),
        child: Column(
          children: [
            SegmentedButton<String>(
              segments: const [
                ButtonSegment(value: 'soft', label: Text('Soft')),
                ButtonSegment(value: 'hard', label: Text('Hard')),
                ButtonSegment(value: 'hardcore', label: Text('Hardcore')),
              ],
              selected: {_difficulty},
              onSelectionChanged: (newSelection) {
                setState(() => _difficulty = newSelection.first);
              },
            ),
            SizedBox(height: 20),
            Expanded(
              child: Center(
                child: AnimatedSwitcher(
                  duration: Duration(milliseconds: 500),
                  child: _buildMainContent(currentPlayer),
                ),
              ),
            ),
            SizedBox(height: 10),
            _buildGameControls(),
            SizedBox(height: 10),
            _buildPlayerChips(),
          ],
        ),
      ),
    );
  }

  Widget _buildMainContent(String currentPlayer) {
    if (_isSpinning) {
      return SpinTheWheelWidget(
        key: ValueKey('wheel'),
        players: widget.players,
        onSpinEnd: _onWheelStopped,
      );
    }
    if (_playerHasToChoose) {
      return Card(
        key: ValueKey('choice'),
        child: Padding(
          padding: const EdgeInsets.all(24.0),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Text(
                currentPlayer,
                style: Theme.of(context).textTheme.headlineMedium?.copyWith(
                  color: Colors.deepPurpleAccent,
                ),
              ),
              SizedBox(height: 10),
              Text(
                "Choisis ton destin...",
                style: Theme.of(context).textTheme.headlineSmall,
              ),
            ],
          ),
        ),
      );
    }
    if (_currentContent.isNotEmpty) {
      return Card(
        key: ValueKey(_currentContent),
        child: Padding(
          padding: const EdgeInsets.all(24.0),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Text(
                "C'est au tour de",
                style: Theme.of(context).textTheme.bodyMedium,
              ),
              Text(
                currentPlayer,
                style: Theme.of(context).textTheme.headlineMedium?.copyWith(
                  color: Colors.deepPurpleAccent,
                ),
              ),
              SizedBox(height: 20),
              Text(
                _currentContent,
                textAlign: TextAlign.center,
                style: Theme.of(context).textTheme.headlineSmall,
              ),
            ],
          ),
        ),
      );
    }
    return Text(
      "Appuyez sur 'Lancer la roue' pour commencer !",
      style: Theme.of(
        context,
      ).textTheme.headlineSmall?.copyWith(color: Colors.white70),
      textAlign: TextAlign.center,
    );
  }

  Widget _buildGameControls() {
    if (_isSpinning) return SizedBox(height: 50);

    if (_playerHasToChoose) {
      return Row(
        mainAxisAlignment: MainAxisAlignment.spaceEvenly,
        children: [
          ElevatedButton(
            onPressed: () => _generateNewContent('truth'),
            child: Text("VÃƒÂ©ritÃƒÂ©"),
          ),
          ElevatedButton(
            onPressed: () => _generateNewContent('dare'),
            child: Text("Action"),
          ),
        ],
      );
    }

    return ElevatedButton(
      onPressed: () => setState(() => _isSpinning = true),
      child: Text(
        _currentPlayerIndex == -1 ? "Lancer la roue" : "Tour Suivant",
      ),
    );
  }

  Widget _buildPlayerChips() {
    return Wrap(
      spacing: 8,
      runSpacing: 4,
      alignment: WrapAlignment.center,
      children: List.generate(widget.players.length, (index) {
        final isCurrent = index == _currentPlayerIndex && !_isSpinning;
        return Chip(
          label: Text(widget.players[index]),
          backgroundColor: isCurrent ? Colors.deepPurple : Color(0xFF333333),
          labelStyle: TextStyle(
            color: Colors.white,
            fontWeight: isCurrent ? FontWeight.bold : FontWeight.normal,
          ),
        );
      }),
    );
  }
}

class OfflineGameScreen extends StatefulWidget {
  final String gameType;
  final List<String> players;
  OfflineGameScreen({required this.gameType, required this.players});

  @override
  _OfflineGameScreenState createState() => _OfflineGameScreenState();
}

class _OfflineGameScreenState extends State<OfflineGameScreen> {
  String _difficulty = 'soft';
  String _currentContent = "";
  String _title = "";
  bool _showCoinFlipResult = false;
  String _coinFlipChoice = "";
  String _coinFlipResult = "";
  int _currentPlayerIndex = -1;
  bool _isSpinning = false;

  // PARAMÈTRES POUR LE DILEMME LOCAL
  bool _useWheelForDilemma = true;
  Map<String, String> _dilemmaVotes = {}; // PlayerID -> "A" ou "B"
  int _dilemmaVoterIndex = 0;
  String? _activeDilemmaVoterId;
  String _dilemmaOptionA = "";
  String _dilemmaOptionB = "";

  // --- SYSTÈME DE SCORES ---
  Map<String, int> _globalScores = {};

  @override
  void initState() {
    super.initState();
    _setTitle();
    for (var p in widget.players) {
      _globalScores[p] = 0;
    }
  }

  void _setTitle() {
    switch (widget.gameType) {
      case 'coin_flip':
        _title = "Jeu de la Pièce";
        break;
      case 'dilemma':
        _title = "Le Dilemme";
        break;
    }
  }

  void _showScoreDialog(String selectedPlayer) {
    showDialog(
      context: context,
      builder: (ctx) {
        return StatefulBuilder(
          builder: (context, setStateDialog) {
            return AlertDialog(
              title: const Text(
                "Gérer les Scores",
                textAlign: TextAlign.center,
              ),
              content: Column(
                mainAxisSize: MainAxisSize.min,
                children:
                    widget.players.map((p) {
                      bool isSelected = p == selectedPlayer;
                      return ListTile(
                        title: Text(
                          p,
                          style: TextStyle(
                            fontWeight:
                                isSelected
                                    ? FontWeight.bold
                                    : FontWeight.normal,
                            color: isSelected ? Colors.amber : Colors.white,
                          ),
                        ),
                        trailing: Row(
                          mainAxisSize: MainAxisSize.min,
                          children: [
                            IconButton(
                              icon: const Icon(
                                Icons.remove_circle_outline,
                                color: Colors.redAccent,
                              ),
                              onPressed: () {
                                setState(() {
                                  _globalScores[p] =
                                      (_globalScores[p] ?? 0) - 1;
                                });
                                setStateDialog(() {});
                              },
                            ),
                            Text(
                              "${_globalScores[p]}",
                              style: const TextStyle(
                                fontSize: 18,
                                fontWeight: FontWeight.bold,
                              ),
                            ),
                            IconButton(
                              icon: const Icon(
                                Icons.add_circle_outline,
                                color: Colors.greenAccent,
                              ),
                              onPressed: () {
                                setState(() {
                                  _globalScores[p] =
                                      (_globalScores[p] ?? 0) + 1;
                                });
                                setStateDialog(() {});
                              },
                            ),
                          ],
                        ),
                      );
                    }).toList(),
              ),
              actions: [
                TextButton(
                  onPressed: () => Navigator.pop(ctx),
                  child: const Text("Fermer"),
                ),
              ],
            );
          },
        );
      },
    );
  }

  void _onWheelStopped(int selectedIndex) {
    setState(() {
      _currentPlayerIndex = selectedIndex;
      _isSpinning = false;
      _generateNewContent();
      if (widget.gameType == 'dilemma' && widget.players.isNotEmpty) {
        _activeDilemmaVoterId = widget.players[selectedIndex];
      }
    });
  }

  String _processContent(String content) {
    if (content.contains('{player}')) {
      List<String> otherPlayers = List.from(widget.players);
      if (_currentPlayerIndex >= 0 &&
          _currentPlayerIndex < otherPlayers.length) {
        otherPlayers.removeAt(_currentPlayerIndex);
      }
      if (otherPlayers.isNotEmpty) {
        String randomPlayer =
            otherPlayers[Random().nextInt(otherPlayers.length)];
        return content.replaceAll('{player}', randomPlayer);
      } else {
        return content.replaceAll('{player}', 'toi-mê-me');
      }
    }
    return content;
  }

  List<String> _splitDilemmaOptions(String content) {
    final normalized = content.trim().replaceFirst(RegExp(r'[?]+$'), '');
    final match = RegExp(
      r'\sou\s',
      caseSensitive: false,
    ).firstMatch(normalized);

    if (match == null) {
      return [normalized, 'Je passe'];
    }

    final first = normalized.substring(0, match.start).trim();
    final second = normalized.substring(match.end).trim();

    if (first.isEmpty || second.isEmpty) {
      return [normalized, 'Je passe'];
    }

    return [first, second];
  }

  String _currentDilemmaWinner() {
    final optionACount =
        _dilemmaVotes.values.where((vote) => vote == 'A').length;
    final optionBCount =
        _dilemmaVotes.values.where((vote) => vote == 'B').length;

    if (optionACount == 0 && optionBCount == 0) return '';
    if (optionACount > optionBCount) return 'A';
    if (optionBCount > optionACount) return 'B';
    return 'TIE';
  }

  void _submitDilemmaVote(String playerId, String option) {
    setState(() {
      _dilemmaVotes[playerId] = option;
      if (!_useWheelForDilemma) {
        if (_dilemmaVoterIndex < widget.players.length - 1) {
          _dilemmaVoterIndex++;
          _activeDilemmaVoterId = widget.players[_dilemmaVoterIndex];
        } else {
          _activeDilemmaVoterId = null;
        }
      } else {
        _activeDilemmaVoterId = null;
      }
    });
  }

  Widget _buildDilemmaOptionCard({
    required BuildContext context,
    required String optionKey,
    required String optionText,
    required Color color,
  }) {
    final voteCount =
        _dilemmaVotes.values.where((vote) => vote == optionKey).length;
    final totalVotes = _dilemmaVotes.isEmpty ? 1 : _dilemmaVotes.length;
    final progress = (voteCount / totalVotes).clamp(0.0, 1.0);
    final winner = _currentDilemmaWinner();
    final isWinning = winner == optionKey;
    final isTied = winner == 'TIE';

    return Expanded(
      child: GestureDetector(
        onTap:
            _activeDilemmaVoterId == null
                ? null
                : () => _submitDilemmaVote(_activeVoterOrCurrent(), optionKey),
        child: AnimatedContainer(
          duration: const Duration(milliseconds: 250),
          padding: const EdgeInsets.all(16),
          decoration: BoxDecoration(
            color:
                isWinning ? color.withOpacity(0.28) : color.withOpacity(0.16),
            borderRadius: BorderRadius.circular(18),
            border: Border.all(
              color: isWinning ? color : Colors.white12,
              width: isWinning ? 2.5 : 1.0,
            ),
          ),
          child: Column(
            mainAxisAlignment: MainAxisAlignment.center,
            children: [
              Text(
                optionText,
                textAlign: TextAlign.center,
                style: Theme.of(context).textTheme.titleLarge?.copyWith(
                  color: Colors.white,
                  fontWeight: FontWeight.bold,
                  fontSize: 16,
                ),
              ),
              const SizedBox(height: 14),
              ClipRRect(
                borderRadius: BorderRadius.circular(999),
                child: LinearProgressIndicator(
                  minHeight: 10,
                  value: progress,
                  backgroundColor: Colors.white10,
                  valueColor: AlwaysStoppedAnimation<Color>(color),
                ),
              ),
              const SizedBox(height: 10),
              Text(
                '$voteCount vote${voteCount > 1 ? 's' : ''}',
                style: const TextStyle(
                  color: Colors.white70,
                  fontWeight: FontWeight.w600,
                ),
              ),
              if (isWinning && voteCount > 0)
                Padding(
                  padding: const EdgeInsets.only(top: 8.0),
                  child: Text(
                    isTied ? 'Égalité' : 'Majoritaire',
                    style: TextStyle(color: color, fontWeight: FontWeight.bold),
                  ),
                ),
            ],
          ),
        ),
      ),
    );
  }

  String _getInstructionText() {
    if (_useWheelForDilemma) {
      final voterName =
          _currentPlayerIndex != -1
              ? widget.players[_currentPlayerIndex]
              : '...';
      return _activeDilemmaVoterId == null
          ? "Choix enregistré !"
          : "Dilemme pour $voterName : fait ton choix !";
    } else {
      return _activeDilemmaVoterId == null
          ? "Tous les votes sont enregistrés !"
          : "C'est au tour de $_activeDilemmaVoterId de voter !";
    }
  }

  String _getCurrentVoterName() {
    return _useWheelForDilemma
        ? (_currentPlayerIndex != -1
            ? widget.players[_currentPlayerIndex]
            : "Joueur")
        : (_activeDilemmaVoterId ?? "Fin");
  }

  String _activeVoterOrCurrent() {
    return _useWheelForDilemma
        ? _getCurrentVoterName()
        : (_activeDilemmaVoterId ?? "");
  }

  Widget _buildDilemmaVoteUI(BuildContext context) {
    final allVotesCast =
        _useWheelForDilemma
            ? _dilemmaVotes.isNotEmpty
            : _dilemmaVotes.length >= widget.players.length;

    return LayoutBuilder(
      builder: (context, constraints) {
        return SingleChildScrollView(
          padding: const EdgeInsets.only(bottom: 16),
          child: ConstrainedBox(
            constraints: BoxConstraints(minHeight: constraints.maxHeight),
            child: Column(
              mainAxisAlignment: MainAxisAlignment.center,
              children: [
                Card(
                  elevation: 6,
                  color: Colors.blueGrey[900],
                  shape: RoundedRectangleBorder(
                    borderRadius: BorderRadius.circular(20),
                  ),
                  child: Padding(
                    padding: const EdgeInsets.all(20.0),
                    child: Column(
                      children: [
                        const Text(
                          'LE DILEMME',
                          style: TextStyle(
                            color: Colors.amberAccent,
                            letterSpacing: 2,
                            fontWeight: FontWeight.bold,
                          ),
                        ),
                        const SizedBox(height: 12),
                        Text(
                          _currentContent,
                          textAlign: TextAlign.center,
                          style: Theme.of(
                            context,
                          ).textTheme.headlineSmall?.copyWith(fontSize: 20),
                        ),
                      ],
                    ),
                  ),
                ),
                const SizedBox(height: 16),
                Text(
                  _getInstructionText(),
                  style: Theme.of(context).textTheme.titleMedium?.copyWith(
                    color: Colors.white,
                    fontWeight: FontWeight.bold,
                  ),
                  textAlign: TextAlign.center,
                ),
                const SizedBox(height: 12),
                if (!_useWheelForDilemma && _activeDilemmaVoterId != null)
                  Wrap(
                    spacing: 8,
                    runSpacing: 8,
                    alignment: WrapAlignment.center,
                    children:
                        widget.players.map((player) {
                          final hasVoted = _dilemmaVotes.containsKey(player);
                          final isActive = player == _activeDilemmaVoterId;
                          return Chip(
                            label: Text(player),
                            backgroundColor:
                                isActive
                                    ? Colors.deepPurple
                                    : (hasVoted
                                        ? Colors.green[800]
                                        : Colors.white10),
                            labelStyle: TextStyle(
                              color: Colors.white,
                              fontWeight:
                                  isActive
                                      ? FontWeight.bold
                                      : FontWeight.normal,
                            ),
                          );
                        }).toList(),
                  ),
                const SizedBox(height: 20),
                Row(
                  children: [
                    _buildDilemmaOptionCard(
                      context: context,
                      optionKey: 'A',
                      optionText: _dilemmaOptionA,
                      color: Colors.deepPurpleAccent,
                    ),
                    const SizedBox(width: 12),
                    _buildDilemmaOptionCard(
                      context: context,
                      optionKey: 'B',
                      optionText: _dilemmaOptionB,
                      color: Colors.teal,
                    ),
                  ],
                ),
                const SizedBox(height: 20),
                if (allVotesCast)
                  ElevatedButton.icon(
                    icon: const Icon(Icons.arrow_forward),
                    label: const Text('Dilemme Suivant'),
                    style: ElevatedButton.styleFrom(
                      backgroundColor: Colors.green,
                      padding: const EdgeInsets.symmetric(
                        horizontal: 24,
                        vertical: 12,
                      ),
                    ),
                    onPressed:
                        () => setState(() {
                          _isSpinning = false;
                          _currentContent = "";
                          _currentPlayerIndex = -1;
                          _dilemmaVotes.clear();
                          _activeDilemmaVoterId = null;
                          _dilemmaOptionA = "";
                          _dilemmaOptionB = "";
                        }),
                  )
                else if (_useWheelForDilemma)
                  const Text(
                    'Le joueur désigné doit faire son choix.',
                    style: TextStyle(
                      color: Colors.white38,
                      fontStyle: FontStyle.italic,
                    ),
                  )
                else
                  Text(
                    'En attente du vote de : $_activeDilemmaVoterId (${_dilemmaVotes.length} / ${widget.players.length})',
                    style: const TextStyle(
                      color: Colors.white54,
                      fontStyle: FontStyle.italic,
                    ),
                  ),
              ],
            ),
          ),
        );
      },
    );
  }

  void _generateNewContent() {
    List<String> contentList = [];
    Random random = Random();
    String nextContent = "";

    switch (widget.gameType) {
      case 'coin_flip':
        contentList = GameData.offlineCoinFlipQuestions[_difficulty]!;
        _showCoinFlipResult = false;
        break;
      case 'dilemma':
        contentList = GameData.offlineDilemmas[_difficulty]!;
        break;
    }

    nextContent = _processContent(
      contentList[random.nextInt(contentList.length)],
    );

    setState(() {
      _currentContent = nextContent;
      if (widget.gameType == 'dilemma') {
        final dilemmaOptions = _splitDilemmaOptions(nextContent);
        _dilemmaOptionA = dilemmaOptions[0];
        _dilemmaOptionB = dilemmaOptions[1];
        _dilemmaVotes.clear();

        if (_useWheelForDilemma) {
          _activeDilemmaVoterId =
              _currentPlayerIndex != -1
                  ? widget.players[_currentPlayerIndex]
                  : null;
        } else {
          _dilemmaVoterIndex = 0;
          _activeDilemmaVoterId =
              widget.players.isNotEmpty ? widget.players.first : null;
        }
      }
    });
  }

  void _flipCoin() {
    Random random = Random();
    setState(() {
      _coinFlipResult = random.nextBool() ? "Pile" : "Face";
      _showCoinFlipResult = true;
    });
  }

  void _startNextDilemmaRoundDirectly() {
    setState(() {
      _isSpinning = false;
      _generateNewContent();
    });
  }

  @override
  Widget build(BuildContext context) {
    final currentPlayer =
        _currentPlayerIndex != -1 ? widget.players[_currentPlayerIndex] : "";
    final isDilemma = widget.gameType == 'dilemma';

    return Scaffold(
      appBar: AppBar(
        title: Text(_title),
        actions: [
          IconButton(
            icon: const Icon(Icons.info_outline),
            onPressed: () => showGameRules(context, _title),
          ),
        ],
      ),
      body: Padding(
        padding: const EdgeInsets.all(16.0),
        child: Column(
          children: [
            // FILTRE DIFFICULTE
            SegmentedButton<String>(
              segments: const [
                ButtonSegment(value: 'soft', label: Text('Soft')),
                ButtonSegment(value: 'hard', label: Text('Hard')),
                ButtonSegment(value: 'hardcore', label: Text('Hardcore')),
              ],
              selected: {_difficulty},
              onSelectionChanged: (newSelection) {
                setState(() {
                  _difficulty = newSelection.first;
                  if (!_isSpinning && _currentContent.isNotEmpty) {
                    _generateNewContent();
                  }
                });
              },
            ),
            const SizedBox(height: 12),

            if (isDilemma && _currentContent.isEmpty && !_isSpinning) ...[
              Card(
                color: Colors.grey[900],
                shape: RoundedRectangleBorder(
                  borderRadius: BorderRadius.circular(15),
                ),
                child: Padding(
                  padding: const EdgeInsets.symmetric(
                    vertical: 8.0,
                    horizontal: 16.0,
                  ),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.stretch,
                    children: [
                      const Text(
                        "Mode de sélection du Dilemme",
                        style: TextStyle(
                          fontWeight: FontWeight.bold,
                          color: Colors.white70,
                        ),
                        textAlign: TextAlign.center,
                      ),
                      const SizedBox(height: 10),
                      SegmentedButton<bool>(
                        segments: const [
                          ButtonSegment(
                            value: true,
                            label: Text('Avec Roue'),
                            icon: Icon(Icons.blur_circular),
                          ),
                          ButtonSegment(
                            value: false,
                            label: Text('Sans Roue (Tous)'),
                            icon: Icon(Icons.people),
                          ),
                        ],
                        selected: {_useWheelForDilemma},
                        onSelectionChanged:
                            (val) => setState(() {
                              _useWheelForDilemma = val.first;
                            }),
                      ),
                    ],
                  ),
                ),
              ),
              const SizedBox(height: 12),
            ],

            Expanded(
              child: Center(
                child: AnimatedSwitcher(
                  duration: const Duration(milliseconds: 500),
                  transitionBuilder:
                      (child, animation) =>
                          ScaleTransition(scale: animation, child: child),
                  child:
                      isDilemma && _currentContent.isNotEmpty
                          ? _buildDilemmaVoteUI(context)
                          : _isSpinning
                          ? SpinTheWheelWidget(
                            key: const ValueKey('wheel_spin'),
                            players: widget.players,
                            onSpinEnd: _onWheelStopped,
                          )
                          : (_currentContent.isEmpty
                              ? Text(
                                "Appuyez sur 'Lancer le tour' pour commencer !",
                                style: Theme.of(context).textTheme.headlineSmall
                                    ?.copyWith(color: Colors.white70),
                                textAlign: TextAlign.center,
                              )
                              : Card(
                                key: ValueKey<String>(_currentContent),
                                elevation: 4,
                                child: Padding(
                                  padding: const EdgeInsets.all(24.0),
                                  child: Column(
                                    mainAxisSize: MainAxisSize.min,
                                    mainAxisAlignment: MainAxisAlignment.center,
                                    children: [
                                      Text(
                                        "C'est au tour de",
                                        style:
                                            Theme.of(
                                              context,
                                            ).textTheme.bodyMedium,
                                      ),
                                      Text(
                                        currentPlayer,
                                        style: Theme.of(
                                          context,
                                        ).textTheme.headlineMedium?.copyWith(
                                          color: Colors.deepPurpleAccent,
                                        ),
                                      ),
                                      const SizedBox(height: 20),
                                      Text(
                                        _currentContent,
                                        textAlign: TextAlign.center,
                                        style:
                                            Theme.of(
                                              context,
                                            ).textTheme.headlineSmall,
                                      ),
                                      if (widget.gameType == 'coin_flip' &&
                                          _showCoinFlipResult)
                                        _buildCoinFlipResult(),
                                    ],
                                  ),
                                ),
                              )),
                ),
              ),
            ),
            const SizedBox(height: 10),
            _buildGameControls(),
            const SizedBox(height: 10),
            if (!isDilemma || _currentContent.isEmpty || _isSpinning)
              _buildPlayerChips(),
          ],
        ),
      ),
    );
  }

  Widget _buildPlayerChips() {
    return Wrap(
      spacing: 8,
      runSpacing: 4,
      alignment: WrapAlignment.center,
      children: List.generate(widget.players.length, (index) {
        final pName = widget.players[index];
        final isCurrent = index == _currentPlayerIndex && !_isSpinning;
        return ActionChip(
          avatar: CircleAvatar(
            backgroundColor: Colors.white24,
            child: Text(
              pName[0],
              style: const TextStyle(fontSize: 10, color: Colors.white),
            ),
          ),
          label: Text("$pName : ${_globalScores[pName]} pts"),
          backgroundColor:
              isCurrent ? Colors.deepPurple : const Color(0xFF333333),
          labelStyle: TextStyle(
            color: Colors.white,
            fontWeight: isCurrent ? FontWeight.bold : FontWeight.normal,
          ),
          onPressed: () => _showScoreDialog(pName),
        );
      }),
    );
  }

  Widget _buildCoinFlipResult() {
    bool lost = _coinFlipChoice != _coinFlipResult;
    return Padding(
      padding: const EdgeInsets.only(top: 20.0),
      child: Column(
        children: [
          Text(
            "Tu as choisi $_coinFlipChoice. La pièce est tombée sur... $_coinFlipResult !",
            style: const TextStyle(fontWeight: FontWeight.bold),
          ),
          const SizedBox(height: 10),
          Text(
            lost
                ? "PERDU ! Révèle la question et réponds-y !"
                : "GAGNÉ ! Ton secret est préservé.",
            style: TextStyle(
              fontSize: 18,
              color: lost ? Colors.redAccent : Colors.greenAccent,
              fontWeight: FontWeight.bold,
            ),
            textAlign: TextAlign.center,
          ),
        ],
      ),
    );
  }

  Widget _buildGameControls() {
    if (_isSpinning) return const SizedBox(height: 50);

    if (widget.gameType == 'dilemma' && _currentContent.isNotEmpty) {
      return const SizedBox.shrink();
    }

    if (_currentContent.isEmpty) {
      return ElevatedButton(
        onPressed: () {
          if (widget.gameType == 'dilemma' && !_useWheelForDilemma) {
            _startNextDilemmaRoundDirectly();
          } else {
            setState(() => _isSpinning = true);
          }
        },
        child: Text(
          widget.gameType == 'dilemma' && !_useWheelForDilemma
              ? "Lancer le Dilemme"
              : "Lancer la roue",
        ),
      );
    }

    if (widget.gameType == 'coin_flip' && _showCoinFlipResult) {
      return ElevatedButton(
        onPressed:
            () => setState(() {
              _isSpinning = true;
              _currentContent = "";
            }),
        child: const Text("Tour Suivant"),
      );
    }

    if (widget.gameType == 'coin_flip') {
      return Row(
        mainAxisAlignment: MainAxisAlignment.spaceEvenly,
        children: [
          ElevatedButton(
            onPressed: () {
              _coinFlipChoice = "Pile";
              _flipCoin();
            },
            child: const Text("Je choisis PILE"),
          ),
          ElevatedButton(
            onPressed: () {
              _coinFlipChoice = "Face";
              _flipCoin();
            },
            child: const Text("Je choisis FACE"),
          ),
        ],
      );
    }
    return const SizedBox.shrink();
  }
}

class SpinTheWheelWidget extends StatefulWidget {
  final List<String> players;
  final Function(int) onSpinEnd;

  const SpinTheWheelWidget({
    Key? key,
    required this.players,
    required this.onSpinEnd,
  }) : super(key: key);

  @override
  _SpinTheWheelWidgetState createState() => _SpinTheWheelWidgetState();
}

class _SpinTheWheelWidgetState extends State<SpinTheWheelWidget>
    with SingleTickerProviderStateMixin {
  late AnimationController _controller;
  late Animation<double> _rotationAnimation;
  double _finalRotationAngle = 0.0;
  final Random _random = Random();

  @override
  void initState() {
    super.initState();
    _controller = AnimationController(
      vsync: this,
      duration: Duration(seconds: 4),
    );
    _spinWheel();
  }

  void _spinWheel() {
    double randomRotations = 8 + _random.nextDouble() * 4;
    _finalRotationAngle = randomRotations * 2 * pi;

    _rotationAnimation = Tween<double>(
      begin: 0.0,
      end: _finalRotationAngle,
    ).animate(CurvedAnimation(parent: _controller, curve: Curves.easeOutCubic));

    _controller.forward(from: 0).then((_) {
      _determineWinner();
    });
  }

  void _determineWinner() {
    if (widget.players.isEmpty) return;
    double segmentAngle = (2 * pi) / widget.players.length;
    double normalizedAngle = _finalRotationAngle % (2 * pi);
    int winnerIndex =
        ((2 * pi - normalizedAngle) / segmentAngle).floor() %
        widget.players.length;
    widget.onSpinEnd(winnerIndex);
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Column(
      mainAxisAlignment: MainAxisAlignment.center,
      children: [
        Text(
          "La roue tourne...",
          style: Theme.of(context).textTheme.headlineSmall,
        ),
        SizedBox(height: 20),
        SizedBox(
          width: 300,
          height: 300,
          child: Stack(
            alignment: Alignment.center,
            children: [
              AnimatedBuilder(
                animation: _rotationAnimation,
                builder: (context, child) {
                  return Transform.rotate(
                    angle: _rotationAnimation.value,
                    child: SizedBox(
                      width: 280,
                      height: 280,
                      child: CustomPaint(
                        painter: _WheelPainter(widget.players),
                      ),
                    ),
                  );
                },
              ),
              Container(
                width: 30,
                height: 30,
                decoration: BoxDecoration(
                  color: Colors.white,
                  shape: BoxShape.circle,
                  border: Border.all(color: Colors.deepPurple, width: 2),
                ),
              ),
              Positioned(
                top: 5,
                child: Icon(
                  Icons.keyboard_arrow_down,
                  color: Colors.redAccent,
                  size: 40,
                ),
              ),
            ],
          ),
        ),
      ],
    );
  }
}

class _WheelPainter extends CustomPainter {
  final List<String> players;
  static const List<Color> colors = [
    Color(0xFF1976D2),
    Color(0xFF388E3C),
    Color(0xFFF57C00),
    Color(0xFFD32F2F),
    Color(0xFF7B1FA2),
    Color(0xFF689F38),
    Color(0xFF0288D1),
    Color(0xFFE64A19),
    Color(0xFF5D4037),
    Color(0xFF455A64),
  ];

  _WheelPainter(this.players);

  @override
  void paint(Canvas canvas, Size size) {
    final center = Offset(size.width / 2, size.height / 2);
    final radius = size.width / 2;
    if (players.isEmpty) return;
    final segmentAngle = 2 * pi / players.length;

    for (int i = 0; i < players.length; i++) {
      final paint =
          Paint()
            ..color = colors[i % colors.length]
            ..style = PaintingStyle.fill;
      final startAngle = -pi / 2 + i * segmentAngle;
      final path = Path();
      path.moveTo(center.dx, center.dy);
      path.arcTo(
        Rect.fromCircle(center: center, radius: radius),
        startAngle,
        segmentAngle,
        false,
      );
      path.close();
      canvas.drawPath(path, paint);

      final borderPaint =
          Paint()
            ..color = Colors.white
            ..style = PaintingStyle.stroke
            ..strokeWidth = 2;
      canvas.drawPath(path, borderPaint);

      final textAngle = startAngle + segmentAngle / 2;
      final textRadius = radius * 0.65;
      final textCenter = Offset(
        center.dx + textRadius * cos(textAngle),
        center.dy + textRadius * sin(textAngle),
      );
      final textPainter = TextPainter(
        text: TextSpan(
          text: players[i],
          style: TextStyle(
            color: Colors.white,
            fontSize: 14,
            fontWeight: FontWeight.bold,
          ),
        ),
        textAlign: TextAlign.center,
        textDirection: TextDirection.ltr,
      );
      textPainter.layout();
      canvas.save();
      canvas.translate(textCenter.dx, textCenter.dy);
      double rotation = textAngle + pi / 2;
      if (rotation > pi / 2 && rotation < 3 * pi / 2) {
        rotation += pi;
      }
      canvas.rotate(rotation);
      textPainter.paint(
        canvas,
        Offset(-textPainter.width / 2, -textPainter.height / 2),
      );
      canvas.restore();
    }
  }

  @override
  bool shouldRepaint(covariant CustomPainter oldDelegate) => false;
}

enum UndercoverGameState { setup, revealing, discussing, voting, result }

class UndercoverLocalGameScreen extends StatefulWidget {
