  Widget _buildBoard({required bool showKey}) {
    return GridView.builder(
      padding: EdgeInsets.all(8),
      gridDelegate: SliverGridDelegateWithFixedCrossAxisCount(
        crossAxisCount: 5,
        childAspectRatio: 1.4, // Format paysage carte de visite
        crossAxisSpacing: 6.0,
        mainAxisSpacing: 6.0,
      ),
      itemCount: _boardWords.length,
      itemBuilder: (context, index) {
        String word = _boardWords[index];
        String actualColor = _wordKeyMap[word]!;
        bool isRevealed = _revealedWords[word] ?? false;

        // Design de la carte
        Color cardColor = Color(0xFFE0C097); // Couleur beige "dossier secret"
        Color textColor = Colors.black87;
        IconData? statusIcon;
        Color? overlayColor;

        if (isRevealed) {
          if (actualColor == 'red') {
            cardColor = Colors.red[800]!;
            textColor = Colors.white;
            statusIcon = Icons.person; // Agent Rouge
          } else if (actualColor == 'blue') {
            cardColor = Colors.blue[900]!;
            textColor = Colors.white;
            statusIcon = Icons.person; // Agent Bleu
          } else if (actualColor == 'assassin') {
            cardColor = Colors.black;
            textColor = Colors.white;
            statusIcon = Icons.dangerous; // Assassin
          } else {
            cardColor = Colors.brown[300]!; // TÃƒÂ©moin
            textColor = Colors.white70;
            statusIcon = Icons.directions_walk;
          }
        } else if (showKey) {
          // Vue MaÃƒÂ®tre Espion (teinte lÃƒÂ©gÃƒÂ¨re)
          if (actualColor == 'red') overlayColor = Colors.red.withOpacity(0.3);
          if (actualColor == 'blue')
            overlayColor = Colors.blue.withOpacity(0.3);
          if (actualColor == 'assassin')
            overlayColor = Colors.black.withOpacity(0.5);
        }

        return GestureDetector(
          onTap:
              !showKey &&
                      !isRevealed // Logique de clic (gardez votre logique existante ici)
                  ? () => _selectWord(word)
                  : null,
          child: AnimatedContainer(
            duration: Duration(milliseconds: 400),
            curve: Curves.easeInOut,
            transform:
                Matrix4.identity()..scale(
                  isRevealed ? 0.95 : 1.0,
                ), // Petit effet de "flip" simulÃƒÂ©
            decoration: BoxDecoration(
              color: cardColor,
              borderRadius: BorderRadius.circular(6),
              boxShadow: [
                BoxShadow(
                  color: Colors.black38,
                  offset: Offset(1, 2),
                  blurRadius: 3,
                ),
              ],
              border:
                  showKey && overlayColor != null
                      ? Border.all(
                        color:
                            actualColor == 'red'
                                ? Colors.red
                                : (actualColor == 'blue'
                                    ? Colors.blue
                                    : Colors.black),
                        width: 2,
                      )
                      : null,
            ),
            child: Stack(
              children: [
                // Fond colorÃƒÂ© pour maÃƒÂ®tre espion
                if (overlayColor != null) Container(color: overlayColor),

                // Contenu
                Center(
                  child: Column(
                    mainAxisAlignment: MainAxisAlignment.center,
                    children: [
                      if (isRevealed && statusIcon != null)
                        Icon(
                          statusIcon,
                          color: Colors.white.withOpacity(0.5),
                          size: 24,
                        ),
                      Padding(
                        padding: const EdgeInsets.symmetric(horizontal: 4.0),
                        child: Text(
                          word.toUpperCase(),
                          textAlign: TextAlign.center,
                          style: TextStyle(
                            color: textColor,
                            fontWeight: FontWeight.bold,
                            fontSize: 11, // Police plus petite pour tenir
                            letterSpacing: 0.5,
                          ),
                          maxLines: 2,
                          overflow: TextOverflow.ellipsis,
                        ),
                      ),
                    ],
                  ),
                ),
              ],
            ),
          ),
        );
      },
    );
  }
}

enum TimesUpLocalGameState {
  setup,
  wordInput,
  round1,
  round2,
  round3,
  gameOver,
}

class TimesUpLocalGameScreen extends StatefulWidget {
  final List<String> players;
  final List<String>? teamA; // Ãƒâ€°quipes optionnelles
  final List<String>? teamB;

  const TimesUpLocalGameScreen({
    Key? key,
    required this.players,
    this.teamA,
    this.teamB,
  }) : super(key: key);

  @override
  _TimesUpLocalGameScreenState createState() => _TimesUpLocalGameScreenState();
}

class _TimesUpLocalGameScreenState extends State<TimesUpLocalGameScreen> {
  TimesUpLocalGameState _gameState = TimesUpLocalGameState.setup;
  List<String> _redTeam = [];
  List<String> _blueTeam = [];
  List<String> _allWords = [];
  List<String> _currentDeck = [];
  List<String> _discardedWords = [];

  Map<String, int> _teamScores = {'red': 0, 'blue': 0};
  int _currentRoundNumber = 1;
  int _totalRounds = 3;
  int _currentPlayerIndex = 0;
  String _activeTeam = 'red';
  int _timeRemaining = 30;
  Timer? _turnTimer;

  final TextEditingController _wordInputController = TextEditingController();
  final TextEditingController _aiController = TextEditingController();
  bool _isAiLoading = false;

  Map<String, List<String>> _playersWords = {};

  @override
  void initState() {
    super.initState();
    if (widget.players.length < 4) {
      _gameState = TimesUpLocalGameState.gameOver;
      _teamScores['red'] = -1;
      _teamScores['blue'] = -1;
    } else {
      _assignTeams();
    }
  }

  @override
  void dispose() {
    _turnTimer?.cancel();
    _wordInputController.dispose();
    _aiController.dispose();
    super.dispose();
  }

  void _assignTeams() {
    if (widget.teamA != null && widget.teamB != null) {
      _redTeam =
          widget.teamA!; // Utilise _redTeam et _blueTeam comme noms internes
      _blueTeam = widget.teamB!;
    } else {
      List<String> shuffledPlayers = List.from(widget.players)..shuffle();
      int mid = shuffledPlayers.length ~/ 2;
      _redTeam = shuffledPlayers.sublist(0, mid);
      _blueTeam = shuffledPlayers.sublist(mid);
    }
    for (var player in widget.players) {
      _playersWords[player] = [];
    }
  }

  void _addPlayerWord(String player, String word) {
    if (word.trim().isNotEmpty) {
      setState(() {
        _playersWords[player]?.add(word.trim());
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text(
              "Mot ajoutÃƒÂ© pour $player ! Total: ${_playersWords[player]?.length}",
            ),
          ),
        );
      });
    }
  }

  void _finishWordInput() {
    _allWords.clear();
    _playersWords.values.forEach((list) => _allWords.addAll(list));
    _allWords.shuffle();
    _currentDeck = List.from(_allWords);

    setState(() {
      _gameState = TimesUpLocalGameState.round1;
      _startTurn();
    });
  }

  void _startTurn() {
    _turnTimer?.cancel();
    _discardedWords.clear();

    if (_currentDeck.isEmpty) {
      _moveToNextRoundPhase();
      return;
    }

    List<String> currentTeamPlayers =
        (_activeTeam == 'red' ? _redTeam : _blueTeam);
    if (currentTeamPlayers.isEmpty) {
      _moveToNextRoundPhase();
      return;
    }
    _currentPlayerIndex = (_currentPlayerIndex + 1) % currentTeamPlayers.length;

    if (_currentPlayerIndex == 0) {
      _activeTeam = (_activeTeam == 'red' ? 'blue' : 'red');
      currentTeamPlayers = (_activeTeam == 'red' ? _redTeam : _blueTeam);
      _currentPlayerIndex = 0;
    }

    _timeRemaining = 30;
    _turnTimer = Timer.periodic(Duration(seconds: 1), (timer) {
      setState(() {
        if (_timeRemaining > 0) {
          _timeRemaining--;
        } else {
          timer.cancel();
          _endTurn();
        }
      });
    });

    setState(() {});
  }

  void _endTurn() {
    _turnTimer?.cancel();

    if (_currentDeck.isEmpty) {
      _moveToNextRoundPhase();
    } else {
      _startTurn();
    }
  }

  void _guessWord(String word, bool guessed) {
    setState(() {
      if (_currentDeck.contains(word)) {
        _currentDeck.remove(word);
        if (guessed) {
          _teamScores[_activeTeam] = (_teamScores[_activeTeam] ?? 0) + 1;
        }
        _discardedWords.add(word);
      }
      if (_currentDeck.isEmpty) {
        _endTurn();
      } else {}
    });
  }

  void _moveToNextRoundPhase() {
    _turnTimer?.cancel();
    _currentRoundNumber++;
    _currentPlayerIndex = 0;
    _activeTeam = 'red';

    if (_currentRoundNumber > _totalRounds) {
      _gameState = TimesUpLocalGameState.gameOver;
    } else {
      _currentDeck = List.from(_allWords)..shuffle();
      _discardedWords.clear();
      if (_currentRoundNumber == 2)
        _gameState = TimesUpLocalGameState.round2;
      else if (_currentRoundNumber == 3)
        _gameState = TimesUpLocalGameState.round3;

      _startTurn();
    }
  }

  void _resetGame() {
    _turnTimer?.cancel();
    setState(() {
      _gameState = TimesUpLocalGameState.setup;
      _allWords.clear();
      _currentDeck.clear();
      _discardedWords.clear();
      _teamScores = {'red': 0, 'blue': 0};
      _currentRoundNumber = 1;
      _currentPlayerIndex = 0;
      _activeTeam = 'red';
      _playersWords.forEach((key, value) => value.clear());
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: Text("Time's Up"),
        actions: [
          IconButton(
            icon: Icon(Icons.info_outline),
            onPressed: () => showGameRules(context, 'Time\'s Up'),
          ),
        ],
      ),
      body: Padding(
        padding: const EdgeInsets.all(16.0),
        child: AnimatedSwitcher(
          duration: Duration(milliseconds: 300),
          child: _buildContent(),
        ),
      ),
    );
  }

  Widget _buildContent() {
    switch (_gameState) {
      case TimesUpLocalGameState.setup:
        return _buildSetupPhase();
      case TimesUpLocalGameState.wordInput:
        return _buildWordInputPhase();
      case TimesUpLocalGameState.round1:
      case TimesUpLocalGameState.round2:
      case TimesUpLocalGameState.round3:
        return _buildPlayingPhase();
      case TimesUpLocalGameState.gameOver:
        return _buildGameOverScreen();
    }
  }

