enum PassTheObjectGameState { setup, playing, questionPhase }

class PassTheObjectGameScreen extends StatefulWidget {
  final List<String> players;
  const PassTheObjectGameScreen({Key? key, required this.players})
    : super(key: key);

  @override
  _PassTheObjectGameScreenState createState() =>
      _PassTheObjectGameScreenState();
}

class _PassTheObjectGameScreenState extends State<PassTheObjectGameScreen>
    with TickerProviderStateMixin {
  PassTheObjectGameState _gameState = PassTheObjectGameState.setup;
  String _difficulty = 'soft';
  Timer? _gameTimer;
  Timer? _flashTimer;
  int _secondsRemaining = 0;
  final Random _random = Random();
  String _currentQuestion = "";
  int _loserIndex = 0;
  bool _isFlashing = false;

  bool _useButton = true;
  bool _showTimer = true;

  int _minDuration = 10;
  int _maxDuration = 30;

  String? _nextPlayerToPass;
  final List<int> _passedSequence =
      []; // Historique pour éviter la répétition immédiate du même joueur

  @override
  void dispose() {
    _gameTimer?.cancel();
    _flashTimer?.cancel();
    super.dispose();
  }

  void _startGame() {
    _gameTimer?.cancel();
    _flashTimer?.cancel();
    _passedSequence.clear();

    if (_maxDuration > _minDuration) {
      _secondsRemaining =
          _minDuration + _random.nextInt(_maxDuration - _minDuration + 1);
    } else {
      _secondsRemaining = _minDuration;
    }

    _loserIndex = _random.nextInt(widget.players.length);
    _passedSequence.add(_loserIndex);
    _nextPlayerToPass = null; // Réinitialiser au début

    _gameTimer = Timer.periodic(const Duration(seconds: 1), (timer) {
      if (!mounted) {
        timer.cancel();
        return;
      }
      setState(() {
        _secondsRemaining--;
        if (_secondsRemaining <= 5 && _secondsRemaining > 0) {
          _startFlashing();
        }
        if (_secondsRemaining <= 0) {
          timer.cancel();
          _flashTimer?.cancel();
          _triggerQuestion();
        }
      });
    });

    setState(() {
      _gameState = PassTheObjectGameState.playing;
    });
  }

  void _passToRandomPlayer() {
    if (widget.players.length < 2) return;

    // Règle équitable : sélectionne un joueur différent qui n'a pas eu l'objet récemment
    List<int> eligibleIndices = [];
    for (int i = 0; i < widget.players.length; i++) {
      if (i != _loserIndex) {
        eligibleIndices.add(i);
      }
    }

    int nextIdx = eligibleIndices[_random.nextInt(eligibleIndices.length)];
    String nextPlayer = widget.players[nextIdx];

    setState(() {
      _nextPlayerToPass = nextPlayer;
      _loserIndex = nextIdx;
      _passedSequence.add(nextIdx);
    });
  }

  void _startFlashing() {
    _flashTimer?.cancel();
    _flashTimer = Timer.periodic(const Duration(milliseconds: 300), (timer) {
      if (!mounted) {
        timer.cancel();
        return;
      }
      setState(() {
        _isFlashing = !_isFlashing;
      });
    });
  }

  void _triggerQuestion() {
    final questions =
        GameData.localPassTheObjectQuestions[_difficulty] ??
        GameData.localPassTheObjectQuestions['soft']!;

    // Normalisation de la question pour éviter les caractères corrompus
    String rawQ = questions[_random.nextInt(questions.length)];
    String cleanQ = FirebaseService.sanitizeUserInput(rawQ, maxLength: 150);

    setState(() {
      _currentQuestion = cleanQ;
      _gameState = PassTheObjectGameState.questionPhase;
      _isFlashing = false;
    });
  }

  void _resetGame() {
    _gameTimer?.cancel();
    _flashTimer?.cancel();
    _passedSequence.clear();
    setState(() {
      _gameState = PassTheObjectGameState.setup;
      _currentQuestion = "";
      _secondsRemaining = 0;
      _isFlashing = false;
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: Text("Passe l'Objet"),
        actions: [
          IconButton(
            icon: Icon(Icons.info_outline),
            onPressed:
                () => showGameRules(context, 'On se passe un objet rapidement'),
          ),
        ],
      ),
      body: AnimatedContainer(
        duration: Duration(milliseconds: 150),
        color:
            _isFlashing
                ? Colors.red.withOpacity(0.5)
                : Theme.of(context).scaffoldBackgroundColor,
        child: Padding(
          padding: const EdgeInsets.all(16.0),
          child: AnimatedSwitcher(
            duration: Duration(milliseconds: 300),
            child: _buildContentForState(),
          ),
        ),
      ),
    );
  }

  Widget _buildContentForState() {
    switch (_gameState) {
      case PassTheObjectGameState.setup:
        return _buildSetupScreen();
      case PassTheObjectGameState.playing:
        return _buildPlayingScreen();
      case PassTheObjectGameState.questionPhase:
        return _buildQuestionPhase();
    }
  }

  Widget _buildSetupScreen() {
    return SingleChildScrollView(
      key: ValueKey('setup'),
      child: Card(
        child: Padding(
          padding: const EdgeInsets.all(24.0),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              Icon(
                Icons.directions_run,
                size: 80,
                color: Colors.deepPurpleAccent,
              ),
              SizedBox(height: 10),
              Text(
                "Passe l'Objet Rapidement",
                style: Theme.of(context).textTheme.headlineMedium,
                textAlign: TextAlign.center,
              ),
              SizedBox(height: 20),
              DropdownButtonFormField<String>(
                value: _difficulty,
                items:
                    GameData.localPassTheObjectQuestions.keys
                        .map(
                          (diff) =>
                              DropdownMenuItem(value: diff, child: Text(diff)),
                        )
                        .toList(),
                onChanged: (val) => setState(() => _difficulty = val!),
                decoration: InputDecoration(
                  labelText: "DifficultÃƒÂ© des questions",
                ),
              ),
              SizedBox(height: 20),
              SwitchListTile.adaptive(
                title: Text(
                  "DÃƒÂ©signer un joueur alÃƒÂ©atoire ÃƒÂ  qui passer",
                ),
                subtitle: Text(
                  "Sinon, passez physiquement ÃƒÂ  qui vous voulez",
                ),
                value: _useButton,
                onChanged: (val) => setState(() => _useButton = val),
              ),
              SwitchListTile.adaptive(
                title: Text("Afficher le chronomÃƒÂ¨tre"),
                value: _showTimer,
                onChanged: (val) => setState(() => _showTimer = val),
              ),
              SizedBox(height: 20),
              Text(
                "Intervalle du chrono : de $_minDuration ÃƒÂ  $_maxDuration secondes",
                style: Theme.of(context).textTheme.bodyMedium,
              ),
              RangeSlider(
                values: RangeValues(
                  _minDuration.toDouble(),
                  _maxDuration.toDouble(),
                ),
                min: 1,
                max: 60,
                divisions: 59,
                labels: RangeLabels('$_minDuration s', '$_maxDuration s'),
                onChanged: (RangeValues values) {
                  setState(() {
                    _minDuration = values.start.round();
                    _maxDuration = values.end.round();
                  });
                },
              ),
              SizedBox(height: 20),
              ElevatedButton(
                onPressed: _startGame,
                child: Text("Commencer la manche"),
              ),
            ],
          ),
        ),
      ),
    );
  }

  Widget _buildPlayingScreen() {
    return Column(
      key: ValueKey('playing'),
      mainAxisAlignment: MainAxisAlignment.center,
      children: [
        if (_showTimer)
          Text(
            "Temps restant : $_secondsRemaining s",
            style: Theme.of(context).textTheme.headlineMedium,
          )
        else
          Text(
            "Passez vite !",
            style: Theme.of(context).textTheme.headlineMedium,
          ),
        SizedBox(height: 30),
        Icon(Icons.mobile_friendly, size: 100, color: Colors.greenAccent),
        SizedBox(height: 30),

        if (_useButton)
          Column(
            children: [
              ElevatedButton(
                onPressed: _passToRandomPlayer,
                child: Text("Je passe l'objet !"),
              ),
              SizedBox(height: 10),
              if (_nextPlayerToPass != null)
                Text(
                  "Passe ÃƒÂ  $_nextPlayerToPass !",
                  style: Theme.of(
                    context,
                  ).textTheme.titleLarge?.copyWith(color: Colors.amberAccent),
                ),
            ],
          ),
      ],
    );
  }

  Widget _buildQuestionPhase() {
    final loserName = widget.players[_loserIndex];
    return Column(
      key: ValueKey('question'),
      mainAxisAlignment: MainAxisAlignment.center,
      children: [
        Icon(Icons.question_mark, size: 80, color: Colors.amberAccent),
        SizedBox(height: 20),
        Text(
          "$loserName a perdu !",
          style: Theme.of(context).textTheme.headlineMedium,
          textAlign: TextAlign.center,
        ),
        SizedBox(height: 10),
        Text(
          "Il/Elle doit rÃƒÂ©pondre ÃƒÂ  la question :",
          style: Theme.of(context).textTheme.bodyMedium,
          textAlign: TextAlign.center,
        ),
        SizedBox(height: 20),
        Card(
          child: Padding(
            padding: const EdgeInsets.all(24.0),
            child: Text(
              _currentQuestion,
              style: Theme.of(context).textTheme.titleLarge,
              textAlign: TextAlign.center,
            ),
          ),
        ),
        SizedBox(height: 40),
        ElevatedButton(onPressed: _resetGame, child: Text("Nouvelle Manche")),
      ],
    );
  }
}

enum GuessTheWordGameState { setup, playing, score, gameOver }

class GuessTheWordLocalScreen extends StatefulWidget {
  final List<String> players;
  const GuessTheWordLocalScreen({Key? key, required this.players})
    : super(key: key);

  @override
  _GuessTheWordLocalGameScreenState createState() =>
      _GuessTheWordLocalGameScreenState();
}

class _GuessTheWordLocalGameScreenState extends State<GuessTheWordLocalScreen> {
  GuessTheWordGameState _gameState = GuessTheWordGameState.setup;
  Map<String, int> _playerScores = {};
  List<String> _redTeam = [];
  List<String> _blueTeam = [];
  bool _useTeams = false;
  String? _selectedCategory;
  // DifficultÃƒÂ© : soft = illimitÃƒÂ©, hard = 60s, hardcore = 30s
  String _difficulty = 'soft';
  Timer? _turnTimer;
  int _turnSecondsRemaining = 0;
  List<String> _wordsToGuess = [];
  String? _currentWord;
  int _currentPlayerIndex = 0;
  int _currentTeamIndex = 0;
  String _activeTeamName = 'Ãƒâ€°quipe Rouge';

  // DurÃƒÂ©es par difficultÃƒÂ© (0 = illimitÃƒÂ©)
  static const Map<String, int> _difficultyDurations = {
    'soft': 0,
    'hard': 60,
    'hardcore': 30,
  };

  StreamSubscription? _accelerometerSubscription;
  double _lastY = 0.0;
  Timer? _debounceTimer;

  int _guessedCount = 0;
  int _passedCount = 0;
  final TextEditingController _aiController = TextEditingController();
  bool _isAiLoading = false;
  List<String> _aiCustomWords = [];

  @override
  void initState() {
    super.initState();
    _playerScores = {for (var player in widget.players) player: 0};
  }

  @override
  void dispose() {
    _stopAccelerometer(); // Assure que les capteurs sont bien arrÃƒÂªtÃƒÂ©s
    _aiController.dispose();
    super.dispose();
  }

  void _assignTeams() {
    if (widget.players.length < 2) return;
    List<String> shuffledPlayers = List.from(widget.players)..shuffle();
    int mid = shuffledPlayers.length ~/ 2;
    _redTeam = shuffledPlayers.sublist(0, mid);
    _blueTeam = shuffledPlayers.sublist(mid);
    if (_redTeam.isEmpty) _activeTeamName = 'Ãƒâ€°quipe Bleue';
    _currentTeamIndex = 0;
  }

  void _startGame() {
    if (_useTeams) {
      _assignTeams();
      if (_redTeam.isEmpty && _blueTeam.isEmpty) {
        setState(() {
          _gameState = GuessTheWordGameState.gameOver;
          _currentWord = "Pas assez de joueurs pour former des ÃƒÂ©quipes !";
        });
        return;
      }
    }

    _wordsToGuess = _getWordsForGame().toList()..shuffle();
    if (_wordsToGuess.isEmpty) {
      setState(() {
        _gameState = GuessTheWordGameState.gameOver;
        _currentWord = "Aucun mot disponible dans cette catÃƒÂ©gorie !";
      });
      return;
    }

    _playerScores = {for (var player in widget.players) player: 0};
    _guessedCount = 0;
    _passedCount = 0;
    _currentPlayerIndex = 0;

    // DÃƒÂ©marrer le timer de manche si la difficultÃƒÂ© l'exige
    int duration = _difficultyDurations[_difficulty] ?? 0;
    if (duration > 0) {
      _turnSecondsRemaining = duration;
      _turnTimer?.cancel();
      _turnTimer = Timer.periodic(Duration(seconds: 1), (timer) {
        if (!mounted) {
          timer.cancel();
          return;
        }
        setState(() {
          if (_turnSecondsRemaining > 0) {
            _turnSecondsRemaining--;
          } else {
            timer.cancel();
            _endGame();
          }
        });
      });
    }

    _startAccelerometer(); // DÃƒÂ©marrage des capteurs
    _nextWord();

    setState(() {
      _gameState = GuessTheWordGameState.playing;
    });
  }

  void _startAccelerometer() {
    _lastY = 0.0;
    _accelerometerSubscription = accelerometerEvents.listen((
      AccelerometerEvent event,
    ) {
      if (!mounted || (_debounceTimer?.isActive ?? false)) return;

      if (event.y < -5.0 && _lastY >= -5.0) {
        HapticFeedback.vibrate();
        _debounceTimer = Timer(
          Duration(milliseconds: 700),
          () => _markWord(true),
        );
      } else if (event.y > 5.0 && _lastY <= 5.0) {
        HapticFeedback.vibrate();
        _debounceTimer = Timer(
          Duration(milliseconds: 700),
          () => _markWord(false),
        );
      }

      _lastY = event.y;
    });
  }

  void _stopAccelerometer() {
    _accelerometerSubscription?.cancel();
    _debounceTimer?.cancel();
    _turnTimer?.cancel();
  }

  List<String> _getWordsForGame() {
    if (_aiCustomWords.isNotEmpty) return List.from(_aiCustomWords);
    // If a specific category is selected, use those words
    final categoriesForDifficulty = GameWords.devineTeteCategories[_difficulty];
    if (_selectedCategory != null &&
        categoriesForDifficulty != null &&
        categoriesForDifficulty.containsKey(_selectedCategory)) {
      return List<String>.from(categoriesForDifficulty[_selectedCategory]!);
    }
    // Otherwise, use all words for the current difficulty
    if (GameWords.devineTeteByDifficulty.containsKey(_difficulty)) {
      return List<String>.from(GameWords.devineTeteByDifficulty[_difficulty]!);
    }
    // Fallback: use all categories combined
    return GameWords.devineTeteCategories.values
        .expand((cats) => cats.values.expand((words) => words))
        .toList();
  }

  void _markWord(bool guessed) {
    if (_gameState != GuessTheWordGameState.playing || !mounted) return;

    setState(() {
      if (guessed) {
        _guessedCount++;
        String currentPlayer = _getCurrentPlayer();
        _playerScores[currentPlayer] = (_playerScores[currentPlayer] ?? 0) + 1;
        if (_useTeams) {
          if (_activeTeamName == 'Ãƒâ€°quipe Rouge')
            _playerScores['redTeam'] = (_playerScores['redTeam'] ?? 0) + 1;
          else
            _playerScores['blueTeam'] = (_playerScores['blueTeam'] ?? 0) + 1;
        }
      } else {
        _passedCount++;
      }
    });
    _nextWord();
  }

  void _nextWord() {
    if (_wordsToGuess.isEmpty) {
      _endGame();
      return;
    }
    setState(() {
      _currentWord = _wordsToGuess.removeAt(0);
    });
  }

  String _getCurrentPlayer() {
    if (_useTeams) {
      if (_activeTeamName == 'Ãƒâ€°quipe Rouge') {
        return _redTeam[_currentPlayerIndex % _redTeam.length];
      } else {
        return _blueTeam[_currentPlayerIndex % _blueTeam.length];
      }
    }
    return widget.players[_currentPlayerIndex];
  }

  void _endGame() {
    _accelerometerSubscription?.cancel();
    _debounceTimer?.cancel();
    setState(() {
      _gameState = GuessTheWordGameState.score;
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: Text("Devine Tête"),
        actions: [
          IconButton(
            icon: Icon(Icons.info_outline),
            onPressed: () => showGameRules(context, 'Devine Tête'),
          ),
        ],
      ),
      body: Padding(
        padding: const EdgeInsets.all(16.0),
        child: AnimatedSwitcher(
          duration: Duration(milliseconds: 300),
          child: _buildContentForState(),
        ),
      ),
    );
  }

  Widget _buildContentForState() {
    switch (_gameState) {
      case GuessTheWordGameState.setup:
        return _buildSetupScreen();
      case GuessTheWordGameState.playing:
        return _buildPlayingScreen();
      case GuessTheWordGameState.score:
        return _buildScoreScreen();
      case GuessTheWordGameState.gameOver:
        return _buildGameOverScreen();
    }
  }

  Widget _buildSetupScreen() {
    final categoriesForDifficulty =
        GameWords.devineTeteCategories[_difficulty] ?? {};
    return SingleChildScrollView(
      key: ValueKey('setup'),
      child: Card(
        child: Padding(
          padding: const EdgeInsets.all(24.0),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              Icon(Icons.headset_mic, size: 80, color: Colors.deepPurpleAccent),
              SizedBox(height: 10),
              Text(
                "Devine Tête",
                style: Theme.of(context).textTheme.headlineMedium,
                textAlign: TextAlign.center,
              ),
              SizedBox(height: 20),
              SwitchListTile.adaptive(
                title: Text("Jouer par ÃƒÂ©quipes ?"),
                value: _useTeams,
                onChanged: (val) {
                  if (val && widget.players.length < 2) {
                    ScaffoldMessenger.of(context).showSnackBar(
                      SnackBar(
                        content: Text(
                          "Besoin d'au moins 2 joueurs pour jouer par ÃƒÂ©quipes !",
                        ),
                      ),
                    );
                    return;
                  }
                  setState(() => _useTeams = val);
                },
                secondary: Icon(Icons.people_alt),
              ),
              SizedBox(height: 16),
              // Difficulty toggle buttons
              Text("Niveau", style: Theme.of(context).textTheme.titleMedium),
              SizedBox(height: 8),
              SegmentedButton<String>(
                segments: const [
                  ButtonSegment(
                    value: 'soft',
                    label: Text('Ã°Å¸Å¸Â¢ Soft'),
                    icon: Icon(Icons.mood),
                  ),
                  ButtonSegment(
                    value: 'hard',
                    label: Text('Ã°Å¸Å¸Â  Hard'),
                    icon: Icon(Icons.whatshot),
                  ),
                  ButtonSegment(
                    value: 'hardcore',
                    label: Text('Ã°Å¸â€Â´ Hardcore'),
                    icon: Icon(Icons.local_fire_department),
                  ),
                ],
                selected: {_difficulty},
                onSelectionChanged: (newSelection) {
                  setState(() {
                    _difficulty = newSelection.first;
