class DobbleLocalScreen extends StatefulWidget {
  final List<String> players;
  const DobbleLocalScreen({Key? key, required this.players}) : super(key: key);

  @override
  _DobbleLocalScreenState createState() => _DobbleLocalScreenState();
}

class _DobbleLocalScreenState extends State<DobbleLocalScreen> {
  List<List<String>> _deck = [];
  Map<String, List<String>> _playerCards = {};
  Map<String, int> _playerScores = {};
  List<String> _centerCard = [];
  bool _gameOver = false;
  String? _gameWinner;

  @override
  void initState() {
    super.initState();
    _startNewGame();
  }

  void _startNewGame() {
    final generatedCardsIndices = GameData.generateDobbleCards(8);
    List<List<String>> fullDeck =
        generatedCardsIndices.map((cardIndices) {
          return cardIndices
              .map((index) => GameData.dobbleSymbols[index])
              .toList();
        }).toList();
    fullDeck.shuffle();

    final initialScores = {for (var player in widget.players) player: 0};
    final initialPlayerCards = <String, List<String>>{};
    for (var player in widget.players) {
      if (fullDeck.isNotEmpty) {
        initialPlayerCards[player] = fullDeck.removeAt(0)..shuffle();
      }
    }

    final initialCenterCard =
        fullDeck.isNotEmpty ? (fullDeck.removeAt(0)..shuffle()) : <String>[];

    setState(() {
      _deck = fullDeck;
      _playerScores = initialScores;
      _playerCards = initialPlayerCards;
      _centerCard = initialCenterCard;
      _gameOver = initialCenterCard.isEmpty;
      _gameWinner = null;
    });
  }

  String? _findCommonSymbol(List<String> card1, List<String> card2) {
    final card2Symbols = card2.toSet();
    for (var symbol in card1) {
      if (card2Symbols.contains(symbol)) {
        return symbol;
      }
    }
    return null;
  }

  void _onCorrectGuess(String playerName, List<String> takenCard) {
    if (_gameOver) return;

    setState(() {
      HapticFeedback.lightImpact();
      _playerScores[playerName] = (_playerScores[playerName] ?? 0) + 1;
      _playerCards[playerName] = takenCard..shuffle();

      if (_deck.isNotEmpty) {
        _centerCard = _deck.removeAt(0)..shuffle();
      } else {
        _gameOver = true;
        _determineWinner();
      }
    });
  }

  void _determineWinner() {
    if (_playerScores.isEmpty) {
      _gameWinner = "Personne";
      return;
    }
    final sortedScores =
        _playerScores.entries.toList()
          ..sort((a, b) => b.value.compareTo(a.value));
    _gameWinner = sortedScores.first.key;
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: Text("Dobble Local"),
        actions: [
          IconButton(
            icon: Icon(Icons.info_outline),
            onPressed: () => showGameRules(context, 'Dobble'),
          ),
        ],
      ),
      body: _gameOver ? _buildGameOverUI() : _buildGameUI(),
    );
  }

  Widget _buildGameUI() {
    final screenWidth = MediaQuery.of(context).size.width;
    // Radius must fit within the square: radius + card half-height + name text < half container size
    final radius = (screenWidth / 2 - 90).clamp(60.0, 130.0);

    return Center(
      child: AspectRatio(
        aspectRatio: 1.0, // Garde la zone de jeu carrÃƒÂ©e
        child: Stack(
          alignment: Alignment.center,
          children: [
            Draggable<List<String>>(
              data: _centerCard,

              feedback: Opacity(
                opacity: 0.75,
                child: _buildDobbleCardWidget(_centerCard, isLarge: true),
              ),

              childWhenDragging: Opacity(
                opacity: 0.3,
                child: _buildDobbleCardWidget(_centerCard, isLarge: true),
              ),

              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  Text("Pioche (${_deck.length + 1})"),
                  _buildDobbleCardWidget(_centerCard, isLarge: true),
                ],
              ),
            ),

            ...List.generate(widget.players.length, (index) {
              final player = widget.players[index];
              final playerCard = _playerCards[player] ?? [];
              final angle = (2 * pi * index / widget.players.length) - (pi / 2);

              final x = radius * cos(angle);
              final y = radius * sin(angle);

              return Positioned(
                left: (screenWidth / 2) + x - 60,
                top: (screenWidth / 2) + y - 80, // un peu plus haut pour le nom
                child: DragTarget<List<String>>(
                  builder: (context, candidateData, rejectedData) {
                    return Column(
                      mainAxisSize: MainAxisSize.min,
                      children: [
                        Text(
                          "$player (${_playerScores[player]})",
                          style: Theme.of(context).textTheme.bodyLarge,
                        ),
                        SizedBox(height: 5),
                        _buildDobbleCardWidget(playerCard),
                      ],
                    );
                  },

                  onWillAccept: (draggedData) {
                    return _findCommonSymbol(playerCard, draggedData ?? []) !=
                        null;
                  },

                  onAccept: (draggedData) {
                    _onCorrectGuess(player, draggedData);
                  },
                ),
              );
            }),
          ],
        ),
      ),
    );
  }

  Widget _buildGameOverUI() {
    return Center(
      child: Card(
        child: Padding(
          padding: const EdgeInsets.all(24.0),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Text(
                "Partie TerminÃƒÂ©e !",
                style: Theme.of(context).textTheme.headlineMedium,
              ),
              SizedBox(height: 20),
              Text(
                "Le gagnant est",
                style: Theme.of(context).textTheme.titleLarge,
              ),
              Text(
                "$_gameWinner",
                style: Theme.of(
                  context,
                ).textTheme.headlineSmall?.copyWith(color: Colors.amberAccent),
              ),
              SizedBox(height: 20),
              ..._playerScores.entries
                  .map((e) => Text("${e.key}: ${e.value} points"))
                  .toList(),
              SizedBox(height: 30),
              ElevatedButton(onPressed: _startNewGame, child: Text("Rejouer")),
            ],
          ),
        ),
      ),
    );
  }

  Widget _buildDobbleCardWidget(List<String> symbols, {bool isLarge = false}) {
    final double cardSize = isLarge ? 150 : 100;
    final double symbolBaseSize = isLarge ? 28 : 20;
    final double radius = isLarge ? 55 : 35;

    if (symbols.isEmpty) {
      return Container(
        width: cardSize,
        height: cardSize,
        decoration: BoxDecoration(
          color: Colors.grey[800],
          shape: BoxShape.circle,
        ),
        child: Center(child: Text("Vide")),
      );
    }

    return Container(
      width: cardSize,
      height: cardSize,
      decoration: BoxDecoration(
        color: Colors.white,
        shape: BoxShape.circle,
        boxShadow: [
          BoxShadow(
            color: Colors.black.withOpacity(0.5),
            blurRadius: 8,
            spreadRadius: 2,
          ),
        ],
      ),
      child: Stack(
        alignment: Alignment.center,
        children: List.generate(symbols.length, (index) {
          final symbol = symbols[index];
          final random = Random(symbol.hashCode + index);
          final angle =
              (2 * pi * index / symbols.length) +
              (random.nextDouble() * 0.4 - 0.2);
          final distance = radius * (0.8 + random.nextDouble() * 0.2);
          final x = distance * cos(angle);
          final y = distance * sin(angle);
          final size = symbolBaseSize + (random.nextDouble() * 10 - 5);

          return Positioned(
            left: (cardSize / 2) + x - (size / 1.5),
            top: (cardSize / 2) + y - (size / 1.5),
            child: Transform.rotate(
              angle: random.nextDouble() * pi * 2,
              child: Text(
                symbol,
                style: TextStyle(fontSize: size),
                textAlign: TextAlign.center,
              ),
            ),
          );
        }),
      ),
    );
  }
}

// CLASSE D'ANIMATION POUR LES SYMBOLES DOBBLE
class _DobbleSymbolButton extends StatefulWidget {
  final String symbol;
  final double size;
  final VoidCallback? onTap;

  const _DobbleSymbolButton({
    Key? key,
    required this.symbol,
    required this.size,
    this.onTap,
  }) : super(key: key);

  @override
  __DobbleSymbolButtonState createState() => __DobbleSymbolButtonState();
}

class __DobbleSymbolButtonState extends State<_DobbleSymbolButton>
    with SingleTickerProviderStateMixin {
  late AnimationController _controller;
  late Animation<double> _scaleAnimation;

  @override
  void initState() {
    super.initState();
    _controller = AnimationController(
      vsync: this,
      duration: Duration(milliseconds: 100), // Animation trÃƒÂ¨s rapide (pop)
    );
    // L'emoji grossit de 1.0 ÃƒÂ  1.5 puis revient
    _scaleAnimation = Tween<double>(
      begin: 1.0,
      end: 1.5,
    ).animate(CurvedAnimation(parent: _controller, curve: Curves.easeInOut));
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  void _handleTap() {
    if (widget.onTap == null) return;

    // Jouer l'animation aller-retour
    _controller.forward().then((_) => _controller.reverse());

    // Appeler la logique du jeu
    widget.onTap!();
  }

  @override
  Widget build(BuildContext context) {
    return GestureDetector(
      onTap: _handleTap,
      behavior: HitTestBehavior.opaque,
      child: ScaleTransition(
        scale: _scaleAnimation,
        child: Text(
          widget.symbol,
          style: TextStyle(
            fontSize: widget.size,
            shadows: [
              Shadow(
                blurRadius: 2,
                color: Colors.black26,
                offset: Offset(1, 1),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

