// Helper pour dessiner le plateau circulaire avec de vraies cases
class _LudoBoardPainter extends CustomPainter {
  final List<Color> colors;

  _LudoBoardPainter(this.colors);

  @override
  void paint(Canvas canvas, Size size) {
    final cellSize = size.width / 15; // Grille 15x15 standard Ludo

    // Dessiner le fond blanc
    canvas.drawRect(
      Rect.fromLTWH(0, 0, size.width, size.height),
      Paint()..color = Colors.white,
    );

    // Dessiner les 4 bases (coins) - avec l'ordre de couleurs du Widget PetitsChevaux
    _drawHomeBase(
      canvas,
      Offset(0, 0),
      colors[0],
      cellSize,
    ); // Haut-Gauche (Rouge)
    _drawHomeBase(
      canvas,
      Offset(9 * cellSize, 0),
      colors[1],
      cellSize,
    ); // Haut-Droite (Bleu)
    _drawHomeBase(
      canvas,
      Offset(0, 9 * cellSize),
      colors[2],
      cellSize,
    ); // Bas-Gauche (Vert)
    _drawHomeBase(
      canvas,
      Offset(9 * cellSize, 9 * cellSize),
      colors[3],
      cellSize,
    ); // Bas-Droite (Jaune)

    // Dessiner le chemin central en croix (les cases individuelles)
    _drawCrossPath(canvas, cellSize, size);
  }

  void _drawHomeBase(
    Canvas canvas,
    Offset offset,
    Color color,
    double cellSize,
  ) {
    // Cadre extÃ©rieur
    canvas.drawRect(
      Rect.fromLTWH(offset.dx, offset.dy, 6 * cellSize, 6 * cellSize),
      Paint()..color = color,
    );
    // Zone intÃ©rieure blanche
    canvas.drawRect(
      Rect.fromLTWH(
        offset.dx + cellSize,
        offset.dy + cellSize,
        4 * cellSize,
        4 * cellSize,
      ),
      Paint()..color = Colors.white,
    );
    // 4 cercles pour les pions
    for (int i = 0; i < 2; i++) {
      for (int j = 0; j < 2; j++) {
        canvas.drawCircle(
          Offset(
            offset.dx + (1.5 + i * 2) * cellSize,
            offset.dy + (1.5 + j * 2) * cellSize,
          ),
          cellSize * 0.4,
          Paint()..color = color,
        );
      }
    }
  }

  void _drawCrossPath(Canvas canvas, double cellSize, Size size) {
    final strokePaint =
        Paint()
          ..color = Colors.black38
          ..style = PaintingStyle.stroke
          ..strokeWidth = 1.5;

    // Fonction pour dessiner une case
    void drawCell(int r, int c, {Color? fillColor, bool isStar = false}) {
      final rect = Rect.fromLTWH(
        c * cellSize,
        r * cellSize,
        cellSize,
        cellSize,
      );
      if (fillColor != null) {
        canvas.drawRect(rect, Paint()..color = fillColor);
      }
      canvas.drawRect(rect, strokePaint);
      if (isStar) {
        canvas.drawCircle(
          rect.center,
          cellSize * 0.3,
          Paint()..color = Colors.black26,
        );
      }
    }

    // Bras Gauche (Lignes 6 Ã  8, Colonnes 0 Ã  5)
    for (int r = 6; r <= 8; r++) {
      for (int c = 0; c <= 5; c++) {
        Color? fill;
        bool star = false;
        if (r == 7 && c > 0) fill = colors[0]; // Escaliers Rouges
        if (r == 6 && c == 1) fill = colors[0]; // DÃ©part Rouge
        if (r == 8 && c == 2) star = true; // Etoile
        drawCell(r, c, fillColor: fill, isStar: star);
      }
    }

    // Bras Haut (Lignes 0 Ã  5, Colonnes 6 Ã  8)
    for (int r = 0; r <= 5; r++) {
      for (int c = 6; c <= 8; c++) {
        Color? fill;
        bool star = false;
        if (c == 7 && r > 0) fill = colors[1]; // Escaliers Bleus
        if (c == 8 && r == 1) fill = colors[1]; // DÃ©part Bleu
        if (c == 6 && r == 2) star = true;
        drawCell(r, c, fillColor: fill, isStar: star);
      }
    }

    // Bras Droit (Lignes 6 Ã  8, Colonnes 9 Ã  14)
    for (int r = 6; r <= 8; r++) {
      for (int c = 9; c <= 14; c++) {
        Color? fill;
        bool star = false;
        if (r == 7 && c < 14) fill = colors[3]; // Escaliers Jaunes
        if (r == 8 && c == 13) fill = colors[3]; // DÃ©part Jaune
        if (r == 6 && c == 12) star = true;
        drawCell(r, c, fillColor: fill, isStar: star);
      }
    }

    // Bras Bas (Lignes 9 Ã  14, Colonnes 6 Ã  8)
    for (int r = 9; r <= 14; r++) {
      for (int c = 6; c <= 8; c++) {
        Color? fill;
        bool star = false;
        if (c == 7 && r < 14) fill = colors[2]; // Escaliers Verts
        if (c == 6 && r == 13) fill = colors[2]; // DÃ©part Vert
        if (c == 8 && r == 12) star = true;
        drawCell(r, c, fillColor: fill, isStar: star);
      }
    }

    _drawCenterTriangle(canvas, cellSize);
  }

  void _drawCenterTriangle(Canvas canvas, double cellSize) {
    final center = Offset(7.5 * cellSize, 7.5 * cellSize);
    // Triangle Rouge (Gauche)
    canvas.drawPath(
      Path()..addPolygon([
        Offset(6 * cellSize, 6 * cellSize),
        Offset(6 * cellSize, 9 * cellSize),
        center,
      ], true),
      Paint()..color = colors[0],
    );
    // Triangle Bleu (Haut)
    canvas.drawPath(
      Path()..addPolygon([
        Offset(6 * cellSize, 6 * cellSize),
        Offset(9 * cellSize, 6 * cellSize),
        center,
      ], true),
      Paint()..color = colors[1],
    );
    // Triangle Jaune (Droite)
    canvas.drawPath(
      Path()..addPolygon([
        Offset(9 * cellSize, 6 * cellSize),
        Offset(9 * cellSize, 9 * cellSize),
        center,
      ], true),
      Paint()..color = colors[3],
    );
    // Triangle Vert (Bas)
    canvas.drawPath(
      Path()..addPolygon([
        Offset(6 * cellSize, 9 * cellSize),
        Offset(9 * cellSize, 9 * cellSize),
        center,
      ], true),
      Paint()..color = colors[2],
    );
  }

  @override
  bool shouldRepaint(covariant CustomPainter oldDelegate) => false;
}

// 52 cases standard
const List<List<int>> _ludoPath = [
  [1, 6], [2, 6], [3, 6], [4, 6], [5, 6], // Bras gauche haut
  [6, 5], [6, 4], [6, 3], [6, 2], [6, 1], [6, 0], // Bras haut gauche
  [7, 0], [8, 0], // Tournant haut
  [8, 1], [8, 2], [8, 3], [8, 4], [8, 5], // Bras haut droit
  [9, 6], [10, 6], [11, 6], [12, 6], [13, 6], [14, 6], // Bras droit haut
  [14, 7], [14, 8], // Tournant droit
  [13, 8], [12, 8], [11, 8], [10, 8], [9, 8], // Bras droit bas
  [8, 9], [8, 10], [8, 11], [8, 12], [8, 13], [8, 14], // Bras bas droit
  [7, 14], [6, 14], // Tournant bas
  [6, 13], [6, 12], [6, 11], [6, 10], [6, 9], // Bras bas gauche
  [5, 8], [4, 8], [3, 8], [2, 8], [1, 8], [0, 8], // Bras gauche bas
  [0, 7], [0, 6], // Tournant gauche
];

Offset _getLudoPathPosition(int pos, int playerIndex, double cellSize) {
  final startOffsets = [0, 13, 39, 26]; // 0:Rouge, 1:Bleu, 2:Vert, 3:Jaune
  final actualPos = (pos + startOffsets[playerIndex]) % 52;
  final gridPos = _ludoPath[actualPos];
  return Offset((gridPos[0] + 0.5) * cellSize, (gridPos[1] + 0.5) * cellSize);
}

Offset _getLudoHomePosition(int pos, int playerIndex, double cellSize) {
  if (pos == 5) return Offset(7.5 * cellSize, 7.5 * cellSize); // Le centre
  int col = 0, row = 0;
  switch (playerIndex) {
    case 0:
      col = 1 + pos;
      row = 7;
      break; // Rouge, Escalier Gauche
    case 1:
      col = 7;
      row = 1 + pos;
      break; // Bleu, Escalier Haut
    case 2:
      col = 7;
      row = 13 - pos;
      break; // Vert, Escalier Bas
    case 3:
      col = 13 - pos;
      row = 7;
      break; // Jaune, Escalier Droit
  }
  return Offset((col + 0.5) * cellSize, (row + 0.5) * cellSize);
}

List<Widget> _buildLudoPawns(
  double size,
  Map<String, dynamic> positions,
  List<String> playerOrder,
  List<Color> colors,
  String myId,
  bool isMyTurn,
  int dice,
  bool hasRolled,
  String gameCode,
  FirebaseService firebaseService,
  bool
  isTeamMode, // NOUVEAU PARAMÃˆTRE ! Pensez Ã  le passer depuis _buildPetitsChevauxUI
) {
  List<Widget> pawns = [];
  final cellSize = size / 15;

  final Map<int, List<Offset>> homePositions = {
    0: [
      Offset(1.5, 1.5),
      Offset(3.5, 1.5),
      Offset(1.5, 3.5),
      Offset(3.5, 3.5),
    ], // Rouge
    1: [
      Offset(10.5, 1.5),
      Offset(12.5, 1.5),
      Offset(10.5, 3.5),
      Offset(12.5, 3.5),
    ], // Bleu
    2: [
      Offset(1.5, 10.5),
      Offset(3.5, 10.5),
      Offset(1.5, 12.5),
      Offset(3.5, 12.5),
    ], // Vert
    3: [
      Offset(10.5, 10.5),
      Offset(12.5, 10.5),
      Offset(10.5, 12.5),
      Offset(12.5, 12.5),
    ], // Jaune
  };

  int myPlayerIdx = playerOrder.indexOf(myId);

  for (int pIdx = 0; pIdx < playerOrder.length; pIdx++) {
    String ownerId = playerOrder[pIdx];
    List<int> pPos = List<int>.from(positions[ownerId]);
    Color pColor = colors[pIdx % 4];

    bool isMe = ownerId == myId;
    bool isTeammate = isTeamMode && !isMe && (myPlayerIdx % 2 == pIdx % 2);

    for (int pawnIdx = 0; pawnIdx < 4; pawnIdx++) {
      int pos = pPos[pawnIdx];
      double x = 0, y = 0;

      if (pos == -1) {
        final homePos = homePositions[pIdx % 4]![pawnIdx];
        x = homePos.dx * cellSize;
        y = homePos.dy * cellSize;
      } else if (pos <= 50) {
        final pathPos = _getLudoPathPosition(pos, pIdx % 4, cellSize);
        x = pathPos.dx;
        y = pathPos.dy;
      } else {
        final homePos = _getLudoHomePosition(pos - 51, pIdx % 4, cellSize);
        x = homePos.dx;
        y = homePos.dy;
      }

      // LOGIQUE VISUELLE : Puis-je cliquer sur ce pion ?
      bool canMove = false;
      if (isMyTurn && hasRolled && dice > 0) {
        if (isMe) {
          canMove = true;
        } else if (isTeammate) {
          // Aide l'alliÃ© Ã  sortir ou dans les escaliers
          if (pos == -1 && (dice == 1 || dice == 6)) canMove = true;
          if (pos > 50 && pos < 56) canMove = true;
        }
      }

      pawns.add(
        Positioned(
          left: x - 15,
          top: y - 15,
          child: GestureDetector(
            onTap:
                canMove
                    ? () {
                      firebaseService
                          .movePawnPetitsChevaux(
                            gameCode,
                            myId,
                            ownerId,
                            pawnIdx,
                          )
                          .catchError((e) {
                            print(e);
                          });
                    }
                    : null,
            child: Container(
              width: 30,
              height: 30,
              decoration: BoxDecoration(
                shape: BoxShape.circle,
                color: pColor,
                border: Border.all(
                  // Les pions jouables brillent en blanc
                  color: canMove ? Colors.white : Colors.black87,
                  width: canMove ? 3 : 1.5,
                ),
                boxShadow: [
                  BoxShadow(
                    color: Colors.black45,
                    blurRadius: 4,
                    offset: Offset(1, 2),
                  ),
                ],
              ),
              child: Center(
                child: Text(
                  "${pawnIdx + 1}",
                  style: TextStyle(
                    color: Colors.white,
                    fontWeight: FontWeight.bold,
                    fontSize: 12,
                    shadows: [Shadow(color: Colors.black, blurRadius: 2)],
                  ),
                ),
              ),
            ),
          ),
        ),
      );
    }
  }

  return pawns;
}

// â”€â”€â”€ ModÃ¨le d'une tuile posÃ©e â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
class PlacedTile {
  final String tile;
  final int matchEnd;
  final Offset position;
  final TileOrientation orientation;
  final bool flipped;

  const PlacedTile({
    required this.tile,
    required this.matchEnd,
    required this.position,
    required this.orientation,
    required this.flipped,
  });
}

enum TileOrientation { horizontal, vertical }

class LayoutResult {
  final List<PlacedTile> tiles;
  final Size boardSize;
  LayoutResult(this.tiles, this.boardSize);
}

// â”€â”€â”€ Moteur de layout (Vraie logique bout Ã  bout) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
class ChainLayoutEngine {
  static const double HALF_W = 24.0; // largeur d'une demi-tuile
  static const double HALF_H = 36.0; // hauteur d'une demi-tuile

  LayoutResult computeLayout(List<Map<String, dynamic>> chain) {
    List<PlacedTile> result = [];
    if (chain.isEmpty) return LayoutResult([], const Size(300, 200));

    int leftVal = -1, rightVal = -1;
    double leftX = 0.0, rightX = 0.0;

    for (int i = 0; i < chain.length; i++) {
      final entry = chain[i];
      final tileStr = entry['tile'] as String;
      final matchEnd = entry['matchEnd'] as int? ?? -1;
      final parts = tileStr.split('-');
      final a = int.parse(parts[0]);
      final b = int.parse(parts[1]);
      final isDouble = a == b;

      // Largeur physique de la tuile posÃ©e (un double se pose Ã  la verticale)
      final double tileWidth = isDouble ? HALF_W * 2 : HALF_W * 4;

      if (i == 0) {
        // Premier domino au centre (0,0)
        leftVal = a;
        rightVal = b;
        result.add(
          PlacedTile(
            tile: tileStr,
            matchEnd: -1,
            position: const Offset(0, 0),
            orientation:
                isDouble
                    ? TileOrientation.vertical
                    : TileOrientation.horizontal,
            flipped: false,
          ),
        );
        leftX = -(tileWidth / 2);
        rightX = (tileWidth / 2);
      } else {
        bool attachLeft = false;
        bool attachRight = false;

        if (matchEnd == leftVal && matchEnd == rightVal) {
          attachRight = true; // Si ambigu, on part Ã  droite
        } else if (matchEnd == leftVal) {
          attachLeft = true;
        } else if (matchEnd == rightVal) {
          attachRight = true;
        } else {
          attachRight = true; // Fallback
        }

        bool flipped = false;

        if (attachRight) {
          if (matchEnd == b) flipped = true;
          double cx = rightX + (tileWidth / 2);
          result.add(
            PlacedTile(
              tile: tileStr,
              matchEnd: matchEnd,
              position: Offset(cx, 0),
              orientation:
                  isDouble
                      ? TileOrientation.vertical
                      : TileOrientation.horizontal,
              flipped: flipped,
            ),
          );
          rightX += tileWidth;
          rightVal = flipped ? a : b;
        } else if (attachLeft) {
          if (matchEnd == a) flipped = true;
          double cx = leftX - (tileWidth / 2);
          result.add(
            PlacedTile(
              tile: tileStr,
              matchEnd: matchEnd,
              position: Offset(cx, 0),
              orientation:
                  isDouble
                      ? TileOrientation.vertical
                      : TileOrientation.horizontal,
              flipped: flipped,
            ),
          );
          leftX -= tileWidth;
          leftVal = flipped ? b : a;
        }
      }
    }

    // Centrer le tout pour que toutes les coordonnÃ©es soient positives
    if (result.isEmpty) return LayoutResult([], const Size(300, 200));

    double minX = result
        .map(
          (p) =>
              p.position.dx -
              (p.orientation == TileOrientation.vertical ? HALF_W : HALF_W * 2),
        )
        .reduce((a, b) => a < b ? a : b);
    double maxX = result
        .map(
          (p) =>
              p.position.dx +
              (p.orientation == TileOrientation.vertical ? HALF_W : HALF_W * 2),
        )
        .reduce((a, b) => a > b ? a : b);

    const double padding = 80.0;
    double totalWidth = (maxX - minX) + (padding * 2);
    double totalHeight = (HALF_H * 2) + (padding * 2);

    List<PlacedTile> shiftedResult =
        result.map((p) {
          return PlacedTile(
            tile: p.tile,
            matchEnd: p.matchEnd,
            // On recentre tout
            position: Offset(p.position.dx - minX + padding, totalHeight / 2),
            orientation: p.orientation,
            flipped: p.flipped,
          );
        }).toList();

    return LayoutResult(shiftedResult, Size(totalWidth, totalHeight));
  }
}

// â”€â”€â”€ Widget du plateau de jeu â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
class DominoesBoardWidget extends StatelessWidget {
  final List<Map<String, dynamic>> chain;

  const DominoesBoardWidget({super.key, required this.chain});

  @override
  Widget build(BuildContext context) {
    final engine = ChainLayoutEngine();
    final layout = engine.computeLayout(chain);

    return InteractiveViewer(
      minScale: 0.1,
      maxScale: 2.5,
      constrained: false, // Permet le scroll infini
      boundaryMargin: const EdgeInsets.all(double.infinity),
      child: SizedBox(
        width: layout.boardSize.width,
        height: layout.boardSize.height,
        child: Stack(
          alignment: Alignment.center,
          children:
              layout.tiles
                  .map(
                    (p) => Positioned(
                      left:
                          p.position.dx -
                          (p.orientation == TileOrientation.vertical
                              ? ChainLayoutEngine.HALF_W
                              : ChainLayoutEngine.HALF_W * 2),
                      top:
                          p.position.dy -
                          (p.orientation == TileOrientation.vertical
                              ? ChainLayoutEngine.HALF_W * 2
                              : ChainLayoutEngine.HALF_H),
                      child: _BoardTile(tile: p.tile, flipped: p.flipped),
                    ),
                  )
                  .toList(),
        ),
      ),
    );
  }
}

// â”€â”€â”€ Tuile sur le plateau â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
class _BoardTile extends StatelessWidget {
  final String tile;
  final bool flipped;

  const _BoardTile({required this.tile, required this.flipped});

  @override
  Widget build(BuildContext context) {
    final parts = tile.split('-');
    int a = int.parse(parts[0]);
    int b = int.parse(parts[1]);
    if (flipped) {
      int tmp = a;
      a = b;
      b = tmp;
    }
    final bool isDouble = a == b;

    return Container(
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(6),
        border: Border.all(
          color:
              isDouble ? Colors.amber.withOpacity(0.8) : Colors.grey.shade400,
          width: 1.5,
        ),
        boxShadow: const [
          BoxShadow(color: Colors.black26, blurRadius: 4, offset: Offset(2, 2)),
        ],
      ),
      child:
          isDouble
              ? Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  SizedBox(
                    width: ChainLayoutEngine.HALF_W * 2,
                    height: ChainLayoutEngine.HALF_W * 2,
                    child: _PipGrid(value: a),
                  ),
                  Container(
                    height: 1.5,
                    width: ChainLayoutEngine.HALF_W * 2,
                    color: Colors.grey.shade400,
                  ),
                  SizedBox(
                    width: ChainLayoutEngine.HALF_W * 2,
                    height: ChainLayoutEngine.HALF_W * 2,
                    child: _PipGrid(value: b),
                  ),
                ],
              )
              : Row(
                mainAxisSize: MainAxisSize.min,
                children: [
                  SizedBox(
                    width: ChainLayoutEngine.HALF_W * 2,
                    height: ChainLayoutEngine.HALF_H * 2,
                    child: _PipGrid(value: a),
                  ),
                  Container(
                    width: 1.5,
                    height: ChainLayoutEngine.HALF_H * 2,
                    color: Colors.grey.shade400,
                  ),
                  SizedBox(
                    width: ChainLayoutEngine.HALF_W * 2,
                    height: ChainLayoutEngine.HALF_H * 2,
                    child: _PipGrid(value: b),
                  ),
                ],
              ),
    );
  }
}

// â”€â”€â”€ Tuile en main (rack) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
class HandTileWidgetSimple extends StatefulWidget {
  final String tile;
  final bool isPlayable;
  final VoidCallback? onTap;

  const HandTileWidgetSimple({
    super.key,
    required this.tile,
    required this.isPlayable,
    this.onTap,
  });

  @override
  State<HandTileWidgetSimple> createState() => _HandTileWidgetSimpleState();
}

class _HandTileWidgetSimpleState extends State<HandTileWidgetSimple> {
  bool _pressed = false;

  @override
  Widget build(BuildContext context) {
    final parts = widget.tile.split('-');
    final int a = int.parse(parts[0]);
    final int b = int.parse(parts[1]);
    final bool isDouble = a == b;

    final double dy =
        _pressed
            ? -2.0
            : widget.isPlayable
            ? -10.0
            : 0.0;

    return GestureDetector(
      onTap: widget.onTap,
      onTapDown: (_) => setState(() => _pressed = true),
      onTapUp: (_) => setState(() => _pressed = false),
      onTapCancel: () => setState(() => _pressed = false),
      child: Padding(
        padding: const EdgeInsets.symmetric(horizontal: 4, vertical: 12),
        child: Transform.translate(
          offset: Offset(0, dy),
          child: Container(
            decoration: BoxDecoration(
              color: const Color(0xFFF5F0E8),
              borderRadius: BorderRadius.circular(6),
              border: Border.all(
                color:
                    widget.isPlayable
                        ? const Color(0xFF4ade80)
                        : Colors.grey.shade400,
                width: widget.isPlayable ? 2.5 : 1.5,
              ),
              boxShadow:
                  widget.isPlayable
                      ? [
                        BoxShadow(
                          color: const Color(0xFF4ade80).withOpacity(0.5),
                          blurRadius: 8,
                          offset: const Offset(0, 4),
                        ),
                      ]
                      : const [
                        BoxShadow(
                          color: Colors.black26,
                          blurRadius: 4,
                          offset: Offset(1, 2),
                        ),
                      ],
            ),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                SizedBox(
                  width: 40,
                  height: isDouble ? 40 : 60,
                  child: _PipGrid(value: a),
                ),
                Container(height: 1.5, width: 40, color: Colors.grey.shade400),
                SizedBox(
                  width: 40,
                  height: isDouble ? 40 : 60,
                  child: _PipGrid(value: b),
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }
}

// â”€â”€â”€ Nouveau rendu des points SANS GridView (ZÃ©ro crash) â”€â”€
class _PipGrid extends StatelessWidget {
  final int value;

  const _PipGrid({required this.value});

  @override
  Widget build(BuildContext context) {
    return CustomPaint(painter: _PipPainter(value), child: Container());
  }
}

class _PipPainter extends CustomPainter {
  final int value;
  _PipPainter(this.value);

  @override
  void paint(Canvas canvas, Size size) {
    final paint = Paint()..color = const Color(0xFF111111);
    final double r = size.width * 0.11; // Rayon du point
    final double padX = size.width * 0.28;
    final double padY = size.height * 0.28;
    final double cx = size.width / 2;
    final double cy = size.height / 2;

    void drawDot(double x, double y) =>
        canvas.drawCircle(Offset(x, y), r, paint);

    if (value == 1 || value == 3 || value == 5) drawDot(cx, cy); // Milieu
    if (value > 1) {
      drawDot(padX, padY); // Haut Gauche
      drawDot(size.width - padX, size.height - padY); // Bas Droite
    }
    if (value > 3) {
      drawDot(size.width - padX, padY); // Haut Droite
      drawDot(padX, size.height - padY); // Bas Gauche
    }
    if (value == 6) {
      drawDot(padX, cy); // Milieu Gauche
      drawDot(size.width - padX, cy); // Milieu Droite
    }
  }

  @override
  bool shouldRepaint(_PipPainter old) => old.value != value;
}

class FloatingChatOverlay extends StatefulWidget {
  final String gameCode;

  const FloatingChatOverlay({Key? key, required this.gameCode})
    : super(key: key);

  @override
  _FloatingChatOverlayState createState() => _FloatingChatOverlayState();
}

class _FloatingChatOverlayState extends State<FloatingChatOverlay> {
  final FirebaseService _firebaseService = FirebaseService();

  @override
  Widget build(BuildContext context) {
    return StreamBuilder<QuerySnapshot>(
      stream: _firebaseService.getChatStream(widget.gameCode, 'global'),
      builder: (context, snapshot) {
        if (!snapshot.hasData) return SizedBox.shrink();

        final messages = snapshot.data!.docs;
        // Ne garder que les 5 derniers messages qui ont moins de 10 secondes
        final recentMessages =
            messages.where((doc) {
              final data = doc.data() as Map<String, dynamic>;
              final Timestamp? time = data['timestamp'];
              if (time == null) return false;
              return DateTime.now().difference(time.toDate()).inSeconds < 10;
            }).toList();

        if (recentMessages.isEmpty) return SizedBox.shrink();

        return Container(
          width: double.infinity,
          height: double.infinity,
          padding: EdgeInsets.all(16),
          child: Column(
            mainAxisAlignment: MainAxisAlignment.center, // Afficher au milieu
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children:
                recentMessages.map((msgDoc) {
                  final msgData = msgDoc.data() as Map<String, dynamic>;
                  final sender = msgData['senderName'] ?? 'Joueur';
                  final text = msgData['text'] ?? '';
                  return AnimatedOpacity(
                    opacity: 1.0,
                    duration: Duration(seconds: 1),
                    child: SlideTransition(
                      position: Tween<Offset>(
                        begin: Offset(1, 0),
                        end: Offset(0, 0),
                      ).animate(AlwaysStoppedAnimation(1.0)),
                      child: Align(
                        alignment: Alignment.centerRight,
                        child: Container(
                          margin: EdgeInsets.symmetric(vertical: 4),
                          padding: EdgeInsets.symmetric(
                            horizontal: 12,
                            vertical: 8,
                          ),
                          decoration: BoxDecoration(
                            color: Colors.black.withOpacity(0.6),
                            borderRadius: BorderRadius.circular(16),
                          ),
                          child: Text(
                            "$sender: $text",
                            style: TextStyle(
                              color: Colors.white,
                              fontSize: 16,
                              shadows: [
                                Shadow(color: Colors.black, blurRadius: 2),
                              ],
                            ),
                          ),
                        ),
                      ),
                    ),
                  );
                }).toList(),
          ),
        );
      },
    );
  }
}

